## Exercise

**Task:** Implement two async JavaScript functions using the Web Crypto API:

1. `encrypt(plaintext, password)` → returns an object `{ salt, iv, ciphertext }` where all three fields are **base64** strings.
2. `decrypt(bundle, password)` → takes the bundle from `encrypt` and returns the original plaintext.

Requirements:
- Use **AES-256-GCM** (authenticated encryption).
- Derive the key from the password with **PBKDF2 + SHA-256** (100,000 iterations).
- Generate a fresh random **salt** (16 bytes) and **IV** (12 bytes) for every encryption.
- Round-trip must succeed: `decrypt(await encrypt("hello", "pw"), "pw") === "hello"`.

---

## Step-by-step solution

### 1. Helpers: encode/decode + base64 conversion
Text in JS is UTF-16 strings, but crypto operates on bytes. `TextEncoder`/`TextDecoder` handle UTF-8 conversion.  
Web Crypto returns `ArrayBuffer`/`Uint8Array`, so we need base64 helpers to serialize them.

```js
const enc = new TextEncoder();
const dec = new TextDecoder();

function toBase64(bytes) {
  // bytes: Uint8Array
  let binary = "";
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
}

function fromBase64(b64) {
  const binary = atob(b64);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) out[i] = binary.charCodeAt(i);
  return out;
}
```

> Note: `btoa`/`atob` exist in browsers and modern Node (v16+). For very large payloads, chunk the loop to avoid call-stack limits.

### 2. Derive an AES key from a password
Passwords are low-entropy; we must slow down brute force via PBKDF2 and a random salt.

```js
async function deriveKey(password, salt) {
  const keyMaterial = await crypto.subtle.importKey(
    "raw",
    enc.encode(password),
    { name: "PBKDF2" },
    false,
    ["deriveKey"]
  );

  return crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt,                 // Uint8Array
      iterations: 100_000,
      hash: "SHA-256",
    },
    keyMaterial,
    { name: "AES-GCM", length: 256 },
    false,                  // key not extractable
    ["encrypt", "decrypt"]
  );
}
```

### 3. Encrypt
Generate salt + IV, derive key, encrypt. GCM authenticates ciphertext, so tampering is detected on decrypt.

```js
async function encrypt(plaintext, password) {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const iv   = crypto.getRandomValues(new Uint8Array(12)); // 96-bit nonce for GCM
  const key  = await deriveKey(password, salt);

  const ciphertextBuf = await crypto.subtle.encrypt(
    { name: "AES-GCM", iv },
    key,
    enc.encode(plaintext)
  );

  return {
    salt: toBase64(salt),
    iv: toBase64(iv),
    ciphertext: toBase64(new Uint8Array(ciphertextBuf)),
  };
}
```

### 4. Decrypt
Re-derive the same key using the stored salt, then decrypt. `decrypt` throws if the password is wrong or data was tampered.

```js
async function decrypt(bundle, password) {
  const salt = fromBase64(bundle.salt);
  const iv   = fromBase64(bundle.iv);
  const ct   = fromBase64(bundle.ciphertext);

  const key = await deriveKey(password, salt);

  const plaintextBuf = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv },
    key,
    ct
  );

  return dec.decode(plaintextBuf);
}
```

### 5. Round-trip test

```js
(async () => {
  const bundle = await encrypt("hello, crypto!", "correct horse battery staple");
  console.log("bundle:", bundle);

  const out = await decrypt(bundle, "correct horse battery staple");
  console.log("decrypted:", out); // "hello, crypto!"

  // Tamper / wrong password should throw:
  try {
    await decrypt(bundle, "wrong password");
    console.log("ERROR: should have thrown");
  } catch (e) {
    console.log("expected failure on bad password:", e.name);
  }
})();
```

---

## Final complete solution

```js
const enc = new TextEncoder();
const dec = new TextDecoder();

function toBase64(bytes) {
  let binary = "";
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary);
}

function fromBase64(b64) {
  const binary = atob(b64);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) out[i] = binary.charCodeAt(i);
  return out;
}

async function deriveKey(password, salt) {
  const keyMaterial = await crypto.subtle.importKey(
    "raw",
    enc.encode(password),
    { name: "PBKDF2" },
    false,
    ["deriveKey"]
  );

  return crypto.subtle.deriveKey(
    { name: "PBKDF2", salt, iterations: 100_000, hash: "SHA-256" },
    keyMaterial,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"]
  );
}

async function encrypt(plaintext, password) {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const iv   = crypto.getRandomValues(new Uint8Array(12));
  const key  = await deriveKey(password, salt);

  const ct = await crypto.subtle.encrypt(
    { name: "AES-GCM", iv },
    key,
    enc.encode(plaintext)
  );

  return {
    salt: toBase64(salt),
    iv: toBase64(iv),
    ciphertext: toBase64(new Uint8Array(ct)),
  };
}

async function decrypt(bundle, password) {
  const salt = fromBase64(bundle.salt);
  const iv   = fromBase64(bundle.iv);
  const ct   = fromBase64(bundle.ciphertext);

  const key = await deriveKey(password, salt);

  const pt = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv },
    key,
    ct
  );

  return dec.decode(pt);
}

// Demo
(async () => {
  const bundle = await encrypt("hello, crypto!", "secret passphrase");
  console.log(bundle);
  console.log(await decrypt(bundle, "secret passphrase"));
})();
```

### Why this is “basic but correct”
- **Authenticated encryption (GCM):** ciphertext includes an auth tag; wrong password or tampering throws.
- **PBKDF2 + salt:** slows password guessing; unique salt per message prevents rainbow tables.
- **Fresh IV per message:** essential for GCM security; never reuse an IV with the same key.
- **Key not extractable:** `deriveKey` sets `extractable: false`, reducing leakage risk.

### Caveats / next steps
- Base64 expansion + PBKDF2 at 100k iterations can be CPU-heavy in browsers—fine for small messages.
- For production, consider Argon2id (via WASM) instead of PBKDF2, and store/verify a key check rather than raw passwords.
- IVs need not be secret but must be unique; 12 random bytes is standard for GCM.
- For large files, stream with chunked encryption rather than loading everything into memory.

## Cryptography basics (interview framing)

In JavaScript, “crypto” usually means:

- **Hashing**: one-way function (`SHA-256`). Used for integrity, passwords (with salt + slow KDF), fingerprints. Not reversible.
- **Symmetric encryption**: same key encrypts/decrypts (`AES-GCM`). Fast; used for bulk data. Needs a **nonce/IV** that must never repeat for the same key.
- **Asymmetric encryption / signing**: key pair (`RSA`, `ECDSA`, `Ed25519`). Public key can be shared; private key stays secret. Used for key exchange, signatures, identity.
- **Authentication (AEAD)**: `AES-GCM` gives confidentiality **and** integrity. A tag verifies tampering.
- **Key derivation**: turn passwords into keys with a slow function (`PBKDF2`, `scrypt`, `Argon2`) + salt.
- **Encoding vs encryption**: Base64/Hex are encodings, not security.

**Golden rule in interviews:** never roll your own crypto for production; use `crypto.subtle` (Web Crypto) or a vetted library. Below, I wrap the real API cleanly and add a *toy* cipher only to illustrate the concept.

---

## Clean implementation

```js
// cryptoBasics.js
// Production-safe wrappers around the Web Crypto API + tiny educational examples.

const enc = new TextEncoder();
const dec = new TextDecoder();

class CryptoBasics {
  // ---------- helpers ----------
  static bufferToHex(buf) {
    return [...new Uint8Array(buf)]
      .map((b) => b.toString(16).padStart(2, '0'))
      .join('');
  }

  static bufferToBase64(buf) {
    const bytes = new Uint8Array(buf);
    let bin = '';
    for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
    return btoa(bin);
  }

  static base64ToBuffer(b64) {
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes.buffer;
  }

  // ---------- hashing ----------
  // One-way digest. Same input -> same output.
  static async sha256(message) {
    const data = enc.encode(message);
    const hash = await crypto.subtle.digest('SHA-256', data);
    return this.bufferToHex(hash);
  }

  // ---------- symmetric: AES-GCM ----------
  // Generate a 256-bit key. Keep it secret; never hard-code in client bundles.
  static async generateAesKey() {
    return crypto.subtle.generateKey(
      { name: 'AES-GCM', length: 256 },
      true, // extractable (set false in production if you don't need export)
      ['encrypt', 'decrypt']
    );
  }

  // Encrypts text, returns { iv, ciphertext } (both base64).
  // IV must be unique per (key, message). GCM with 96-bit (12-byte) IV.
  static async aesEncrypt(plaintext, key) {
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const ct = await crypto.subtle.encrypt(
      { name: 'AES-GCM', iv },
      key,
      enc.encode(plaintext)
    );
    return {
      iv: this.bufferToBase64(iv.buffer),
      ciphertext: this.bufferToBase64(ct),
    };
  }

  static async aesDecrypt({ iv, ciphertext }, key) {
    const pt = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: this.base64ToBuffer(iv) },
      key,
      this.base64ToBuffer(ciphertext)
    );
    return dec.decode(pt);
  }

  // ---------- asymmetric: RSA-OAEP encryption ----------
  static async generateRsaKeyPair() {
    return crypto.subtle.generateKey(
      {
        name: 'RSA-OAEP',
        modulusLength: 2048,
        publicExponent: new Uint8Array([1, 0, 1]),
        hash: 'SHA-256',
      },
      true,
      ['encrypt', 'decrypt']
    );
  }

  static async rsaEncrypt(plaintext, publicKey) {
    const ct = await crypto.subtle.encrypt(
      { name: 'RSA-OAEP' },
      publicKey,
      enc.encode(plaintext)
    );
    return this.bufferToBase64(ct);
  }

  static async rsaDecrypt(ciphertextB64, privateKey) {
    const pt = await crypto.subtle.decrypt(
      { name: 'RSA-OAEP' },
      privateKey,
      this.base64ToBuffer(ciphertextB64)
    );
    return dec.decode(pt);
  }

  // ---------- asymmetric: ECDSA signing ----------
  static async generateEcdsaKeyPair() {
    return crypto.subtle.generateKey(
      { name: 'ECDSA', namedCurve: 'P-256' },
      true,
      ['sign', 'verify']
    );
  }

  static async ecdsaSign(message, privateKey) {
    const sig = await crypto.subtle.sign(
      { name: 'ECDSA', hash: 'SHA-256' },
      privateKey,
      enc.encode(message)
    );
    return this.bufferToBase64(sig);
  }

  static async ecdsaVerify(message, signatureB64, publicKey) {
    return crypto.subtle.verify(
      { name: 'ECDSA', hash: 'SHA-256' },
      publicKey,
      this.base64ToBuffer(signatureB64),
      enc.encode(message)
    );
  }

  // ---------- key derivation from password ----------
  // PBKDF2: slow-ish, salted. Use Argon2/scrypt in production if available.
  static async deriveKeyFromPassword(password, saltB64, iterations = 100_000) {
    const salt = saltB64
      ? this.base64ToBuffer(saltB64)
      : crypto.getRandomValues(new Uint8Array(16)).buffer;

    const baseKey = await crypto.subtle.importKey(
      'raw',
      enc.encode(password),
      'PBKDF2',
      false,
      ['deriveKey']
    );

    const key = await crypto.subtle.deriveKey(
      { name: 'PBKDF2', salt, iterations, hash: 'SHA-256' },
      baseKey,
      { name: 'AES-GCM', length: 256 },
      true,
      ['encrypt', 'decrypt']
    );

    return { key, salt: this.bufferToBase64(salt) };
  }

  // ---------- educational only (NOT secure) ----------
  // Repeating-key XOR to illustrate symmetric idea. Never use for real data.
  static xorCipher(text, key) {
    if (!key) throw new Error('key required');
    const out = [];
    for (let i = 0; i < text.length; i++) {
      out.push(String.fromCharCode(text.charCodeAt(i) ^ key.charCodeAt(i % key.length)));
    }
    return out.join('');
  }
}

// ---------------- usage demo ----------------
(async () => {
  // Hash
  console.log('sha256("hi")', await CryptoBasics.sha256('hi'));

  // Symmetric
  const aesKey = await CryptoBasics.generateAesKey();
  const encObj = await CryptoBasics.aesEncrypt('secret message', aesKey);
  console.log('decrypted:', await CryptoBasics.aesDecrypt(encObj, aesKey));

  // Asymmetric encryption
  const rsa = await CryptoBasics.generateRsaKeyPair();
  const rsaCt = await CryptoBasics.rsaEncrypt('hello rsa', rsa.publicKey);
  console.log('rsa decrypted:', await CryptoBasics.rsaDecrypt(rsaCt, rsa.privateKey));

  // Signing
  const ecdsa = await CryptoBasics.generateEcdsaKeyPair();
  const sig = await CryptoBasics.ecdsaSign('sign me', ecdsa.privateKey);
  console.log('verify:', await CryptoBasics.ecdsaVerify('sign me', sig, ecdsa.publicKey));

  // Password-derived key
  const { key: pwdKey, salt } = await CryptoBasics.deriveKeyFromPassword('hunter2', null);
  const pwdEnc = await CryptoBasics.aesEncrypt('top secret', pwdKey);
  console.log('pwd decrypted:', await CryptoBasics.aesDecrypt(pwdEnc, pwdKey));

  // Toy cipher (educational)
  const x = CryptoBasics.xorCipher('hello', 'key');
  console.log('xor roundtrip:', CryptoBasics.xorCipher(x, 'key'));
})();

export default CryptoBasics;
```

### Interview talking points to mention
- **IV/nonce**: must be unique per key; random 96-bit IV is standard for GCM.
- **Authenticated encryption**: GCM verifies integrity; don’t use unauthenticated modes like raw CBC for new designs.
- **Key management**: where keys live (HSM, KMS, not in source), rotation, least privilege.
- **Passwords**: never store plaintext; store salt + slow hash (Argon2id preferred); use constant-time compare.
- **RSA vs ECC**: ECC gives similar security with smaller keys; prefer ECDSA/Ed25519 today.
- **Threats**: replay attacks, nonce reuse, padding oracles, weak randomness.

If you want, I can also implement a **toy SHA-256-like compression** or a **mini RSA with BigInt** purely for algorithm intuition—but emphasize it’s not production-safe.

Below are practical edge cases that bite people when using the Web Crypto API (`crypto.subtle`) or Node’s `crypto` module, with idiomatic fixes.

---

### 1. Encoding: Text ↔ Bytes (UTF-8, hex, base64)

**Edge cases**
- `btoa`/`atob` only handle Latin-1; Unicode throws or corrupts.
- Hex/base64 padding and odd-length strings.
- Empty inputs and zero-length buffers.

```js
// Safe UTF-8 + base64 helpers
const enc = new TextEncoder();
const dec = new TextDecoder();

function bytesToBase64(bytes) {
  // Chunk to avoid call-stack limits on large buffers
  let binary = '';
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunk));
  }
  return btoa(binary);
}

function base64ToBytes(b64) {
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

function bytesToHex(bytes) {
  return [...bytes].map(b => b.toString(16).padStart(2, '0')).join('');
}

function hexToBytes(hex) {
  if (hex.length % 2) throw new Error('Odd hex length');
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  return out;
}

// Edge: empty string round-trips
const empty = enc.encode('');
console.log(dec.decode(empty)); // ''
```

---

### 2. Randomness: Never use `Math.random`

**Edge cases**
- `Math.random` is not cryptographically secure.
- `getRandomValues` has a per-call byte limit (65,536 in browsers).
- Bias when reducing modulo a non-power-of-two range.

```js
function secureRandomBytes(n) {
  const out = new Uint8Array(n);
  // Chunk if needed
  for (let i = 0; i < n; i += 65536) {
    crypto.getRandomValues(out.subarray(i, Math.min(i + 65536, n)));
  }
  return out;
}

// Unbiased random integer in [0, max) using rejection sampling
function secureRandomInt(max) {
  if (!Number.isInteger(max) || max <= 0) throw new RangeError('max must be positive int');
  const range = 0x100000000; // 2^32
  const limit = range - (range % max);
  let x;
  do {
    x = crypto.getRandomValues(new Uint32Array(1))[0];
  } while (x >= limit);
  return x % max;
}
```

---

### 3. Keys: Generation, Import, and Extractability

**Edge cases**
- Forgetting `extractable: false` (keys leak into JS heap).
- Algorithm/usage mismatch at import time.
- Raw vs JWK format confusion.
- Derived keys with wrong salt/iterations.

```js
// Generate a non-extractable AES-GCM key
const key = await crypto.subtle.generateKey(
  { name: 'AES-GCM', length: 256 },
  false,                       // extractable = false
  ['encrypt', 'decrypt']
);

// Import a raw key (e.g., from server)
async function importAesKey(rawBytes) {
  return crypto.subtle.importKey(
    'raw',
    rawBytes,
    { name: 'AES-GCM' },
    false,
    ['encrypt', 'decrypt']
  );
}

// Derive a key with PBKDF2 (note: use Argon2 in Node for passwords; browser has no native Argon2)
async function deriveKey(password, salt, iterations = 600_000) {
  const baseKey = await crypto.subtle.importKey(
    'raw',
    enc.encode(password),
    'PBKDF2',
    false,
    ['deriveKey']
  );
  return crypto.subtle.deriveKey(
    { name: 'PBKDF2', salt, iterations, hash: 'SHA-256' },
    baseKey,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt']
  );
}
```

---

### 4. IV / Nonce Management (Critical)

**Edge cases**
- Reusing an IV with the same key in AES-GCM is catastrophic (forgeries).
- IV length: 96 bits (12 bytes) is the recommended size for GCM.
- Counter/nonce must never repeat; random 96-bit is usually safe but check quotas.
- Storing IV alongside ciphertext is fine (it’s not secret), but it must be authenticated or bound.

```js
async function encryptAesGcm(key, plaintext, aad = new Uint8Array(0)) {
  const iv = secureRandomBytes(12); // 96-bit
  const ct = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv, additionalData: aad, tagLength: 128 },
    key,
    plaintext
  );
  // Prepend IV so decrypt can recover it
  const out = new Uint8Array(iv.length + ct.byteLength);
  out.set(iv, 0);
  out.set(new Uint8Array(ct), iv.length);
  return out;
}

async function decryptAesGcm(key, blob, aad = new Uint8Array(0)) {
  const iv = blob.slice(0, 12);
  const ct = blob.slice(12);
  return crypto.subtle.decrypt(
    { name: 'AES-GCM', iv, additionalData: aad, tagLength: 128 },
    key,
    ct
  );
}
```

---

### 5. Authenticated Encryption & Tampering

**Edge cases**
- Using unauthenticated modes (CBC/CTR) without a MAC → malleability.
- Forgetting `additionalData` (AAD) when context matters.
- Truncating or modifying ciphertext without detection.

```js
// AES-GCM fails (throws) if tag doesn't verify — do not catch and ignore
try {
  const pt = await decryptAesGcm(key, tamperedBlob);
} catch (e) {
  // DOMException: OperationError — treat as attack or corruption
  console.error('Decryption failed (auth tag mismatch)');
}

// If you must use legacy CBC, add HMAC in Encrypt-then-MAC order
// (Web Crypto has no built-in EtM helper; prefer GCM/ChaCha20-Poly1305)
```

---

### 6. Constant-Time Comparison (Timing Leaks)

**Edge cases**
- `===` on strings/buffers leaks length and content via timing.
- HMAC comparison must be constant-time.

```js
function constantTimeEqual(a, b) {
  if (a.length !== b.length) return false; // length leak is usually acceptable for fixed-size tags
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i];
  return diff === 0;
}

// Compare two MACs safely
const mac1 = new Uint8Array(await crypto.subtle.sign('HMAC', key, data1));
const mac2 = new Uint8Array(await crypto.subtle.sign('HMAC', key, data2));
if (!constantTimeEqual(mac1, mac2)) throw new Error('MAC mismatch');
```

---

### 7. Platform Differences: Browser vs Node

**Edge cases**
- Node’s `crypto` is sync-ish and buffer-based; Web Crypto is async and ArrayBuffer-based.
- Node supports algorithms browsers don’t (e.g., Argon2 in newer versions, scrypt).
- `Buffer` vs `Uint8Array` views and detachment.

```js
// Node (v18+): use webcrypto for portability
import { webcrypto } from 'node:crypto';
const { subtle } = webcrypto;

// Convert Node Buffer <-> Uint8Array without copying when possible
function toUint8(buf) {
  return new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
}

// Detached ArrayBuffer guard
function safeView(buf) {
  if (buf.byteLength === 0 && buf.buffer.byteLength > 0) {
    // detached / neutered
    throw new Error('ArrayBuffer detached');
  }
  return new Uint8Array(buf);
}
```

---

### 8. Key Storage & Export

**Edge cases**
- Exporting extractable keys to IndexedDB/localStorage in plaintext.
- JWK `k` field is base64url, not standard base64.
- Losing the IV/salt alongside the key makes data unrecoverable.

```js
// Safe export pattern: wrap key with a KEK (key-wrapping)
async function wrapKey(keyToWrap, wrappingKey) {
  return crypto.subtle.wrapKey('raw', keyToWrap, wrappingKey, {
    name: 'AES-KW', length: 256
  });
}

// JWK import (note base64url)
async function importJwk(jwk) {
  return crypto.subtle.importKey('jwk', jwk, { name: 'ECDSA', namedCurve: 'P-256' }, false, ['verify']);
}
```

---

### 9. Large Data / Streaming

**Edge cases**
- Web Crypto operates on whole ArrayBuffers; huge inputs block the main thread.
- Chunking breaks AEAD unless you use a streaming construction (not standard).
- Memory blow-up on multi-GB files.

```js
// Chunked encryption is NOT safe with standard AES-GCM (each chunk needs unique IV + auth)
// For large files, use a streaming AEAD library (e.g., libsodium secretstream) or
// encrypt per-chunk with a derived per-chunk key + counter IV, then MAC the whole.

// Minimal illustrative pattern: derive per-chunk key (NOT production-ready)
async function encryptChunks(masterKey, chunks) {
  const out = [];
  for (let i = 0; i < chunks.length; i++) {
    const iv = new Uint8Array(12);
    new DataView(iv.buffer).setUint32(8, i, false); // counter-style IV; ensure uniqueness
    const ct = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, masterKey, chunks[i]);
    out.push({ iv, ct });
  }
  return out;
}
```

---

### 10. Password Hashing (Do Not Encrypt Passwords)

**Edge cases**
- Using AES/SHA-256 for passwords → instant brute force.
- No salt → rainbow tables.
- Fast hashes (SHA-256) are wrong for passwords.

```js
// Browser: PBKDF2 (minimum 600k iterations SHA-256) — better to do server-side
async function hashPassword(pw, salt) {
  const key = await crypto.subtle.importKey('raw', enc.encode(pw), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits(
    { name: 'PBKDF2', salt, iterations: 600_000, hash: 'SHA-256' },
    key,
    256
  );
  return new Uint8Array(bits);
}

// Node: prefer scrypt or Argon2
import { scrypt } from 'node:crypto';
function hashPasswordNode(pw, salt) {
  return new Promise((res, rej) =>
    scrypt(pw, salt, 64, { N: 16384, r: 8, p: 1 }, (err, buf) => err ? rej(err) : res(buf))
  );
}
```

---

### 11. SubtleCrypto Async & Error Handling

**Edge cases**
- Operations reject with `DOMException`; unhandled rejections crash.
- `crypto.subtle` is `undefined` in insecure contexts (HTTP, not localhost).
- Keys from different realms (iframes) may not be usable.

```js
if (!globalThis.crypto?.subtle) {
  throw new Error('Web Crypto unavailable (need HTTPS or localhost)');
}

async function safeEncrypt(key, data) {
  try {
    return await crypto.subtle.encrypt({ name: 'AES-GCM', iv: secureRandomBytes(12) }, key, data);
  } catch (e) {
    if (e.name === 'OperationError') return null; // auth failure or bad key
    throw e;
  }
}
```

---

### 12. Common Mistakes Summary

| Mistake | Fix |
|---|---|
| `Math.random()` for keys/IVs | `crypto.getRandomValues` |
| Reusing IV with AES-GCM | Fresh random IV per message |
| CBC without MAC | Use GCM or EtM |
| `===` on MACs | Constant-time compare |
| SHA-256 for passwords | PBKDF2/Argon2/scrypt |
| Storing keys in localStorage | Non-extractable keys + wrap with KEK |
| Ignoring detached ArrayBuffers | Re-slice before use |
| Assuming sync crypto | `await` all subtle ops |

---

### Minimal End-to-End Example (Browser)

```js
async function demo() {
  const key = await crypto.subtle.generateKey(
    { name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']
  );
  const msg = enc.encode('hello, crypto');
  const blob = await encryptAesGcm(key, msg);
  const out = await decryptAesGcm(key, blob);
  console.log(dec.decode(out)); // 'hello, crypto'
}
```

If you want, I can tailor this to Node-only, Deno, or a specific library (e.g., libsodium, Web Crypto polyfills).

Custom exceptions in JavaScript are usually created by subclassing the built-in `Error` (or one of its subclasses). The modern, idiomatic way is an ES6 `class` with `extends Error`. A few details matter for correctness:

- Call `super(message)` so `this.message` and the stack are initialized.
- Set `this.name` to the class name so logs identify the error type.
- Optionally attach a stable `code` (string) in addition to/independent of `instanceof` — this is safer across realms/bundles.
- In Node.js, use `Error.captureStackTrace` to keep the stack clean.
- Make errors serializable (`toJSON`) and provide subclass-specific context.

Below is a complete, runnable example. It defines a base `AppError` plus several domain-specific subclasses, then demonstrates throwing, catching, `instanceof` checks, code-based checks, async handling, rethrowing, and serialization.

```js
// custom-errors.js
// Run with: node custom-errors.js

'use strict';

/* ------------------------------------------------------------------ */
/* Base application error                                              */
/* ------------------------------------------------------------------ */
class AppError extends Error {
  /**
   * @param {string} message  Human-readable description
   * @param {string} code     Stable machine-readable code (e.g. "NOT_FOUND")
   * @param {number} statusCode HTTP-ish status code for APIs
   */
  constructor(message, code, statusCode = 500) {
    super(message);

    // Keep the constructor name as the error name for nice stack traces.
    this.name = this.constructor.name;

    this.code = code;
    this.statusCode = statusCode;

    // V8 (Node.js / Chrome) only. Removes this constructor from the stack.
    if (typeof Error.captureStackTrace === 'function') {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  // Useful when sending errors over the wire / logging as JSON.
  toJSON() {
    return {
      name: this.name,
      message: this.message,
      code: this.code,
      statusCode: this.statusCode,
      stack: this.stack,
    };
  }
}

/* ------------------------------------------------------------------ */
/* Domain-specific errors                                               */
/* ------------------------------------------------------------------ */
class ValidationError extends AppError {
  constructor(message, field, value) {
    super(message, 'VALIDATION_ERROR', 400);
    this.field = field;
    this.value = value;
  }
}

class NotFoundError extends AppError {
  constructor(resource, id) {
    super(
      `${resource} not found${id !== undefined ? ` (id: ${id})` : ''}`,
      'NOT_FOUND',
      404
    );
    this.resource = resource;
    this.id = id;
  }
}

class AuthenticationError extends AppError {
  constructor(message = 'Authentication required') {
    super(message, 'AUTHENTICATION_ERROR', 401);
  }
}

class ConflictError extends AppError {
  constructor(message, conflictingField) {
    super(message, 'CONFLICT', 409);
    this.conflictingField = conflictingField;
  }
}

/* ------------------------------------------------------------------ */
/* Fake "database" / services                                           */
/* ------------------------------------------------------------------ */
const users = new Map([
  [1, { id: 1, email: 'alice@example.com', role: 'admin' }],
  [2, { id: 2, email: 'bob@example.com', role: 'user' }],
]);

function findUser(id) {
  const user = users.get(id);
  if (!user) throw new NotFoundError('User', id);
  return user;
}

function createUser({ email, role }) {
  // validation
  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw new ValidationError('Invalid email address', 'email', email);
  }
  if (!['admin', 'user'].includes(role)) {
    throw new ValidationError('Role must be admin or user', 'role', role);
  }
  // conflict check
  for (const u of users.values()) {
    if (u.email === email) {
      throw new ConflictError('Email already in use', 'email');
    }
  }
  const id = users.size + 1;
  const user = { id, email, role };
  users.set(id, user);
  return user;
}

function deleteUser(requesterId, targetId) {
  const requester = findUser(requesterId);
  if (requester.role !== 'admin') {
    throw new AuthenticationError('Only admins may delete users');
  }
  const target = findUser(targetId);
  users.delete(target.id);
  return target;
}

/* ------------------------------------------------------------------ */
/* Async helper to show error propagation                               */
/* ------------------------------------------------------------------ */
async function fetchUserAsync(id) {
  // Simulate async IO
  await new Promise((r) => setTimeout(r, 10));
  return findUser(id); // may throw NotFoundError
}

/* ------------------------------------------------------------------ */
/* Error handling helpers                                               */
/* ------------------------------------------------------------------ */
function handleError(err) {
  // Prefer code-based checks for cross-realm safety; instanceof for local code.
  if (err instanceof AppError) {
    console.error(`[AppError ${err.code}] ${err.message}`);
    if (err instanceof ValidationError) {
      console.error(`  -> field: ${err.field}, value: ${JSON.stringify(err.value)}`);
    }
    if (err instanceof NotFoundError) {
      console.error(`  -> resource: ${err.resource}, id: ${err.id}`);
    }
    return err.statusCode;
  }

  // Unknown / programmer error: log full stack and fail loudly.
  console.error('[UnexpectedError]', err);
  return 500;
}

/* ------------------------------------------------------------------ */
/* Demo                                                                 */
/* ------------------------------------------------------------------ */
function main() {
  console.log('--- 1. Successful create ---');
  console.log(createUser({ email: 'carol@example.com', role: 'user' }));

  console.log('\n--- 2. ValidationError (bad email) ---');
  try {
    createUser({ email: 'not-an-email', role: 'user' });
  } catch (e) {
    handleError(e);
  }

  console.log('\n--- 3. ConflictError ---');
  try {
    createUser({ email: 'alice@example.com', role: 'user' });
  } catch (e) {
    handleError(e);
  }

  console.log('\n--- 4. NotFoundError ---');
  try {
    findUser(999);
  } catch (e) {
    handleError(e);
    console.log('  instanceof NotFoundError:', e instanceof NotFoundError);
    console.log('  code === "NOT_FOUND":', e.code === 'NOT_FOUND');
  }

  console.log('\n--- 5. AuthenticationError ---');
  try {
    deleteUser(2, 1); // bob is not admin
  } catch (e) {
    handleError(e);
  }

  console.log('\n--- 6. Async propagation ---');
  fetchUserAsync(42)
    .then((u) => console.log('Found:', u))
    .catch((e) => {
      handleError(e);
      // Re-throwing after logging is common at boundaries:
      // throw e;
    });

  console.log('\n--- 7. JSON serialization ---');
  try {
    findUser(7);
  } catch (e) {
    console.log(JSON.stringify(e.toJSON(), null, 2));
  }

  console.log('\n--- 8. code-based dispatch (cross-realm safe) ---');
  try {
    findUser(123);
  } catch (e) {
    // Dispatch by code instead of instanceof when crossing module/realm boundaries.
    switch (e.code) {
      case 'NOT_FOUND':
        console.log('Handled as 404');
        break;
      case 'VALIDATION_ERROR':
        console.log('Handled as 400');
        break;
      default:
        console.log('Handled as 500');
    }
  }
}

main();
```

### Key takeaways

1. **Subclassing `Error`** is the standard mechanism. Class syntax ensures `instanceof` and prototype chains work correctly in modern engines.
2. **Always set `name`**; otherwise all errors log as `Error`.
3. **Use stable `code` strings** as a secondary identification mechanism — `instanceof` can break across iframes/VMs, bundled copies, or transpilation.
4. **`Error.captureStackTrace`** (V8) keeps the stack pointing at the *throw site*, not your error class.
5. **Differentiate operational vs. programmer errors**: throw your custom errors for *expected* domain failures (validation, not found, auth). Let unexpected bugs (null deref, type errors) propagate as normal `Error`s and crash/restart the process or surface as 500s.
6. **Async errors** propagate normally through Promises and `async/await`; attach `.catch` or `try/await/catch`.
7. **Serialization**: built-in `Error` objects don't serialize well (`JSON.stringify` drops non-enumerable props like `stack`); a `toJSON` method fixes that.

### ES5 / transpilation caveat

If you must support very old environments or a transpiler that doesn't correctly set prototypes, use the classic pattern:

```js
function LegacyError(message) {
  const err = new Error(message);
  Object.setPrototypeOf(err, LegacyError.prototype);
  err.name = 'LegacyError';
  return err;
}
Object.setPrototypeOf(LegacyError, Error);
LegacyError.prototype = Object.create(Error.prototype);
LegacyError.prototype.constructor = LegacyError;
```

Modern toolchains (Babel with `loose: false`, TypeScript `target: ES2015+`) handle `class extends Error` correctly, so prefer the class form unless you have a specific compatibility requirement.

## Custom exceptions in JavaScript

### The idea

JavaScript doesn’t have a separate “exception” type the way Java/C# do. An *exception* is just **any value thrown** with `throw`. In practice you almost always throw an instance of `Error` (or a subclass), because `Error` objects carry a stack trace, a `name`, and a `message`, which makes debugging possible.

Custom exceptions let you:

- Give errors **semantic names** (`ValidationError`, `NotFoundError`, …).
- Attach **domain data** (field name, HTTP status, DB query, retry flag).
- **Discriminate** errors in `catch` with `instanceof` instead of parsing strings.
- **Wrap** lower-level errors while preserving the original via `cause`.

### Basic syntax

```js
class ValidationError extends Error {
  constructor(message, field) {
    super(message);                 // sets this.message
    this.name = 'ValidationError';  // default would be 'Error'
    this.field = field;             // custom payload
  }
}

throw new ValidationError('email is required', 'email');
```

Key points:

- `extends Error` keeps the prototype chain so `instanceof Error` and `instanceof ValidationError` both work.
- You must call `super(...)` before using `this` in a derived constructor.
- Set `this.name` so logs/printing show the right type.

### Preserving stack traces (Node / V8)

In V8 (Node, Chrome), the constructor itself can pollute the stack. Use `Error.captureStackTrace`:

```js
class AppError extends Error {
  constructor(message) {
    super(message);
    this.name = this.constructor.name;
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}
```

This keeps the stack pointing at the throw site, not the error class internals.

### Wrapping with `cause` (ES2022)

```js
class DatabaseError extends Error {
  constructor(message, { cause, query } = {}) {
    super(message, { cause });   // standard Error.cause
    this.name = 'DatabaseError';
    this.query = query;
  }
}

try {
  await db.run('SELECT ...');
} catch (err) {
  throw new DatabaseError('query failed', { cause: err, query: 'SELECT ...' });
}
```

`cause` keeps the original error reachable: `dbErr.cause`.

### Throwing and discriminating

```js
function parseAge(input) {
  const n = Number(input);
  if (Number.isNaN(n)) throw new ValidationError('not a number', 'age');
  if (n < 0)         throw new ValidationError('must be >= 0', 'age');
  return n;
}

try {
  parseAge('abc');
} catch (e) {
  if (e instanceof ValidationError) {
    console.error(`Bad field ${e.field}: ${e.message}`);
  } else {
    throw e; // unknown error: rethrow, don't swallow
  }
}
```

Always rethrow what you don’t understand.

### Typical use cases

#### 1. Input / domain validation

```js
class InsufficientFundsError extends Error {
  constructor(balance, amount) {
    super(`Need ${amount}, have ${balance}`);
    this.name = 'InsufficientFundsError';
    this.balance = balance;
    this.amount = amount;
  }
}
```

#### 2. HTTP / API errors with status

```js
class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.name = 'HttpError';
    this.status = status;
  }
  get isClientError() { return this.status >= 400 && this.status < 500; }
}

// throw new HttpError(404, 'User not found')
```

#### 3. Retryable vs. non-retryable

```js
class TransientError extends Error {
  constructor(message, { retryAfterMs } = {}) {
    super(message);
    this.name = 'TransientError';
    this.retryable = true;
    this.retryAfterMs = retryAfterMs;
  }
}
```

Catchers can decide: `if (err.retryable) retry();`.

#### 4. Error codes (common in libraries)

```js
class AppError extends Error {
  constructor(code, message, details) {
    super(message);
    this.name = 'AppError';
    this.code = code;       // e.g. 'E_NOT_FOUND'
    this.details = details;
  }
}
```

Codes are stable across minification/renaming, unlike class names, which helps across bundle boundaries.

### Serialization (gotcha)

`Error` properties like `message`, `stack`, `name` are non-enumerable, so `JSON.stringify(err)` is often `{}`. Add `toJSON`:

```js
class ApiError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
  toJSON() {
    return {
      name: this.name,
      message: this.message,
      status: this.status,
      stack: this.stack,
    };
  }
}
```

### Async code

Custom errors work the same; just `throw` inside async functions or reject promises:

```js
async function loadUser(id) {
  const res = await fetch(`/users/${id}`);
  if (!res.ok) throw new HttpError(res.status, await res.text());
  return res.json();
}

try {
  await loadUser(42);
} catch (e) {
  if (e instanceof HttpError && e.status === 404) { /* ... */ }
  else throw e;
}
```

### Pitfalls & best practices

- **Don’t throw strings/objects.** `throw 'oops'` gives no stack trace and breaks `instanceof`.
- **Always rethrow unknown errors** in `catch` instead of swallowing.
- **Set `name`** (or use `this.constructor.name`) for useful logs.
- **Preserve cause** when wrapping so debugging chains survive.
- **Cross-realm `instanceof`** can fail (iframes, VM modules). For public APIs, also expose a stable `code`/`name` and check those as a fallback.
- **Transpilation**: very old Babel setups could break `extends Error` prototype chain; modern tooling is fine. If you must support legacy, verify `instanceof`.
- Consider **`AggregateError`** (ES2021) when reporting multiple failures at once: `throw new AggregateError(errors, 'batch failed')`.

### Minimal complete example

```js
class NotFoundError extends Error {
  constructor(resource, id) {
    super(`${resource} not found: ${id}`);
    this.name = 'NotFoundError';
    this.resource = resource;
    this.id = id;
    if (Error.captureStackTrace) Error.captureStackTrace(this, this.constructor);
  }
}

function getUser(id) {
  const user = users.get(id);
  if (!user) throw new NotFoundError('User', id);
  return user;
}

try {
  getUser(99);
} catch (e) {
  if (e instanceof NotFoundError) console.log(e.resource, e.id);
  else throw e;
}
```

That covers the idea (semantic, data-carrying errors), syntax (class + super + name + cause + captureStackTrace), and the common use cases (validation, HTTP, domain rules, retryability, wrapping, codes).

### Mistake: throwing a plain object instead of an `Error`

```js
function validateAge(age) {
  if (age < 0) {
    // ❌ Throwing a plain object
    throw { name: "ValidationError", message: "Age cannot be negative" };
  }
}

try {
  validateAge(-5);
} catch (err) {
  console.log("is Error?", err instanceof Error); // false
  console.log("stack:", err.stack);               // undefined
  console.log("name:", err.name);                // "ValidationError"
}
```

### Corrected version

```js
class ValidationError extends Error {
  constructor(message) {
    super(message);                 // initialize Error (message, stack, etc.)
    this.name = "ValidationError";  // so console shows the custom name
  }
}

function validateAge(age) {
  if (age < 0) {
    throw new ValidationError("Age cannot be negative");
  }
}

try {
  validateAge(-5);
} catch (err) {
  console.log("is Error?", err instanceof Error); // true
  console.log("stack:", err.stack);               // real stack trace
  console.log("name:", err.name);                // "ValidationError"
}
```

### What was wrong and why

1. **No stack trace**  
   A plain object has no `stack` property. When something fails, you lose the call site, making debugging much harder.

2. **Not an `Error` instance**  
   `err instanceof Error` is `false`, so generic error handlers, logging frameworks, and `instanceof`-based catch blocks won’t recognize it as an error.

3. **Inconsistent behavior across tools**  
   Some engines/VMs and debugging tools expect real `Error` objects for proper formatting, source mapping, and async stack traces.

4. **Missing prototype chain**  
   Even if you add `name`/`message` manually, the object doesn’t inherit `Error.prototype` methods like `toString()` formatting consistently.

### Key best practices for custom exceptions

- Always `extend Error`.
- Always call `super(message)` first in the constructor.
- Set `this.name` to the class name (otherwise it prints as `Error`).
- Use `throw new MyError(...)` — classes cannot be invoked without `new`.
- (Optional, Node.js) Hide the constructor frame from the stack:
  ```js
  Error.captureStackTrace(this, this.constructor);
  ```
- For cross-realm checks (iframes/workers), prefer checking `err.name` or a custom `code` property instead of `instanceof`, since `instanceof` can fail across different global objects.

# Common pitfalls with custom exceptions in JavaScript

JavaScript “exceptions” are just thrown values; the ecosystem convention is to throw `Error` (or subclasses). Most pitfalls come from breaking the `Error` contract, losing stack traces, or mishandling asynchronous code.

---

## 1. Forgetting to call `super()` in a subclass

In a derived class, `this` is not available until `super()` runs.

**Bad**

```js
class BadError extends Error {
  constructor(message) {
    this.message = message; // ReferenceError: Must call super constructor
  }
}
```

**Good**

```js
class GoodError extends Error {
  constructor(message) {
    super(message);
    this.name = "GoodError";
  }
}
```

---

## 2. Relying on `constructor.name` for `error.name`

Minifiers/bundlers can rename classes, and `Error` itself sets `name` to `"Error"`.

**Bad**

```js
class NotFoundError extends Error {}

const err = new NotFoundError("missing");
console.log(err.name); // Often "Error", not "NotFoundError"
console.log(String(err)); // "Error: missing"
```

**Good**

```js
class NotFoundError extends Error {
  constructor(message) {
    super(message);
    this.name = "NotFoundError"; // explicit, stable string
  }
}
```

---

## 3. Creating the error far from where it is thrown

`Error` captures its stack at construction time, not at `throw` time.

**Bad**

```js
const err = new Error("something failed");

function run() {
  throw err; // stack points to where `err` was created, not to `run()`
}
```

**Good**

```js
function run() {
  throw new Error("something failed"); // stack points near the throw site
}
```

If you must create early, recapture the stack where throwing:

```js
if (Error.captureStackTrace) {
  Error.captureStackTrace(err, run);
}
throw err;
```

---

## 4. Breaking the prototype chain in ES5-style constructors

If you use function constructors, `instanceof Error` can silently fail.

**Bad**

```js
function LegacyError(message) {
  Error.call(this, message);
  this.message = message;
}

const e = new LegacyError("boom");
console.log(e instanceof Error); // false in many cases
console.log(e instanceof LegacyError); // true, but Error contract is broken
```

**Good**

```js
function LegacyError(message) {
  if (!(this instanceof LegacyError)) {
    return new LegacyError(message);
  }

  Error.call(this, message);
  this.message = message;
  this.name = "LegacyError";

  if (Error.captureStackTrace) {
    Error.captureStackTrace(this, this.constructor);
  }
}

LegacyError.prototype = Object.create(Error.prototype);
LegacyError.prototype.constructor = LegacyError;
```

Modern code should usually just use `class`.

---

## 5. Throwing non-`Error` values

Throwing strings, numbers, or plain objects loses stack traces and breaks tooling.

**Bad**

```js
throw "database unavailable";
throw { code: "NOT_FOUND", message: "user missing" };
```

**Good**

```js
class DatabaseError extends Error {
  constructor(message, code) {
    super(message);
    this.name = "DatabaseError";
    this.code = code;
  }
}

throw new DatabaseError("database unavailable", "DB_DOWN");
```

---

## 6. Using exceptions for ordinary control flow

Exceptions are expensive and obscure normal branches.

**Bad**

```js
function parseAge(input) {
  const n = Number(input);
  if (!Number.isInteger(n) || n < 0) {
    throw new Error("invalid age");
  }
  return n;
}

try {
  const age = parseAge(userInput); // expected invalid input becomes exceptional
} catch {
  // ...
}
```

**Good**

```js
function parseAge(input) {
  const n = Number(input);
  if (!Number.isInteger(n) || n < 0) return null;
  return n;
}

const age = parseAge(userInput);
if (age === null) {
  // handle expected invalid input normally
}
```

---

## 7. Swallowing errors in `catch`

Empty or “log only” catch blocks hide failures and make debugging impossible.

**Bad**

```js
try {
  saveUser(user);
} catch (err) {
  // silently ignored
}
```

**Good**

```js
try {
  saveUser(user);
} catch (err) {
  console.error("saveUser failed:", err);
  throw err; // or translate into a domain-specific error
}
```

---

## 8. Wrapping errors without preserving the original cause

Stringifying the original error loses its stack and type.

**Bad**

```js
try {
  await fetchUser(id);
} catch (err) {
  throw new Error(`Could not load user ${id}: ${err.message}`);
}
```

**Good**

```js
class UserLoadError extends Error {
  constructor(id, cause) {
    super(`Could not load user ${id}`);
    this.name = "UserLoadError";
    this.userId = id;
    this.cause = cause;
  }
}

try {
  await fetchUser(id);
} catch (err) {
  throw new UserLoadError(id, err);
}
```

Modern JavaScript also supports the standard option:

```js
throw new Error("Could not load user", { cause: err });
```

---

## 9. Assuming `try/catch` catches asynchronous throws

A `try/catch` around an async call does not catch a throw inside a callback or an un-awaited promise.

**Bad**

```js
try {
  setTimeout(() => {
    throw new Error("boom"); // not caught here
  }, 0);
} catch (err) {
  console.error("caught:", err); // never runs
}
```

**Good**

```js
// Wrap callback-style APIs in promises, or use async/await
function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function run() {
  await delay(0);
  throw new Error("boom"); // now propagates as a rejected promise
}

run().catch((err) => console.error("caught:", err));
```

---

## 10. Not awaiting async functions, causing unhandled rejections

Calling an async function without `await` or `.catch()` can produce an unhandled promise rejection.

**Bad**

```js
async function risky() {
  throw new Error("failed");
}

risky(); // unhandled rejection
```

**Good**

```js
async function main() {
  try {
    await risky();
  } catch (err) {
    console.error(err);
  }
}

main();
```

In Node.js, also handle process-level failures deliberately:

```js
process.on("unhandledRejection", (reason) => {
  console.error("Unhandled rejection:", reason);
  process.exit(1);
});
```

---

## 11. Returning from `finally` and swallowing exceptions

A `return` in `finally` overrides both normal returns and thrown errors.

**Bad**

```js
function readConfig() {
  try {
    throw new Error("config missing");
  } finally {
    return "default"; // exception is swallowed
  }
}
```

**Good**

```js
function readConfig() {
  try {
    throw new Error("config missing");
  } catch (err) {
    console.error(err);
    return "default";
  }
}
```

Use `finally` only for cleanup, not for returning values.

---

## 12. Passing non-string messages

`Error` coerces the message to a string, so objects become `"[object Object]"`.

**Bad**

```js
const details = { id: 42, reason: "timeout" };
throw new Error(details); // message becomes "[object Object]"
```

**Good**

```js
class TimeoutError extends Error {
  constructor(details) {
    super(typeof details === "string" ? details : JSON.stringify(details));
    this.name = "TimeoutError";
    this.details = details;
  }
}

throw new TimeoutError({ id: 42, reason: "timeout" });
```

---

## 13. Expecting `JSON.stringify(error)` to include standard fields

`message`, `stack`, and `name` are typically non-enumerable, so they disappear.

**Bad**

```js
const err = new Error("boom");
err.code = "E_BOOM";

console.log(JSON.stringify(err)); // '{"code":"E_BOOM"}' only
```

**Good**

```js
class AppError extends Error {
  constructor(message, code) {
    super(message);
    this.name = "AppError";
    this.code = code;
  }

  toJSON() {
    return {
      name: this.name,
      message: this.message,
      stack: this.stack,
      code: this.code,
      cause: this.cause instanceof Error
        ? this.cause.toJSON?.() ?? { message: this.cause.message }
        : this.cause,
    };
  }
}
```

Also avoid circular `cause` chains when serializing.

---

## 14. Using `instanceof Error` across realms or iframes

Errors created in another realm (iframe, VM, worker message) are instances of that realm’s `Error`, not yours.

**Bad**

```js
if (err instanceof Error) {
  // may be false for an error from another realm
}
```

**Good**

```js
function isErrorLike(value) {
  return (
    value !== null &&
    typeof value === "object" &&
    typeof value.message === "string" &&
    (typeof value.stack === "string" || value.stack === undefined)
  );
}

if (isErrorLike(err)) {
  // handle defensively
}
```

When sending errors across boundaries, send a plain DTO instead of the `Error` object:

```js
postMessage({
  name: err.name,
  message: err.message,
  stack: err.stack,
  code: err.code,
});
```

---

## 15. Catching too broadly or checking `error.name` as a string

String checks are fragile; use `instanceof` with the most specific type first.

**Bad**

```js
try {
  await doWork();
} catch (e) {
  if (e.name === "NotFoundError") {
    // brittle and misses subclasses/custom names
  } else {
    throw e;
  }
}
```

**Good**

```js
try {
  await doWork();
} catch (e) {
  if (e instanceof NotFoundError) {
    return null;
  }
  if (e instanceof ValidationError) {
    return { ok: false, errors: e.fields };
  }
  throw e;
}
```

---

## 16. Logging only the message and losing the stack

Template strings call `toString()`, which omits the stack.

**Bad**

```js
console.log(`Request failed: ${err}`); // "Error: Request failed"
```

**Good**

```js
console.error("Request failed:", err); // preserves stack in most consoles
// or explicitly:
console.error(err.stack ?? err);
```

---

## 17. Assuming `Error.captureStackTrace` is standard

`Error.captureStackTrace` is V8-specific (Node.js/Chrome). It is useful but not portable.

**Good defensive pattern**

```js
class ValidationError extends Error {
  constructor(message, field) {
    super(message);
    this.name = "ValidationError";
    this.field = field;

    if (typeof Error.captureStackTrace === "function") {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}
```

Avoid relying on parsed stack formats; they differ between V8, SpiderMonkey, and JavaScriptCore.

---

## Practical baseline template

A solid custom error base class:

```js
class AppError extends Error {
  constructor(message, options = {}) {
    super(message, { cause: options.cause });
    this.name = new.target.name || "AppError";
    this.code = options.code;

    if (typeof Error.captureStackTrace === "function") {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  toJSON() {
    return {
      name: this.name,
      message: this.message,
      stack: this.stack,
      code: this.code,
      cause: this.cause instanceof Error
        ? this.cause.toJSON?.() ?? this.cause.message
        : this.cause,
    };
  }
}

class NotFoundError extends AppError {
  constructor(resource, options) {
    super(`${resource} not found`, options);
    this.code = options?.code ?? "NOT_FOUND";
  }
}
```

This avoids most of the common pitfalls: explicit names, preserved cause, stack capture, serializable output, and clear subclassing.

## Exercise

**Task:** Create a small `validateUser(input)` function that throws **custom exception classes** for distinct business-rule failures, then write a caller that catches them separately and recovers (or rethrows) appropriately.

Requirements:
- Define at least 3 custom error classes extending `Error`: `ValidationError`, `EmailError`, `AgeError`.
- Each error should carry a `code` (e.g. `"INVALID_EMAIL"`) and preserve `name` + stack trace.
- `validateUser` accepts `{ name, email, age }` and throws the right custom error.
- The caller must distinguish errors via `instanceof` (not string matching).
- Bonus: add a `toJSON()` so errors serialize cleanly.

---

## Step-by-Step Solution

### Step 1 — Define the base custom error

Every custom error should extend `Error`, set `name`, and (optionally) fix the prototype chain for older engines/`instanceof` after transpilation.

```js
class AppError extends Error {
  constructor(message, code) {
    super(message);
    this.name = this.constructor.name;   // "AppError", "EmailError", etc.
    this.code = code ?? "UNKNOWN";
    // Maintains proper stack trace in V8 (Node/Chrome)
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  toJSON() {
    return {
      name: this.name,
      message: this.message,
      code: this.code,
      stack: this.stack,
    };
  }
}
```

### Step 2 — Define specific errors

Subclass the base so `instanceof` hierarchies work (`EmailError instanceof ValidationError` etc.).

```js
class ValidationError extends AppError {
  constructor(message, code = "VALIDATION_FAILED") {
    super(message, code);
  }
}

class EmailError extends ValidationError {
  constructor(message = "Invalid email address", code = "INVALID_EMAIL") {
    super(message, code);
  }
}

class AgeError extends ValidationError {
  constructor(message = "Age must be between 0 and 150", code = "INVALID_AGE") {
    super(message, code);
  }
}
```

### Step 3 — Validation logic

```js
function validateUser(input) {
  if (!input || typeof input !== "object") {
    throw new ValidationError("Input must be an object", "INVALID_INPUT");
  }
  const { name, email, age } = input;

  if (typeof name !== "string" || name.trim().length < 2) {
    throw new ValidationError("Name must be at least 2 chars", "INVALID_NAME");
  }
  if (typeof email !== "string" || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw new EmailError(); // uses defaults
  }
  if (!Number.isInteger(age) || age < 0 || age > 150) {
    throw new AgeError();
  }
  return true;
}
```

### Step 4 — Caller with differentiated handling

```js
function registerUser(input) {
  try {
    validateUser(input);
    console.log("✅ Valid user:", input.name);
    return { ok: true };
  } catch (err) {
    if (err instanceof EmailError) {
      console.warn("📧 Fix email:", err.message, err.code);
      return { ok: false, retry: "email" };
    }
    if (err instanceof AgeError) {
      console.warn("🎂 Fix age:", err.message, err.code);
      return { ok: false, retry: "age" };
    }
    if (err instanceof ValidationError) {
      console.warn("⚠️ General validation:", err.message);
      return { ok: false, retry: "general" };
    }
    // Unknown error: rethrow
    throw err;
  }
}
```

### Step 5 — Demonstrate serialization & instanceof hierarchy

```js
const tests = [
  { name: "Al", email: "bad", age: 25 },          // EmailError
  { name: "Al", email: "a@b.com", age: -1 },     // AgeError
  { name: "A",  email: "a@b.com", age: 25 },    // ValidationError (name)
  { name: "Alice", email: "a@b.com", age: 30 },  // ok
];

for (const t of tests) {
  const r = registerUser(t);
  console.log(JSON.stringify(r));
}

// instanceof checks
try { validateUser({ name: "A", email: "x@y.com", age: 25 }); }
catch (e) {
  console.log(e instanceof EmailError);     // false
  console.log(e instanceof ValidationError); // true
  console.log(JSON.stringify(e.toJSON()));
}
```

