## Syntax examples in JavaScript contexts

### 1. SQL databases (Node.js, e.g. SQLite / Postgres)

```js
// better-sqlite3
const db = require('better-sqlite3')('app.db');

// single-column
db.exec('CREATE INDEX IF NOT EXISTS idx_users_email ON users(email)');

// composite (leftmost prefix: email first, then created_at)
db.exec('CREATE INDEX idx_orders_user_date ON orders(user_id, created_at)');

// unique
db.exec('CREATE UNIQUE INDEX idx_users_username ON users(username)');

// partial (only active users)
db.exec('CREATE INDEX idx_active_users ON users(email) WHERE active = 1');

// check the query plan
console.log(
  db.prepare('EXPLAIN QUERY PLAN SELECT * FROM users WHERE email = ?').all('a@b.com')
);
```

### 2. MongoDB (Node driver)

```js
const { MongoClient } = require('mongodb');
const client = new MongoClient(process.env.MONGO_URL);
await client.connect();

const users = client.db('app').collection('users');

// single ascending
await users.createIndex({ email: 1 }, { unique: true });

// composite
await users.createIndex({ lastName: 1, firstName: 1 });

// text index for full-text search
await users.createIndex({ bio: 'text' });

// inspect
console.log(await users.listIndexes().toArray());
```

### 3. IndexedDB (browser)

```js
const req = indexedDB.open('mydb', 1);

req.onupgradeneeded = (e) => {
  const db = e.target.result;
  const store = db.createObjectStore('users', { keyPath: 'id' });

  store.createIndex('by_email', 'email', { unique: true });
  store.createIndex('by_name', ['lastName', 'firstName']); // composite
};

req.onsuccess = (e) => {
  const db = e.target.result;
  const tx = db.transaction('users', 'readonly');
  const idx = tx.objectStore('users').index('by_email');

  const getReq = idx.get('a@b.com');
  getReq.onsuccess = () => console.log(getReq.result);
};
```

### 4. ORMs (Prisma / Sequelize)

**Prisma schema**
```prisma
model User {
  id        Int      @id @default(autoincrement())
  email     String   @unique
  lastName  String
  firstName String
  createdAt DateTime @default(now())

  @@index([lastName, firstName])
  @@index([createdAt])
}
```

**Sequelize**
```js
const User = sequelize.define('User', {
  email: { type: DataTypes.STRING, allowNull: false },
}, {
  indexes: [
    { unique: true, fields: ['email'] },
    { fields: ['lastName', 'firstName'] },
  ],
});
```

