## 3) Real thread deadlock with `worker_threads`

This demonstrates an actual OS‑level deadlock using `SharedArrayBuffer` + `Atomics`.

**`worker.js`**

```js
'use strict';

const { workerData, parentPort } = require('worker_threads');

const arr = new Int32Array(workerData.sab);
const [first, second] = workerData.order;

function acquire(idx) {
  // spin until we flip 0 -> 1
  while (Atomics.compareExchange(arr, idx, 0, 1) !== 0) {
    // wait while it stays locked (value === 1)
    Atomics.wait(arr, idx, 1, 2);
  }
}

function release(idx) {
  Atomics.store(arr, idx, 0);
  Atomics.notify(arr, idx, 1);
}

// Acquire in the worker's configured order
acquire(first);
const start = Date.now();
while (Date.now() - start < 40) {} // simulate work while holding first

acquire(second); // may block forever if opposite order deadlocks

// critical section (never reached in deadlock case)
release(second);
release(first);

parentPort.postMessage(`worker ${workerData.id} done`);
```

**`deadlock_threads.js`**

```js
'use strict';

const { Worker } = require('worker_threads');
const path = require('path');

const sab = new SharedArrayBuffer(2 * Int32Array.BYTES_PER_ELEMENT);
const arr = new Int32Array(sab);
arr[0] = 0;
arr[1] = 0;

const w1 = new Worker(path.join(__dirname, 'worker.js'), {
  workerData: { sab, order: [0, 1], id: 1 },
});
const w2 = new Worker(path.join(__dirname, 'worker.js'), {
  workerData: { sab, order: [1, 0], id: 2 }, // opposite order -> deadlock
});

let finished = 0;
for (const w of [w1, w2]) {
  w.on('message', (m) => {
    console.log(m);
    if (++finished === 2) {
      console.log('Both workers finished (no deadlock).');
      process.exit(0);
    }
  });
  w.on('error', (e) => console.error('worker error:', e));
}

setTimeout(() => {
  console.error('DEADLOCK DETECTED: terminating workers');
  w1.terminate();
  w2.terminate();
  process.exit(1);
}, 500);
```

Run:

```bash
node deadlock_threads.js
```

Notes:
* `Atomics.wait` is only allowed in Worker threads (not the main thread), which is why the blocking happens off the main thread.
* The main thread uses a timeout + `terminate()` to detect/recover from the deadlock.

