## Step-by-step solution

### 1. Why this happens in JavaScript

JavaScript is single-threaded, but `await` yields control to the event loop. Two async functions can therefore interleave between `await` points. That is enough to create race conditions. Deadlocks can also happen when async code waits on locks/resources in a cycle.

### 2. Reproducing the race condition

```js
const balances = { A: 100, B: 100 };
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function transferUnsafe(from, to, amount) {
  const fromBalance = balances[from];      // read
  await sleep(10);                         // yield
  if (fromBalance < amount) throw new Error('insufficient funds');
  balances[from] = fromBalance - amount;   // write based on stale read
  balances[to] += amount;                  // also unsafe
}

// 10 transfers of 10 from A to B
await Promise.all(Array.from({ length: 10 }, () => transferUnsafe('A', 'B', 10)));
console.log(balances);
// Expected: { A: 0, B: 200 }
// Often wrong: lost updates, negative-ish or inconsistent totals
```

### 3. Reproducing the deadlock

```js
class SimpleLock {
  constructor() { this.locked = false; this.queue = []; }
  async acquire() {
    return new Promise(resolve => {
      if (!this.locked) { this.locked = true; resolve(); }
      else this.queue.push(resolve);
    });
  }
  release() {
    if (this.queue.length) this.queue.shift()();
    else this.locked = false;
  }
}

const locks = { A: new SimpleLock(), B: new SimpleLock() };
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function transferDeadlock(from, to, amount) {
  await locks[from].acquire();
  await sleep(10);
  await locks[to].acquire();   // can deadlock with opposite transfer
  balances[from] -= amount;
  balances[to] += amount;
  locks[to].release();
  locks[from].release();
}

// These two can deadlock:
Promise.all([
  transferDeadlock('A', 'B', 10),
  transferDeadlock('B', 'A', 10),
]);
```

### 4. Fixing it

Key ideas:

- One mutex per account.
- Always acquire multiple locks in a **consistent global order**, e.g. sort account IDs.
- Use `try/finally` so locks are released even if an error is thrown.
- Make balance updates happen only while holding the relevant lock(s).

---

## Final solution

```js
// safe-bank.js
const sleep = ms => new Promise(r => setTimeout(r, ms));

class Mutex {
  constructor() {
    this.locked = false;
    this.waiters = [];
  }

  acquire() {
    return new Promise(resolve => {
      if (!this.locked) {
        this.locked = true;
        resolve();
      } else {
        this.waiters.push(resolve);
      }
    });
  }

  release() {
    if (this.waiters.length > 0) {
      const next = this.waiters.shift();
      next(); // lock remains held by next waiter
    } else {
      this.locked = false;
    }
  }
}

const balances = new Map([
  ['A', 100],
  ['B', 100],
]);

const locks = new Map();

function getLock(accountId) {
  if (!locks.has(accountId)) {
    locks.set(accountId, new Mutex());
  }
  return locks.get(accountId);
}

function getBalance(accountId) {
  return balances.get(accountId) ?? 0;
}

async function deposit(accountId, amount) {
  if (amount < 0) throw new Error('amount must be non-negative');
  const lock = getLock(accountId);
  await lock.acquire();
  try {
    await sleep(5); // simulate async DB/network work
    balances.set(accountId, getBalance(accountId) + amount);
  } finally {
    lock.release();
  }
}

async function withdraw(accountId, amount) {
  if (amount < 0) throw new Error('amount must be non-negative');
  const lock = getLock(accountId);
  await lock.acquire();
  try {
    await sleep(5);
    const current = getBalance(accountId);
    if (current < amount) throw new Error('insufficient funds');
    balances.set(accountId, current - amount);
  } finally {
    lock.release();
  }
}

async function transfer(from, to, amount) {
  if (amount < 0) throw new Error('amount must be non-negative');
  if (from === to) return;

  // Global lock ordering prevents deadlock.
  const ordered = [from, to].sort();
  const lock1 = getLock(ordered[0]);
  const lock2 = getLock(ordered[1]);

  await lock1.acquire();
  try {
    await lock2.acquire();
    try {
      await sleep(5);
      const fromBalance = getBalance(from);
      if (fromBalance < amount) throw new Error('insufficient funds');
      balances.set(from, fromBalance - amount);
      balances.set(to, getBalance(to) + amount);
    } finally {
      lock2.release();
    }
  } finally {
    lock1.release();
  }
}

function snapshot() {
  return Object.fromEntries(balances);
}

// Demonstration
async function main() {
  // Race-condition test: 10 concurrent transfers of 10 from A to B
  await Promise.all(
    Array.from({ length: 10 }, () => transfer('A', 'B', 10))
  );
  console.log('After 10 transfers A->B:', snapshot());
  // Expected: { A: 0, B: 200 }

  // Deadlock test: opposite transfers concurrently
  await Promise.all([
    transfer('A', 'B', 5),
    transfer('B', 'A', 5),
  ]);
  console.log('After opposite transfers:', snapshot());
  // Should complete without hanging

  await deposit('A', 50);
  await withdraw('B', 25);
  console.log('Final:', snapshot());
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});
```

### Why this fixes both issues

1. **Race condition fixed**: Balance reads and writes occur while the account mutex is held. Concurrent operations on the same account serialize through the mutex.
2. **Deadlock fixed**: Multiple locks are always acquired in sorted account-ID order. Two transfers in opposite directions therefore request locks in the same order, so no circular wait can occur.
3. **Exception safety**: `try/finally` guarantees every acquired lock is released, even if validation or simulated I/O throws.
4. **Consistency**: The total money remains conserved because each transfer updates both balances under the necessary locks.

### How to run

```bash
node safe-bank.js
```

You should see stable, expected balances and no hang during opposite transfers.

## Deadlocks & Race Conditions in JavaScript

### 1) Race condition
A race condition happens when the **final result depends on the timing/ordering** of asynchronous operations, especially when they share mutable state.

In JavaScript (single main thread + event loop), you don’t get preemption inside synchronous code, but races still happen across `await` boundaries:

```js
let x = 0;
async function bump() {
  const v = x;          // read
  await Promise.resolve(); // yield to event loop
  x = v + 1;            // write (stale value possible)
}
```

If two calls interleave at the `await`, both read `0` and both write `1`.

### 2) Deadlock
A deadlock is a cycle of waiting: **A waits for B, B waits for A** (or longer cycles). In JS this usually comes from:
- async locks/mutexes acquired in inconsistent order
- circular `await` (promise A waits on promise B which waits on A)
- Worker threads + `SharedArrayBuffer` + `Atomics.wait` used incorrectly

Pure synchronous single-threaded JS can’t deadlock in the OS sense; deadlocks appear once you introduce **async locks** or threads.

### 3) Fixes
- **Race**: use a mutex/atomic update; prefer immutable updates; keep critical sections small.
- **Deadlock**: global lock ordering, timeouts, `tryLock`, avoid nested locks, break cycles.

---

## Implementation (Node/browser compatible)

```js
// ---------- Utility ----------
const delay = (ms) => new Promise((r) => setTimeout(r, ms));

// ---------- Async Mutex ----------
/**
 * A simple FIFO mutex for async critical sections.
 * Usage:
 *   await mtx.lock();
 *   try { ... } finally { mtx.unlock(); }
 */
class Mutex {
  constructor() {
    this._locked = false;
    this._waiters = []; // queued resolve functions
  }

  lock() {
    if (!this._locked) {
      this._locked = true;
      return Promise.resolve();
    }
    return new Promise((resolve) => this._waiters.push(resolve));
  }

  unlock() {
    if (this._waiters.length > 0) {
      const next = this._waiters.shift();
      // hand off lock without flipping state (stays locked)
      next();
    } else {
      this._locked = false;
    }
  }

  /** Run fn while holding the lock; always releases. */
  async runExclusive(fn) {
    await this.lock();
    try {
      return await fn();
    } finally {
      this.unlock();
    }
  }
}

// ---------- Race condition demo ----------
async function demoRace() {
  let counter = 0;

  // UNSAFE: read-modify-write with a yield in between
  async function unsafeBump() {
    const v = counter;
    await delay(0); // simulate async work / I/O
    counter = v + 1;
  }

  const N = 50;
  await Promise.all(Array.from({ length: N }, unsafeBump));
  console.log("Unsafe counter (expected 50):", counter); // usually < 50

  // SAFE: serialize the critical section
  counter = 0;
  const mtx = new Mutex();
  async function safeBump() {
    await mtx.runExclusive(async () => {
      const v = counter;
      await delay(0);
      counter = v + 1;
    });
  }

  await Promise.all(Array.from({ length: N }, safeBump));
  console.log("Safe counter (expected 50):", counter); // 50
}

// ---------- Deadlock demo ----------
class DeadlockError extends Error {
  constructor(msg) { super(msg); this.name = "DeadlockError"; }
}

/**
 * Try to acquire a lock with a timeout to avoid hanging forever.
 */
async function withTimeout(promise, ms, label) {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new DeadlockError(`${label} timed out`)), ms);
  });
  try {
    return await Promise.race([promise, timeout]);
  } finally {
    clearTimeout(timer);
  }
}

async function demoDeadlock() {
  const a = new Mutex();
  const b = new Mutex();

  // DANGEROUS: opposite acquisition order
  async function task1() {
    await a.lock();
    try {
      await delay(10);
      // waits for b while holding a -> potential deadlock
      await withTimeout(b.lock(), 50, "task1 waiting for b");
      try {
        console.log("task1 got both locks");
      } finally {
        b.unlock();
      }
    } finally {
      a.unlock();
    }
  }

  async function task2() {
    await b.lock();
    try {
      await delay(10);
      await withTimeout(a.lock(), 50, "task2 waiting for a");
      try {
        console.log("task2 got both locks");
      } finally {
        a.unlock();
      }
    } finally {
      b.unlock();
    }
  }

  const results = await Promise.allSettled([task1(), task2()]);
  for (const r of results) {
    if (r.status === "rejected") console.log("Deadlock detected:", r.reason.message);
  }
}

// ---------- Safe pattern: ordered acquisition ----------
async function demoSafeOrdering() {
  const a = new Mutex();
  const b = new Mutex();

  // Always acquire in a fixed global order (a -> b)
  async function task() {
    await a.lock();
    try {
      await delay(10);
      await b.lock();
      try {
        console.log("safely acquired a then b");
      } finally {
        b.unlock();
      }
    } finally {
      a.unlock();
    }
  }

  await Promise.all([task(), task()]);
  console.log("No deadlock with ordered acquisition");
}

// ---------- Run ----------
(async () => {
  await demoRace();
  await demoDeadlock();
  await demoSafeOrdering();
})();
```

### Interview takeaways
- **Race ≠ threading only.** In JS, `await` is the interleaving point; any read-modify-write across an `await` can race.
- **Deadlock in JS is usually a lock-cycle**, not a thread cycle. Timeouts + consistent lock ordering are the standard defenses.
- Prefer **atomic/immutable state updates** and **message passing** (workers) over shared mutable locks when possible.

# Deadlocks & Race Conditions in JavaScript: Edge Cases

JavaScript is single-threaded per realm, so classic OS deadlocks don't occur in pure sync code. But the moment you introduce **async/await, Promises, Web Workers, `SharedArrayBuffer`/`Atomics`, event handlers, or shared mutable state**, both races and deadlocks become real. Below are the edge cases that bite hardest, with runnable examples.

---

## Part 1 — Race conditions

### 1. Lost update (read-modify-write without atomicity)

```js
let counter = 0;
const delay = (ms) => new Promise(r => setTimeout(r, ms));

async function increment() {
  const v = counter;          // read
  await delay(0);             // yield → another task can run
  counter = v + 1;            // write (stale base)
}

await Promise.all([increment(), increment(), increment()]);
console.log(counter); // often 1, expected 3
```

**Fix:** serialize with a mutex/queue, or use `Atomics.add` on a `SharedArrayBuffer`, or recompute from a single source of truth.

### 2. Stale closure captured in a loop

```js
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log('var:', i), 0);
}
// 3 3 3

for (let i = 0; i < 3; i++) {
  setTimeout(() => console.log('let:', i), 0);
}
// 0 1 2
```

Edge case: even with `let`, closures over **mutable outer variables** still capture the binding, not a snapshot. If you mutate after scheduling, you see the new value.

### 3. Check-then-act (TOCTOU)

```js
async function writeIfMissing(path, data) {
  if (!(await exists(path))) {   // check
    await delay(10);
    await writeFile(path, data);  // act — another caller may have created it
  }
}
```

Two concurrent callers both pass the check. Fix: atomic create (`O_EXCL`/`wx` flag), DB unique constraints, or idempotent upserts.

### 4. Out-of-order async responses

```js
let latest = 0;
async function search(q, seq) {
  const res = await fetch(`/api?q=${q}`);
  const data = await res.json();
  if (seq < latest) return;     // discard stale
  latest = seq;
  render(data);
}

let seq = 0;
input.oninput = (e) => search(e.target.value, ++seq);
```

Edge cases: network retries, cached responses, and `AbortController` signals that fire *after* the response already arrived. Always tag requests with a monotonic id and compare.

### 5. Floating / unawaited promises

```js
async function save() {
  doWork();          // floating promise — rejection becomes unhandled
  await other();
}
```

If `doWork()` rejects, you get an `unhandledrejection` event, possibly after the function returned. Fix: `void doWork().catch(log)` or `await`.

### 6. Event-handler reentrancy

```js
button.addEventListener('click', async () => {
  button.disabled = true;
  await submit();
  button.disabled = false;   // if submit throws, button stays disabled
});
```

Edge case: a second click can land between `await` points if you forget to guard. Use a reentrancy flag + `finally`.

### 7. Microtask starvation

```js
function spin() {
  Promise.resolve().then(spin); // never yields to macrotasks
}
spin();
setTimeout(() => console.log('never runs'), 0);
```

An infinite microtask chain blocks timers, I/O, and rendering. Always insert `setTimeout`/`setImmediate` to yield.

### 8. React/state batching staleness (UI race)

```jsx
const [n, setN] = useState(0);
function inc3() {
  setN(n + 1); // all three read stale n=0
  setN(n + 1);
  setN(n + 1);
}
```

Fix: functional update `setN(x => x + 1)`.

### 9. Async singleton initialization

```js
let instance;
async function getInstance() {
  if (!instance) instance = await create(); // two callers both create
  return instance;
}
```

Fix: store the **promise**, not the value:

```js
let p;
function getInstance() {
  if (!p) p = create();
  return p;
}
```

### 10. Cache stampede (thundering herd)

Many concurrent requests miss cache simultaneously and all hit the DB. Fix: single-flight (dedupe in-flight promises by key).

```js
const inflight = new Map();
function load(key) {
  if (inflight.has(key)) return inflight.get(key);
  const p = fetchFromDb(key).finally(() => inflight.delete(key));
  inflight.set(key, p);
  return p;
}
```

