## 1. Console API and structured output

The console is more than `log`. Use the right method for the job so DevTools/terminals can filter by level.

```js
// debug-demo.js
'use strict';

const assert = require('node:assert');
const { performance } = require('node:perf_hooks');
const util = require('node:util');

// ---------- 1. Console levels ----------
console.log('log: general info');
console.info('info: informational');
console.warn('warn: something suspicious');
console.error('error: something broke');
console.debug('debug: verbose detail (often hidden by default)');

// ---------- 2. console.table ----------
const users = [
  { id: 1, name: 'Ada',  role: 'admin',  active: true },
  { id: 2, name: 'Bob',  role: 'user',   active: false },
  { id: 3, name: 'Cara', role: 'editor', active: true },
];
console.table(users);
console.table(users, ['name', 'role']); // subset of columns

// ---------- 3. Grouping ----------
console.group('User processing');
console.log('validating...');
console.log('persisting...');
console.groupCollapsed('Raw payload (collapsed)');
console.dir(users[0], { depth: null, colors: true });
console.groupEnd();
console.groupEnd();

// ---------- 4. Counting ----------
function processUser(u) { console.count('processUser calls'); return u.name.toUpperCase(); }
users.forEach(processUser);
console.countReset('processUser calls');

// ---------- 5. Timing ----------
console.time('loop-1e6');
let s = 0;
for (let i = 0; i < 1_000_000; i++) s += i;
console.timeEnd('loop-1e6');
console.log('sum =', s);

// High-resolution timing independent of console
const t0 = performance.now();
for (let i = 0; i < 1_000_000; i++) s += i;
console.log('hrtime ms:', (performance.now() - t0).toFixed(3));
```

