## 2. Tracing, assertions, and stack capture

```js
// ---------- 6. console.trace ----------
function inner() { console.trace('trace from inner'); }
function outer() { inner(); }
outer();

// ---------- 7. assert (Node) ----------
function divide(a, b) {
  assert(typeof a === 'number' && typeof b === 'number', 'args must be numbers');
  assert(b !== 0, 'division by zero');
  return a / b;
}
try { divide(10, 0); } catch (e) { console.error('AssertionError:', e.message); }
try { divide('10', 2); } catch (e) { console.error('AssertionError:', e.message); }
console.log('divide(10,2) =', divide(10, 2));

// ---------- 8. Capturing a clean stack trace ----------
class DebugError extends Error {
  constructor(msg, context) {
    super(msg);
    this.context = context;
    // Hide constructor frames from the stack (V8)
    if (Error.captureStackTrace) Error.captureStackTrace(this, DebugError);
  }
}
function failWithContext() {
  throw new DebugError('operation failed', { userId: 42, step: 'persist' });
}
try { failWithContext(); } catch (e) {
  console.error(e.name, '-', e.message);
  console.error('context:', e.context);
  console.error('stack:\n' + e.stack);
}
```

