## 5. Async debugging

```js
// ---------- 12. Async stack traces ----------
async function a() { await b(); }
async function b() { await c(); }
async function c() {
  throw new Error('async boom');
}
a().catch(err => {
  console.error('Async error stack:\n' + err.stack);
});

// ---------- 13. Promise debugging helper ----------
function withTiming(label, fn) {
  return async (...args) => {
    const start = performance.now();
    try {
      const r = await fn(...args);
      console.log(`${label} OK in ${(performance.now()-start).toFixed(2)}ms`);
      return r;
    } catch (e) {
      console.error(`${label} FAILED in ${(performance.now()-start).toFixed(2)}ms:`, e.message);
      throw e;
    }
  };
}

const slowOp = withTiming('slowOp', async (ms) => {
  await new Promise(r => setTimeout(r, ms));
  if (ms > 50) throw new Error('too slow');
  return ms * 2;
});
slowOp(30).then(r => console.log('result', r)).catch(() => {});
slowOp(100).catch(() => {});
```

