## Example usage

```js
const defaults = {
  theme: "light",
  pagination: { pageSize: 20, showTotal: true },
  tags: ["default"],
};

const overrides = {
  theme: "dark",
  pagination: { pageSize: 50 },
  tags: ["custom"],
  __proto__: { polluted: true },
};

const config = mergeConfig(defaults, overrides);

console.log(config);
// {
//   theme: "dark",
//   pagination: { pageSize: 50, showTotal: true },
//   tags: ["custom"]
// }

console.log(defaults.pagination.pageSize); // 20 (unchanged)
console.log({}.polluted); // undefined (no prototype pollution)
