mergeConfig({ a: 1 }, null);          // { a: 1 }
mergeConfig("bad", {});               // throws TypeError
mergeConfig({}, []);                  // throws TypeError
mergeConfig({ a: { b: 1 } }, { a: { c: 2 } }); // { a: { b: 1, c: 2 } }
```

## Defensive Programming in JavaScript — Interview Answer

**What it is:** Defensive programming means writing code that assumes inputs may be wrong, dependencies may fail, and state may be unexpected — and handles those cases gracefully instead of crashing or corrupting data. In JS this matters a lot because the language is dynamically typed, coercion is implicit, and `null`/`undefined` are everywhere.

**Core principles I'd name in an interview:**
1. **Never trust input** — validate at boundaries (API edges, user input, env vars).
2. **Fail fast & fail clearly** — throw typed, descriptive errors early rather than propagating bad state.
3. **Guard clauses** — handle bad cases first, keep the happy path un-nested.
4. **Safe access** — optional chaining / nullish coalescing; never `a.b.c` on untrusted data.
5. **Contracts** — assertions for invariants that "should never" happen.
6. **Immutability** — don't mutate inputs you don't own; return new values.
7. **Bounded resources** — cap loops, string lengths, array sizes to avoid DoS.
8. **Don't swallow errors** — log + rethrow, or return a result type; never empty `catch`.

---

### Implementation: a small defensive toolkit + a real consumer

```js
// defensive.js
'use strict';

/**
 * Defensive programming toolkit.
 * Philosophy: validate at boundaries, fail fast with clear errors,
 * never mutate caller data, and make partial failure explicit.
 */

const Defensive = Object.create(null);

// ---------- Type guards ----------
// Note: typeof null === 'object', so always check null explicitly.
Defensive.isString  = (v) => typeof v === 'string';
Defensive.isNumber  = (v) => typeof v === 'number' && Number.isFinite(v);
Defensive.isInt     = (v) => Number.isInteger(v);
Defensive.isBool    = (v) => typeof v === 'boolean';
Defensive.isObject  = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
Defensive.isArray   = Array.isArray;
Defensive.isFn      = (v) => typeof v === 'function';

// ---------- Safe property access ----------
/**
 * Read a (possibly nested) path without throwing.
 * @param {any} obj
 * @param {string|string[]} path  e.g. "a.b.c" or ['a','b','c']
 * @param {any} fallback
 */
Defensive.get = (obj, path, fallback = undefined) => {
  if (obj == null) return fallback;
  const keys = Array.isArray(path) ? path : String(path).split('.');
  let cur = obj;
  for (const key of keys) {
    if (cur == null) return fallback;   // stop early on null/undefined
    cur = cur[key];
  }
  return cur === undefined ? fallback : cur;
};

// ---------- Assertions (invariants) ----------
Defensive.assert = (condition, message = 'Assertion failed') => {
  if (!condition) {
    const err = new Error(`AssertionError: ${message}`);
    // Keep stack useful in V8
    if (Error.captureStackTrace) Error.captureStackTrace(err, Defensive.assert);
    throw err;
  }
};

// ---------- Validation with multiple rules ----------
/**
 * Run all rules; collect ALL errors (don't stop at first) for better UX.
 * Each rule: (value) => string | null  (null/undefined = ok)
 */
Defensive.validate = (value, rules, label = 'value') => {
  if (!Array.isArray(rules)) throw new TypeError('rules must be an array');
  const errors = [];
  for (const rule of rules) {
    if (typeof rule !== 'function') throw new TypeError('each rule must be a function');
    const msg = rule(value);
    if (msg) errors.push(msg);
  }
  if (errors.length) {
    const err = new Error(`ValidationError on "${label}": ${errors.join('; ')}`);
    err.errors = errors;
    err.label = label;
    throw err;
  }
  return value; // validated value, safe to use downstream
};

// Reusable rule factories
Defensive.rules = {
  required: (v) => (v == null || v === '' ? 'is required' : null),
  string:   (v) => (typeof v !== 'string' ? 'must be a string' : null),
  number:   (v) => (typeof v !== 'number' || !Number.isFinite(v) ? 'must be a finite number' : null),
  minLen:   (n) => (v) => (typeof v === 'string' && v.length < n ? `min length ${n}` : null),
  maxLen:   (n) => (v) => (typeof v === 'string' && v.length > n ? `max length ${n}` : null),
  inRange:  (lo, hi) => (v) => (typeof v === 'number' && (v < lo || v > hi) ? `must be in [${lo},${hi}]` : null),
  oneOf:    (allowed) => (v) => (!allowed.includes(v) ? `must be one of ${allowed.join(', ')}` : null),
};

// ---------- Safe call (result type instead of throw) ----------
Defensive.tryCall = (fn, ...args) => {
  try {
    return { ok: true, value: fn(...args) };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err : new Error(String(err)) };
  }
};

// ---------- Sanitization (boundary cleanup) ----------
Defensive.sanitizeString = (v, maxLen = 256) => {
  if (typeof v !== 'string') return '';
  // trim + cap length to prevent huge payloads / log injection
  return v.trim().slice(0, Math.max(0, maxLen));
};

Defensive.sanitizeInt = (v, fallback = 0, { min = -Infinity, max = Infinity } = {}) => {
  const n = Number.parseInt(v, 10);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(max, Math.max(min, n));
};

// ---------- Safe array ops (never mutate input) ----------
Defensive.unique = (arr) => {
  if (!Array.isArray(arr)) return [];
  return [...new Set(arr)];
};

Defensive.chunk = (arr, size) => {
  if (!Array.isArray(arr)) return [];
  const n = Math.max(1, Math.floor(size) || 1);
  const out = [];
  for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n));
  return out;
};

// ---------- Deep clone (defensive copy) ----------
Defensive.clone = (v) => {
  // structuredClone is available in modern runtimes; fall back for safety
  if (typeof structuredClone === 'function') {
    try { return structuredClone(v); } catch (_) { /* fall through */ }
  }
  return JSON.parse(JSON.stringify(v)); // caveat: drops functions/symbols/undefined
};

module.exports = Defensive;
```

### A realistic consumer: processing an untrusted user payload

```js
// userService.js
const D = require('./defensive');

/**
 * Normalize + validate an incoming user object.
 * Returns a clean, trusted object or throws a ValidationError.
 * Never mutates the input.
 */
function normalizeUser(raw) {
  // 1. Boundary: reject non-objects immediately (fail fast).
  if (!D.isObject(raw)) {
    throw new TypeError('normalizeUser expects an object');
  }

  // 2. Defensive copy so we can't corrupt caller's data.
  const src = D.clone(raw);

  // 3. Safe reads with defaults.
  const name  = D.sanitizeString(D.get(src, 'name', ''), 60);
  const email = D.sanitizeString(D.get(src, 'email', ''), 254).toLowerCase();
  const age   = D.sanitizeInt(D.get(src, 'age', 0), 0, { min: 0, max: 130 });
  const role  = D.get(src, 'role', 'user');

  // 4. Validate (collect all errors).
  D.validate(name,  [D.rules.required, D.rules.string, D.rules.minLen(2)], 'name');
  D.validate(email, [D.rules.required, D.rules.string], 'email');
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    throw new Error('ValidationError on "email": invalid format');
  }
  D.validate(age,   [D.rules.number, D.rules.inRange(0, 130)], 'age');
  D.validate(role,  [D.rules.oneOf(['user', 'admin', 'guest'])], 'role');

  // 5. Invariant: after validation these must hold.
  D.assert(name.length >= 2, 'name too short after sanitize');
  D.assert(age >= 0 && age <= 130, 'age out of range');

  // 6. Return a FROZEN, minimal trusted shape (no extra fields leak).
  const clean = Object.freeze({
    name,
    email,
    age,
    role,
    createdAt: new Date().toISOString(),
  });

  return clean;
}

// ---------- Demo ----------
const cases = [
  { name: '  Alice  ', email: 'Alice@Example.com', age: '29', role: 'admin' },
  null,
  { name: 'B', email: 'bad', age: 999, role: 'superadmin' },
  { name: 'Carol', email: 'carol@x.com' }, // missing age/role -> defaults
];

for (const c of cases) {
  const r = D.tryCall(normalizeUser, c);
  if (r.ok) console.log('OK  ->', r.value);
  else       console.log('ERR ->', r.error.message);
}
```

