### Interview talking points / trade-offs

- **Where to defend:** boundaries (I/O, user input, env, external APIs). Don't sprinkle validation in every internal function — that's noise; use assertions there.
- **Throw vs result type:** throw for programmer errors / unrecoverable; result types (`{ok, value, error}`) for expected failures (parsing, network). Mixing both is fine if consistent per layer.
- **Cost:** defensive code adds branches and allocations. In hot loops, measure; in I/O paths, always defend.
- **Don't over-defend:** `if (x != null)` everywhere on trusted internal data is clutter. Trust your own invariants; verify at boundaries.
- **Immutability gotcha:** `Object.freeze` is shallow; for deep immutability use a library or recursive freeze. `structuredClone` is the modern safe copy.
- **JS specifics to mention:** `typeof null`, `NaN` is a number, array is object, implicit coercion (`'5' + 1`), prototype pollution (`__proto__`), ReDoS on untrusted regex.

### What I'd say to close
"Defensive programming in JS is mostly about *boundaries*: validate and sanitize what crosses the trust boundary, assert invariants internally, never mutate inputs, and make failure explicit and typed. The goal isn't zero crashes — it's that any crash is loud, located, and never corrupts data."

Below are the most important edge cases to handle when writing defensively in JavaScript, grouped by category, with runnable examples.

---

### 1. Falsy-value traps (`0`, `""`, `false`, `null`, `undefined`, `NaN`)

The classic bug: using `if (value)` to check existence.

```js
function formatCount(n) {
  // BUG: 0 is a valid count but is treated as "missing"
  if (!n) return "no items";
  return `${n} items`;
}

// Defensive
function formatCountSafe(n) {
  if (n == null) return "no items";   // only null/undefined
  if (Number.isNaN(n)) return "invalid";
  return `${n} items`;
}
```

---

### 2. `typeof null === "object"`

```js
function isObject(v) {
  // BUG
  return typeof v === "object";
}

// Defensive
function isObjectSafe(v) {
  return v !== null && typeof v === "object";
}
```

---

### 3. NaN propagation and comparisons

`NaN` never equals anything, including itself.

```js
const x = 0 / 0;
console.log(x === x);          // false
console.log(x == null);        // false

// Defensive helpers
const safe = Number.isFinite(x) ? x : 0;
const eq = (a, b) => Number.isNaN(a) && Number.isNaN(b) ? true : a === b;
```

---

### 4. Loose equality coercion

```js
// Surprising truths
console.log(0 == "");          // true
console.log(0 == false);       // true
console.log(null == undefined);// true
console.log("0" == false);     // true

// Defensive: always === / !==, except intentional null/undefined check
function isEmpty(v) {
  return v === null || v === undefined || v === "";
}
```

---

### 5. `+` operator type coercion

```js
console.log(1 + "2");   // "12"
console.log(1 + true);  // 2
console.log([] + {});   // "[object Object]"

// Defensive: coerce explicitly
function add(a, b) {
  const na = Number(a);
  const nb = Number(b);
  if (!Number.isFinite(na) || !Number.isFinite(nb)) {
    throw new TypeError("Arguments must be finite numbers");
  }
  return na + nb;
}
```

---

### 6. `parseInt` quirks

```js
console.log(parseInt("08"));        // 8 (modern) but historically 0
console.log(parseInt("10px"));      // 10  (stops early)
console.log(parseInt(""));          // NaN
console.log(parseInt("0x10"));      // 16

// Defensive
function parseStrictInt(s, radix = 10) {
  if (typeof s !== "string" || !/^[+-]?\d+$/.test(s.trim())) {
    return NaN;
  }
  const n = parseInt(s, radix);
  return Number.isSafeInteger(n) ? n : NaN;
}
```

---

### 7. Floating-point precision

```js
console.log(0.1 + 0.2 === 0.3); // false

// Defensive for money/decimals
function roundCents(n) {
  return Math.round(n * 100) / 100;
}
// or use integer cents / BigInt / decimal libraries
```

---

### 8. BigInt mixing and division by zero

```js
// 1n + 1;        // TypeError: Cannot mix BigInt and other types
// 5n / 0n;       // RangeError? actually throws RangeError: Division by zero

// Defensive
function safeBigIntDiv(a, b) {
  if (typeof a !== "bigint" || typeof b !== "bigint") {
    throw new TypeError("Expected bigint");
  }
  if (b === 0n) throw new RangeError("Division by zero");
  return a / b;
}
```

---

### 9. `null`/`undefined` property access

```js
const user = null;
// user.name; // TypeError

// Defensive: optional chaining + nullish coalescing
const name = user?.profile?.name ?? "Anonymous";

// Still guard function calls
const fn = obj?.method?.();
```

---

### 10. Destructuring defaults only trigger on `undefined`, not `null`

```js
const { x = 5 } = { x: null };
console.log(x); // null (default NOT applied)

// Defensive: explicit fallback
function pick(obj, key, fallback) {
  const v = obj?.[key];
  return v == null ? fallback : v;
}
```

---

### 11. Array bounds and sparse arrays

```js
const arr = [1, , 3];          // sparse
console.log(arr.length);        // 3
console.log(arr[1]);            // undefined (indistinguishable from real undefined)
console.log(arr.map(x => x*2)); // [2, empty, 6]

// Defensive
function at(arr, i) {
  if (!Array.isArray(arr)) return undefined;
  if (i < 0 || i >= arr.length) return undefined;
  return Object.prototype.hasOwnProperty.call(arr, i) ? arr[i] : undefined;
}
```

---

### 12. Mutating while iterating

```js
const items = [1, 2, 3, 4];
// BUG: removing elements shifts indices
for (let i = 0; i < items.length; i++) {
  if (items[i] % 2 === 0) items.splice(i, 1);
}
console.log(items); // [1, 3, 4]  (4 survived)

// Defensive: iterate backwards or filter
const evensRemoved = items.filter(n => n % 2 !== 0);
```

---

### 13. `for...in` on arrays / inherited keys

```js
Array.prototype.foo = "bar";
const a = [10, 20];
for (const k in a) console.log(k); // "0", "1", "foo"

// Defensive
for (const [i, v] of a.entries()) { /* ... */ }
// or Object.keys / hasOwnProperty
```

---

### 14. `hasOwnProperty` and prototype pollution

```js
const obj = Object.create(null); // no hasOwnProperty
// obj.hasOwnProperty("x"); // TypeError

// Defensive
function has(obj, key) {
  return Object.prototype.hasOwnProperty.call(obj, key);
}
```

---

### 15. JSON.parse failures and reviver pitfalls

```js
function safeParse(text) {
  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

// Also guard against __proto__ pollution in parsed objects
function safeParse2(text) {
  const o = JSON.parse(text);
  // strip dangerous keys recursively in real apps
  return o;
}
```

---

### 16. `fetch` only rejects on network errors, not HTTP errors

```js
async function getData(url) {
  const res = await fetch(url);
  // BUG: 404/500 still resolves
  return res.json();
}

// Defensive
async function getDataSafe(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const ct = res.headers.get("content-type") || "";
  if (!ct.includes("application/json")) throw new Error("Not JSON");
  return res.json();
}
```

---

### 17. Promise rejections and unhandled errors

```js
// Floating promise (no .catch) → unhandled rejection
fetch("/api").then(r => r.json());

// Defensive
async function run() {
  try {
    const r = await fetch("/api");
    if (!r.ok) throw new Error(r.status);
    return await r.json();
  } catch (err) {
    console.error("request failed", err);
    return null;
  }
}
```

---

### 18. `try/catch` does not catch async errors unless awaited

```js
async function bad() {
  try {
    setTimeout(() => { throw new Error("boom"); }, 0);
  } catch (e) {
    // never runs
  }
}
```

Defensive: use `await`, or attach handlers inside the timer.

---

### 19. Regular expression pitfalls

#### 19a. `lastIndex` statefulness with `g`/`y` flags
```js
const re = /a/g;
console.log(re.test("abc")); // true
console.log(re.test("abc")); // false (lastIndex moved)

// Defensive: reset or create fresh
function countMatches(s, re) {
  const r = new RegExp(re.source, re.flags.replace("g", "") + "g");
  // or r.lastIndex = 0 before each use
}
```

#### 19b. ReDoS
```js
// (a+)+ on long input → catastrophic backtracking
// Defensive: avoid nested quantifiers, set timeouts, use RE2-like libs
```

---

### 20. String indexing with surrogate pairs / emoji

```js
const s = " family 👨‍👩‍👧‍👦"; // ZWJ sequence
console.log(s.length);        // large
console.log(s[0]);            // wrong unit

// Defensive: use code-point aware ops
const chars = [...s];         // code points (still not grapheme clusters)
// for true grapheme clusters use Intl.Segmenter
const seg = new Intl.Segmenter("en", { granularity: "grapheme" });
const graphemes = [...seg.segment(s)].map(x => x.segment);
```

---

### 21. `parseInt` / `Number` locale and Infinity

```js
console.log(Number(""));     // 0
console.log(Number(null));   // 0
console.log(Number(true));   // 1
console.log(1 / 0);          // Infinity

// Defensive
function toFiniteNumber(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}
```

---

### 22. `Date` invalid and timezone pitfalls

```js
const d = new Date("not a date");
console.log(d.getTime()); // NaN

// Defensive
function safeTime(input) {
  const d = new Date(input);
  const t = d.getTime();
  return Number.isFinite(t) ? t : null;
}
```

---

### 23. `Map`/`Set` with object keys (reference equality)

```js
const m = new Map();
m.set({ id: 1 }, "a");
console.log(m.get({ id: 1 })); // undefined

// Defensive: use primitive keys or normalize
m.set(JSON.stringify({ id: 1 }), "a");
```

---

### 24. Modifying a collection during `for...of`

```js
const set = new Set([1, 2, 3]);
for (const v of set) {
  if (v === 2) set.delete(v); // OK in spec but can skip; safer to collect
}
```

Defensive: collect changes, apply after iteration.

---

### 25. `this` loss in callbacks

```js
class C {
  constructor() { this.x = 5; }
  run() {
    [1,2].forEach(function () { console.log(this.x); }); // undefined (strict)
  }
}

// Defensive: arrow or bind
class CSafe {
  constructor() { this.x = 5; }
  run() {
    [1,2].forEach(() => console.log(this.x));
  }
}
```

---

### 26. DOM queries returning `null`

```js
const btn = document.querySelector("#save");
// btn.addEventListener(...); // TypeError if missing

// Defensive
const btn2 = document.querySelector("#save");
btn2?.addEventListener("click", handler);
```

---

### 27. `localStorage` / `sessionStorage` availability and quota

```js
function safeSet(key, val) {
  try {
    localStorage.setItem(key, val);
    return true;
  } catch (e) {
    // Private mode, quota exceeded, disabled
    return false;
  }
}
```

---

### 28. Global / environment feature detection

```js
// Defensive feature checks
const hasStructuredClone = typeof structuredClone === "function";
const clone = hasStructuredClone ? structuredClone(obj) : JSON.parse(JSON.stringify(obj));

// Avoid navigator.userAgent sniffing; prefer capability checks
```

---

### 29. Closure over loop variables (legacy `var`)

```js
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0); // 3,3,3
}
// Defensive: use let/const
for (let j = 0; j < 3; j++) {
  setTimeout(() => console.log(j), 0); // 0,1,2
}
```

---

### 30. Shadowing built-ins / prototype pollution from input

```js
function merge(target, src) {
  for (const k in src) {
    // BUG: __proto__ pollution
    target[k] = src[k];
  }
}

// Defensive
function mergeSafe(target, src) {
  for (const k of Object.keys(src)) {
    if (k === "__proto__" || k === "constructor" || k === "prototype") continue;
    target[k] = src[k];
  }
}
```

---

### General defensive checklist

- Prefer `===` / `!==`.
- Use `Number.isFinite`, `Number.isSafeInteger`, `Number.isNaN`.
- Guard with `?.` and `??`, but remember `??` only falls back on `null`/`undefined`.
- Validate at system boundaries (user input, network, storage).
- Use TypeScript / JSDoc / runtime validators (zod, io-ts) for external data.
- Wrap risky I/O in `try/catch` and treat async errors explicitly.
- Test edge inputs: `null`, `undefined`, `0`, `""`, `NaN`, empty arrays/objects, very large/small numbers, emoji, untrusted JSON.

If you want, I can drill into any single category (e.g., a full input-validation module or async error-handling patterns) with production-ready code.

Below is a single, self-contained JavaScript file that demonstrates **eight classic design patterns** using modern ES6+ idioms. You can run it with `node patterns.js` (Node 18+) or paste it into a browser console.

```js
// patterns.js — Design Patterns in JavaScript (runnable demo)

/* =========================================================
   1. SINGLETON
   Ensures only one instance exists and provides global access.
   ========================================================= */
class Singleton {
  constructor() {
    if (Singleton.instance) return Singleton.instance;
    this.createdAt = new Date();
    Singleton.instance = this;
  }
  static getInstance() {
    return Singleton.instance || new Singleton();
  }
}

/* =========================================================
   2. FACTORY METHOD
   Centralizes object creation behind a common interface.
   ========================================================= */
class Button {
  render() { throw new Error("render() must be implemented"); }
}
class PrimaryButton extends Button { render() { return "[Primary Button]"; } }
class DangerButton  extends Button { render() { return "[Danger Button]"; } }

class ButtonFactory {
  create(type) {
    switch (type) {
      case "primary": return new PrimaryButton();
      case "danger":  return new DangerButton();
      default: throw new Error(`Unknown button type: ${type}`);
    }
  }
}

/* =========================================================
   3. BUILDER
   Constructs complex objects step by step.
   ========================================================= */
class HttpRequest {
  constructor() {
    this.method = "GET";
    this.url = "/";
    this.headers = {};
    this.body = null;
  }
}

class HttpRequestBuilder {
  constructor() { this.req = new HttpRequest(); }
  method(m)   { this.req.method = m; return this; }
  url(u)      { this.req.url = u; return this; }
  header(k,v){ this.req.headers[k] = v; return this; }
  body(b)     { this.req.body = b; return this; }
  build()     { return this.req; }
}

/* =========================================================
   4. OBSERVER (Pub/Sub)
   Lets subjects notify observers about state changes.
   ========================================================= */
class EventEmitter {
  constructor() { this.listeners = new Map(); }
  on(event, cb) {
    if (!this.listeners.has(event)) this.listeners.set(event, new Set());
    this.listeners.get(event).add(cb);
    return () => this.off(event, cb); // unsubscribe function
  }
  off(event, cb) { this.listeners.get(event)?.delete(cb); }
  emit(event, payload) {
    for (const cb of this.listeners.get(event) || []) cb(payload);
  }
}

/* =========================================================
   5. STRATEGY
   Encapsulates interchangeable algorithms.
   ========================================================= */
class PaymentContext {
  constructor(strategy) { this.strategy = strategy; }
  setStrategy(strategy) { this.strategy = strategy; }
  pay(amount) { return this.strategy.pay(amount); }
}

const paymentStrategies = {
  creditCard: { pay: (a) => `Paid ${a} via Credit Card` },
  paypal:     { pay: (a) => `Paid ${a} via PayPal` },
  crypto:     { pay: (a) => `Paid ${a} via Crypto` },
};

/* =========================================================
   6. DECORATOR (functional / higher-order)
   Adds behavior to functions/objects without subclassing.
   ========================================================= */
function withLogging(fn) {
  return function (...args) {
    console.log(`[LOG] calling ${fn.name} with`, args);
    const result = fn.apply(this, args);
    console.log(`[LOG] ${fn.name} returned`, result);
    return result;
  };
}

/* =========================================================
   7. COMMAND
   Encapsulates a request as an object (supports undo/redo).
   ========================================================= */
class CommandBus {
  constructor() { this.history = []; this.redoStack = []; }
  execute(cmd) {
    cmd.execute();
    this.history.push(cmd);
    this.redoStack = [];
  }
  undo() {
    const cmd = this.history.pop();
    if (cmd) { cmd.undo(); this.redoStack.push(cmd); }
  }
  redo() {
    const cmd = this.redoStack.pop();
    if (cmd) { cmd.execute(); this.history.push(cmd); }
  }
}

class AddTextCommand {
  constructor(target, text) { this.target = target; this.text = text; }
  execute() { this.target.value += this.text; }
  undo()    { this.target.value = this.target.value.slice(0, -this.text.length); }
}

/* =========================================================
   8. ADAPTER
   Makes incompatible interfaces work together.
   ========================================================= */
class LegacyPrinter {
  printOld(text) { return `LEGACY: ${text.toUpperCase()}`; }
}
class PrinterAdapter {
  constructor(legacy) { this.legacy = legacy; }
  print(text) { return this.legacy.printOld(text); } // new interface
}

/* =========================================================
   DEMO / RUNNABLE EXAMPLES
   ========================================================= */
function demo() {
  console.log("=== 1. Singleton ===");
  const a = Singleton.getInstance();
  const b = new Singleton();
  console.log("Same instance?", a === b);

  console.log("\n=== 2. Factory Method ===");
  const factory = new ButtonFactory();
  console.log(factory.create("primary").render());
  console.log(factory.create("danger").render());

  console.log("\n=== 3. Builder ===");
  const request = new HttpRequestBuilder()
    .method("POST")
    .url("/api/users")
    .header("Content-Type", "application/json")
    .body(JSON.stringify({ name: "Ada" }))
    .build();
  console.log(request);

  console.log("\n=== 4. Observer ===");
  const bus = new EventEmitter();
  const unsub = bus.on("data", (d) => console.log("received:", d));
  bus.emit("data", { id: 1 });
  unsub();
  bus.emit("data", { id: 2 }); // no output (unsubscribed)

  console.log("\n=== 5. Strategy ===");
  const ctx = new PaymentContext(paymentStrategies.creditCard);
  console.log(ctx.pay(42));
  ctx.setStrategy(paymentStrategies.crypto);
  console.log(ctx.pay(42));

  console.log("\n=== 6. Decorator ===");
  function add(x, y) { return x + y; }
  const loggedAdd = withLogging(add);
  loggedAdd(2, 3);

  console.log("\n=== 7. Command (undo/redo) ===");
  const field = { value: "" };
  const busCmd = new CommandBus();
  busCmd.execute(new AddTextCommand(field, "Hello"));
  busCmd.execute(new AddTextCommand(field, " World"));
  console.log("value:", JSON.stringify(field.value));
  busCmd.undo();
  console.log("after undo:", JSON.stringify(field.value));
  busCmd.redo();
  console.log("after redo:", JSON.stringify(field.value));

  console.log("\n=== 8. Adapter ===");
  const adapter = new PrinterAdapter(new LegacyPrinter());
  console.log(adapter.print("hello adapter"));
}

demo();
```

### How to run
```bash
node patterns.js
```

### Key takeaways
- **Singleton**: guard with a static `instance` field; return it from the constructor.
- **Factory Method**: hide `new` behind a method that maps a type string to a concrete class.
- **Builder**: fluent API (`return this`) keeps configuration readable for complex objects.
- **Observer**: store callbacks in a `Map<event, Set<cb>>`; return an unsubscribe function from `on`.
- **Strategy**: inject a small object with a common method (`pay`) instead of subclassing.
- **Decorator**: wrap functions with higher-order functions; for classes use composition or proxies.
- **Command**: store enough state to `execute`/`undo`; keep history stacks for redo.
- **Adapter**: translate a legacy interface to the one your app expects.

These patterns compose well: for example, an **Observer** can notify **Commands** that were built by a **Builder** and executed through a **CommandBus**, with **Logging Decorators** around side effects. If you want, I can extend this with **Facade**, **Proxy**, **State**, or **Dependency Injection** examples.

# Design Patterns in JavaScript

Design patterns are **reusable, proven solutions to recurring design problems**. They are *templates* (ideas + structure), not drop-in code. In JavaScript they are shaped by the language’s nature: first-class functions, closures, prototypal inheritance, dynamic typing, and (since ES modules) a native module system.

---

## 1. The idea

- **Problem → Pattern → Solution**: You recognize a recurring structural/behavioral problem and apply a known shape.
- **Decoupling**: Patterns usually separate *what* from *how* (interface vs. implementation).
- **Communication**: They give teams a shared vocabulary (“use an Observer here”).
- **Trade-off**: Patterns add indirection. Use them when the flexibility pays off, not by default.

### JavaScript specifics

| JS feature | Effect on patterns |
|---|---|
| First-class functions | Strategy, Command, Callback can be plain functions |
| Closures | Module, Singleton, private state without classes |
| Prototypes / classes | Inheritance-based patterns (Template Method, etc.) |
| Dynamic objects | Decorator/Adapter are easy via wrapping |
| ES modules | Native Module pattern; reduces need for IIFE modules |
| `Proxy` / `Reflect` | Meta-programming, virtual proxies, validation |

---

## 2. Creational patterns

### Singleton — one instance globally

**Use case:** shared config, logger, connection pool.

```js
class Logger {
  static #instance;
  static getInstance() {
    if (!this.#instance) this.#instance = new this();
    return this.#instance;
  }
  log(msg) { console.log(`[${new Date().toISOString()}] ${msg}`); }
}
```

### Factory — create objects without exposing constructors

**Use case:** parsing different payload types, UI components by kind.

```js
function createUser(type, data) {
  const base = { id: data.id, name: data.name };
  if (type === 'admin') return { ...base, role: 'admin', permissions: ['*'] };
  if (type === 'guest') return { ...base, role: 'guest', permissions: [] };
  return { ...base, role: 'user', permissions: ['read'] };
}
```

### Builder — step-by-step construction of complex objects

**Use case:** query builders, HTTP request builders, test fixtures.

```js
class RequestBuilder {
  constructor() { this.cfg = { method: 'GET', headers: {} }; }
  url(u) { this.cfg.url = u; return this; }
  method(m) { this.cfg.method = m; return this; }
  header(k, v) { this.cfg.headers[k] = v; return this; }
  build() { return { ...this.cfg }; }
}

const req = new RequestBuilder()
  .url('/api/users')
  .method('POST')
  .header('Content-Type', 'application/json')
  .build();
```

---

## 3. Structural patterns

### Module — encapsulate state and expose a public API

**Use case:** organizing code, hiding internals. Native ES modules are the modern form.

```js
// counter.js
let count = 0; // private to module
export function increment() { return ++count; }
export function get() { return count; }
```

Classic IIFE version (still useful for scripts):

```js
const Counter = (() => {
  let count = 0;
  return {
    increment: () => ++count,
    get: () => count,
  };
})();
```

### Decorator — add behavior without subclassing

**Use case:** logging, caching, auth checks, retry logic.

```js
function withRetry(fn, retries = 3) {
  return async (...args) => {
    let lastErr;
    for (let i = 0; i <= retries; i++) {
      try { return await fn(...args); }
      catch (e) { lastErr = e; }
    }
    throw lastErr;
  };
}

const fetchUser = withRetry(async (id) => fetch(`/users/${id}`).then(r => r.json()));
```

### Facade — simplify a complex subsystem

**Use case:** one friendly API over many low-level calls.

```js
const PaymentFacade = {
  async checkout(cart, card) {
    await Inventory.reserve(cart);
    const charge = await Gateway.charge(card, cart.total);
    await Orders.create(cart, charge.id);
    await Email.sendReceipt(charge.id);
    return charge.id;
  },
};
```

### Adapter — make incompatible interfaces work together

**Use case:** integrating third-party SDKs, legacy APIs.

```js
class LegacyPrinter {
  printText(text) { console.log('LEGACY:', text); }
}

class PrinterAdapter {
  constructor(legacy) { this.legacy = legacy; }
  print(msg) { this.legacy.printText(msg.toUpperCase()); } // new interface
}
```

---

## 4. Behavioral patterns

### Observer (Pub/Sub) — notify dependents of state changes

**Use case:** event systems, reactive UI, data binding.

```js
class EventEmitter {
  constructor() { this.listeners = new Map(); }
  on(event, cb) {
    if (!this.listeners.has(event)) this.listeners.set(event, []);
    this.listeners.get(event).push(cb);
  }
  emit(event, payload) {
    (this.listeners.get(event) || []).forEach(cb => cb(payload));
  }
  off(event, cb) {
    const arr = this.listeners.get(event);
    if (arr) this.listeners.set(event, arr.filter(f => f !== cb));
  }
}
```

### Strategy — swap algorithms at runtime

**Use case:** sorting, validation, pricing rules, auth methods.

```js
const strategies = {
  local: (u, p) => u === 'admin' && p === 'secret',
  oauth: async (token) => verifyJwt(token),
};

async function authenticate(strategy, ...args) {
  return strategies[strategy](...args);
}
```

### Command — encapsulate an action as an object (with undo)

**Use case:** editors, undo/redo, queued jobs, transactional operations.

```js
class Command {
  constructor({ do: doFn, undo: undoFn }) {
    this.do = doFn; this.undo = undoFn;
  }
}

class History {
  constructor() { this.stack = []; }
  run(cmd) { cmd.do(); this.stack.push(cmd); }
  undo() { this.stack.pop()?.undo(); }
}
```

### State — behavior changes with internal state

**Use case:** finite state machines, order lifecycle, media player.

```js
const states = {
  idle:   { play: () => 'playing' },
  playing:{ pause: () => 'paused', stop: () => 'idle' },
  paused: { play: () => 'playing', stop: () => 'idle' },
};

function transition(state, action) {
  const next = states[state]?.[action]?.();
  return next ?? state;
}
```

### Iterator — sequential access without exposing internals

**Use case:** custom collections, lazy sequences. JS has built-in iteration protocol.

```js
class Range {
  constructor(start, end) { this.start = start; this.end = end; }
  [Symbol.iterator]() {
    let i = this.start;
    const end = this.end;
    return {
      next() {
        return i <= end ? { value: i++, done: false } : { done: true };
      },
    };
  }
}
for (const n of new Range(1, 5)) console.log(n); // 1..5
```

---

## 5. Modern JavaScript context

Many classic patterns are now **built into the platform**:

- **Module** → ES modules (`import`/`export`)
- **Iterator** → `Symbol.iterator`, generators (`function*`)
- **Observer** → `EventTarget`, RxJS, framework reactivity
- **Singleton** → module-level instance (ES module caches one instance)
- **Facade** → service classes / API clients
- **Proxy pattern** → `Proxy` object for validation, logging, virtual objects

Example: module-level singleton is essentially free:

```js
// config.js
export const config = { apiUrl: '/api', debug: false };
// imported everywhere → same object
```

---

## 6. When to use (and when not to)

**Use patterns when:**
- You have repeated, similar problems across the codebase.
- You need to swap implementations (strategies, adapters).
- You’re building frameworks/libraries or complex domains (state machines, editors).
- You want testable seams (inject factories/strategies).

**Avoid / be careful when:**
- The problem is simple—plain functions/objects suffice.
- You’re adding layers “just in case” (YAGNI).
- Inheritance chains get deep—prefer composition.
- You obscure data flow (overuse of Observer/PubSub can make debugging hard).

### Practical guidelines

1. **Prefer composition over inheritance** — decorators, strategies, and adapters compose better.
2. **Keep patterns small** — a pattern should fit on a screen; if it’s huge, it’s probably over-engineered.
3. **Name by intent** — `withRetry`, `createUser`, `EventEmitter` read clearly.
4. **Leverage the language** — don’t reimplement modules/iterators if the platform already provides them.
5. **Test the seams** — patterns create boundaries; unit-test at those boundaries.

---

## Quick reference table

| Pattern | Core idea | Typical JS form |
|---|---|---|
| Singleton | One instance | static field / module export |
| Factory | Create by type | function returning objects |
| Builder | Fluent construction | chained methods returning `this` |
| Module | Encapsulate state | ES module / IIFE |
| Decorator | Wrap to add behavior | higher-order function |
| Facade | Simplify subsystem | single object with methods |
| Adapter | Convert interface | wrapper class/function |
| Observer | Notify on change | EventEmitter / callbacks |
| Strategy | Swap algorithm | object of functions |
| Command | Action as object | `{ do, undo }` |
| State | State-driven behavior | state map + transition fn |
| Iterator | Sequential access | `Symbol.iterator` / generator |

---

If you want, I can go deeper into a specific pattern (e.g., Observer with RxJS, or implementing a state machine with XState), or show how these patterns appear in a real framework like React/Node.

## Typical mistake: a “Singleton” that can still be bypassed

### Mistaken snippet

```js
let instance = null;

class Config {
  constructor() {
    this.settings = {};
    instance = this; // always overwrites the global reference
  }

  static getInstance() {
    if (!instance) {
      instance = new Config();
    }
    return instance;
  }
}

const a = Config.getInstance();
const b = new Config(); // bypasses the intended singleton access point

console.log(a === b); // false
console.log(instance === b); // true, but `a` is now stale
```

**What’s wrong**

- The constructor does not protect against direct instantiation with `new Config()`.
- The module-level `instance` variable is overwritten on every construction, so earlier references can become stale.
- The pattern is only “singleton-ish” by convention, not by enforcement.

---

### Corrected version

```js
class Config {
  constructor() {
    if (Config.instance) {
      return Config.instance; // enforce singleton even with `new`
    }

    this.settings = {};
    Config.instance = this;
  }

  static getInstance() {
    if (!Config.instance) {
      new Config(); // constructor stores the instance
    }
    return Config.instance;
  }

  static resetForTests() {
    Config.instance = null;
  }
}

const a = Config.getInstance();
const b = new Config();
const c = Config.getInstance();

console.log(a === b); // true
console.log(a === c); // true
```

**Why this is better**

- The constructor itself guards against multiple instances, so both `new Config()` and `Config.getInstance()` return the same object.
- State is stored on the class (`Config.instance`) rather than a loose module variable, making ownership clear.
- `resetForTests()` is a small, explicit escape hatch for testing, avoiding hidden global state problems.
- The pattern is enforced structurally, not just by developer discipline.

### Practical note

Singletons are useful for truly global, stateless-ish services (configuration, logging, connection pools), but overusing them creates hidden dependencies and makes unit testing harder. If a class needs different behavior in tests or multiple environments, prefer dependency injection over a hard-coded singleton.

Below are the most common pitfalls, each with a short explanation and runnable code showing the bad and fixed versions.

## 1) Singleton as hidden global state
Singletons are easy to misuse as mutable globals, which makes code hard to test and reason about.

**Bad**
```js
// config.js
const Config = {
  apiUrl: 'https://api.example.com',
  debug: false,
};
export default Config;

// somewhere else
Config.debug = true; // silent global mutation
```

**Better**
```js
// Create an instance per context / inject it
export function createConfig(overrides = {}) {
  return Object.freeze({
    apiUrl: 'https://api.example.com',
    debug: false,
    ...overrides,
  });
}

// tests can create isolated configs
const testConfig = createConfig({ debug: true });
```

## 2) Observer / event-emitter memory leaks
Forgetting to unsubscribe keeps closures (and DOM nodes) alive.

**Bad**
```js
class Component {
  constructor(bus) {
    this.bus = bus;
    this.handler = (e) => this.render(e);
    this.bus.on('update', this.handler);
  }
  destroy() {
    // forgot to remove listener -> leak
  }
}
```

**Better**
```js
class Component {
  constructor(bus) {
    this.bus = bus;
    this.ac = new AbortController();
    this.bus.on('update', (e) => this.render(e), { signal: this.ac.signal });
  }
  destroy() {
    this.ac.abort(); // all listeners registered with this signal are removed
  }
}
```
(Use `AbortSignal` where supported; otherwise keep references and call `off`.)

## 3) Losing `this` in pattern methods
Command/Strategy objects often pass methods as callbacks, losing `this`.

**Bad**
```js
class Command {
  constructor(value) { this.value = value; }
  execute() { console.log('exec', this.value); }
}

const cmd = new Command(42);
setTimeout(cmd.execute, 0); // this is undefined (strict) -> crash
```

**Better**
```js
class Command {
  constructor(value) { this.value = value; }
  execute = () => { console.log('exec', this.value); }; // arrow keeps lexical this
}
// or: setTimeout(() => cmd.execute(), 0)
```

## 4) Mutating shared prototypes
Changing a prototype affects all instances, including ones created earlier, causing spooky action at a distance.

**Bad**
```js
function Animal() {}
const a = new Animal();
Animal.prototype.speak = () => 'generic';
const b = new Animal();
// later
Animal.prototype.speak = () => 'changed';
a.speak(); // 'changed' — surprising for 'a'
```

**Better**
```js
class Animal {
  speak() { return 'generic'; }
}
// Override per instance if needed
const a = new Animal();
a.speak = () => 'a-specific';
```

## 5) Mixins: property collisions and diamond problems
`Object.assign` silently overwrites colliding members.

**Bad**
```js
const canFly = { fly() { return 'fly'; } };
const canSwim = { swim() { return 'swim'; }, fly() { return 'swim-fly'; } };

function Duck() {}
Object.assign(Duck.prototype, canFly, canSwim);
new Duck().fly(); // 'swim-fly' (silent override)
```

**Better**
```js
class Duck {
  fly() { return canFly.fly.call(this); }
  swim() { return canSwim.swim.call(this); }
}
// or use composition instead of mixins
```

## 6) Proxy traps causing infinite recursion
Accessing the proxy inside its own trap re-triggers the trap.

**Bad**
```js
const obj = { x: 1 };
const p = new Proxy(obj, {
  get(target, prop) {
    console.log('get', prop);
    return p[prop]; // recursion -> stack overflow
  },
});
```

**Better**
```js
const p = new Proxy(obj, {
  get(target, prop) {
    console.log('get', prop);
    return target[prop]; // operate on target, not proxy
  },
});
```

## 7) Factory functions that break `instanceof`
Returning a plain object from a constructor makes `instanceof` lie.

**Bad**
```js
function User(name) {
  return { name }; // not a User instance
}
const u = new User('Ada');
console.log(u instanceof User); // false
```

**Better**
```js
function User(name) {
  this.name = name;
}
// or factory without `new`, documented clearly:
export const createUser = (name) => ({ name, greet() { return `hi ${name}`; } });
```

## 8) Assuming synchronous in Repository/DAO patterns
Hiding async behind a sync-looking API leads to unhandled rejections or stale data.

**Bad**
```js
class UserRepository {
  findById(id) {
    return db.query('SELECT ...', [id]); // returns Promise, caller treats as value
  }
}
const user = repo.findById(1);
console.log(user.name); // undefined / Promise
```

**Better**
```js
class UserRepository {
  async findById(id) {
    const rows = await db.query('SELECT ...', [id]);
    return rows[0] ?? null;
  }
}
const user = await repo.findById(1);
```

## 9) Decorator patterns that mutate instead of wrap
If you mutate the original function/object, references held elsewhere bypass the decoration.

**Bad**
```js
function logged(fn) {
  const orig = fn;
  fn = (...args) => {
    console.log('call', args);
    return orig(...args);
  };
  return fn; // but original references elsewhere still point at unlogged fn
}
```

**Better**
```js
function logged(fn) {
  return function (...args) {
    console.log('call', args);
    return fn.apply(this, args);
  };
}
const f = logged(original);
// always use `f`, never `original` directly
```

## 10) Chain of Responsibility with async handlers
Returning without awaiting breaks the chain and swallows rejections.

**Bad**
```js
class Handler {
  setNext(h) { this.next = h; return h; }
  handle(req) {
    if (this.canHandle(req)) return this.process(req);
    if (this.next) return this.next.handle(req); // if process/next are async, mixed
  }
}
```

**Better**
```js
class Handler {
  setNext(h) { this.next = h; return h; }
  async handle(req) {
    if (this.canHandle(req)) return this.process(req);
    if (this.next) return this.next.handle(req);
    throw new Error('Unhandled request');
  }
}
```

## 11) Module pattern hiding state that tests need to reset
Closures are great for privacy but make parallel/isolated tests painful.

**Bad**
```js
const CounterModule = (function () {
  let count = 0;
  return {
    inc: () => ++count,
    get: () => count,
  };
})();
```

**Better**
```js
export function createCounter(initial = 0) {
  let count = initial;
  return {
    inc: () => ++count,
    get: () => count,
    reset: (v = initial) => { count = v; },
  };
}
```

## 12) Over-applying patterns ("pattern fever")
Adding Strategy/Factory/Observer where a function would do creates indirection with no payoff.

**Bad**
```js
// Strategy for a single, never-changing algorithm
class AddStrategy { execute(a,b){ return a+b; } }
class Calculator { constructor(s){ this.s=s; } calc(a,b){ return this.s.execute(a,b);} }
```

**Better**
```js
const add = (a, b) => a + b;
// Introduce a pattern only when you have a second variant or a real seam
```

### Quick checklist
- Prefer composition over inheritance/mixins.
- Keep state explicit and injectable.
- Always clean up observers/subscriptions.
- Make async boundaries explicit (`async`/`await`).
- Preserve `this` or avoid `this` entirely.
- Don't wrap a pattern around a single call path.

If you want, I can expand any one of these into a larger, production-grade example.

## Exercise

Build a small **Task Manager** with these requirements:

1. A `Task` has `id`, `title`, and `status`.
2. When a task’s status changes, every subscribed observer is notified.
3. Notification delivery must be swappable at runtime: console, email, and webhook.
4. Task creation should not hard-code notification channels.
5. It should be possible to add or remove notification channels for an existing task.

Use **Observer**, **Strategy**, and **Factory** patterns.

---

## Step-by-step solution

### Step 1: Identify the patterns

- **Observer**: `Task` is the subject. Subscribers implement `update(event)`.
- **Strategy**: Each notification channel implements the same `send(message, recipient)` method.
- **Factory**: `NotifierFactory` creates strategy objects from a simple type string. `TaskFactory` creates fully wired tasks.

### Step 2: Define notification strategies

All channels share one interface-like contract: `send(message, recipient)`.

```js
class NotificationStrategy {
  send(message, recipient) {
    throw new Error("NotificationStrategy.send() must be implemented");
  }
}

class ConsoleNotifier extends NotificationStrategy {
  send(message, recipient) {
    console.log(`[CONSOLE -> ${recipient}] ${message}`);
  }
}

class EmailNotifier extends NotificationStrategy {
  send(message, recipient) {
    // In real code, call an email API here.
    console.log(`[EMAIL -> ${recipient}] ${message}`);
  }
}

class WebhookNotifier extends NotificationStrategy {
  send(message, recipient) {
    // In real code, POST to recipient URL here.
    console.log(`[WEBHOOK -> ${recipient}] ${message}`);
  }
}
```

### Step 3: Create factories

Factories remove `new` calls from business logic.

```js
class NotifierFactory {
  static create(type) {
    switch (type) {
      case "console":
        return new ConsoleNotifier();
      case "email":
        return new EmailNotifier();
      case "webhook":
        return new WebhookNotifier();
      default:
        throw new Error(`Unknown notifier type: ${type}`);
    }
  }
}

class TaskFactory {
  static createTask({ id, title, status = "todo" }, notificationConfigs = []) {
    const task = new Task({ id, title, status });

    for (const config of notificationConfigs) {
      const strategy = NotifierFactory.create(config.type);
      task.subscribe(new NotificationObserver(strategy, config.recipient));
    }

    return task;
  }
}
```

### Step 4: Implement the observer

An observer wraps a strategy and recipient. This keeps `Task` independent of delivery details.

```js
class NotificationObserver {
  constructor(strategy, recipient) {
    this.strategy = strategy;
    this.recipient = recipient;
  }

  update(event) {
    const message = `Task ${event.id} "${event.title}" changed: ${event.previousStatus} -> ${event.status}`;
    this.strategy.send(message, this.recipient);
  }
}
```

### Step 5: Implement the subject

`Task` manages observers and emits status-change events.

```js
class Task {
  constructor({ id, title, status = "todo" }) {
    this.id = id;
    this.title = title;
    this.status = status;
    this.observers = new Set();
  }

  subscribe(observer) {
    this.observers.add(observer);
    return () => this.unsubscribe(observer); // convenient unsubscribe function
  }

  unsubscribe(observer) {
    this.observers.delete(observer);
  }

  setStatus(newStatus) {
    if (newStatus === this.status) return;

    const previousStatus = this.status;
    this.status = newStatus;

    this.notify({ previousStatus });
  }

  notify(extra = {}) {
    const event = {
      id: this.id,
      title: this.title,
      status: this.status,
      ...extra,
    };

    for (const observer of this.observers) {
      observer.update(event);
    }
  }
}
```

### Step 6: Add a manager for multiple tasks

This is optional but makes the example feel like a real small application.

```js
class TaskManager {
  constructor() {
    this.tasks = new Map();
  }

  addTask(task) {
    this.tasks.set(task.id, task);
  }

  getTask(id) {
    return this.tasks.get(id);
  }

  changeStatus(id, status) {
    const task = this.getTask(id);
    if (!task) throw new Error(`Task not found: ${id}`);
    task.setStatus(status);
  }
}
```

---

## Final solution

```js
class NotificationStrategy {
  send(message, recipient) {
    throw new Error("NotificationStrategy.send() must be implemented");
  }
}

class ConsoleNotifier extends NotificationStrategy {
  send(message, recipient) {
    console.log(`[CONSOLE -> ${recipient}] ${message}`);
  }
}

class EmailNotifier extends NotificationStrategy {
  send(message, recipient) {
    console.log(`[EMAIL -> ${recipient}] ${message}`);
  }
}

class WebhookNotifier extends NotificationStrategy {
  send(message, recipient) {
    console.log(`[WEBHOOK -> ${recipient}] ${message}`);
  }
}

class NotifierFactory {
  static create(type) {
    switch (type) {
      case "console":
        return new ConsoleNotifier();
      case "email":
        return new EmailNotifier();
      case "webhook":
        return new WebhookNotifier();
      default:
        throw new Error(`Unknown notifier type: ${type}`);
    }
  }
}

class NotificationObserver {
  constructor(strategy, recipient) {
    this.strategy = strategy;
    this.recipient = recipient;
  }

  update(event) {
    const message =
      `Task ${event.id} "${event.title}" changed: ` +
      `${event.previousStatus} -> ${event.status}`;
    this.strategy.send(message, this.recipient);
  }
}

class Task {
  constructor({ id, title, status = "todo" }) {
    this.id = id;
    this.title = title;
    this.status = status;
    this.observers = new Set();
  }

  subscribe(observer) {
    this.observers.add(observer);
    return () => this.unsubscribe(observer);
  }

  unsubscribe(observer) {
    this.observers.delete(observer);
  }

  setStatus(newStatus) {
    if (newStatus === this.status) return;

    const previousStatus = this.status;
    this.status = newStatus;
    this.notify({ previousStatus });
  }

  notify(extra = {}) {
    const event = {
      id: this.id,
      title: this.title,
      status: this.status,
      ...extra,
    };

    for (const observer of this.observers) {
      observer.update(event);
    }
  }
}

class TaskFactory {
  static createTask({ id, title, status = "todo" }, notificationConfigs = []) {
    const task = new Task({ id, title, status });

    for (const config of notificationConfigs) {
      const strategy = NotifierFactory.create(config.type);
      task.subscribe(new NotificationObserver(strategy, config.recipient));
    }

    return task;
  }
}

class TaskManager {
  constructor() {
    this.tasks = new Map();
  }

  addTask(task) {
    this.tasks.set(task.id, task);
  }

  getTask(id) {
    return this.tasks.get(id);
  }

  changeStatus(id, status) {
    const task = this.getTask(id);
    if (!task) throw new Error(`Task not found: ${id}`);
    task.setStatus(status);
  }
}

// Demo
const manager = new TaskManager();

const task = TaskFactory.createTask(
  { id: 1, title: "Write design pattern exercise" },
  [
    { type: "console", recipient: "developer" },
    { type: "email", recipient: "team@example.com" },
  ]
);

manager.addTask(task);

// Add a webhook channel at runtime
const webhookStrategy = NotifierFactory.create("webhook");
const unsubscribeWebhook = task.subscribe(
  new NotificationObserver(webhookStrategy, "https://example.com/webhook")
);

task.setStatus("in-progress");
task.setStatus("done");

// Remove the webhook channel
unsubscribeWebhook();
console.log("\nAfter removing webhook:\n");

task.setStatus("archived");
```

### Why this design is useful

- Adding a new channel only requires a new strategy class and one `case` in `NotifierFactory`.
- `Task` never knows how notifications are delivered.
- Observers can be added or removed without modifying `Task`.
- Factories keep object creation centralized and testable.
- The manager layer can grow into persistence, validation, authorization, etc. without changing the core patterns.

# Design Patterns in JavaScript (Interview Style)

## How I'd Frame It in an Interview

> *"Design patterns are reusable solutions to recurring problems. In JavaScript specifically, I think about them in the context of the language's strengths: first-class functions, prototype-based inheritance, closures, and dynamic typing. I group them by **Creational** (how objects are created), **Structural** (how objects compose), and **Behavioral** (how objects communicate). I also care about trade-offs: patterns add indirection, so I only reach for one when the problem actually shows up."*

Below are the patterns I'd expect to discuss, with production-style implementations.

---

## 1. Module Pattern (Revealing Module)

**When:** You want private state + a public API without classes. Very common in JS because of closures.

```js
const counterModule = (function () {
  // private state — unreachable from outside
  let count = 0;

  function increment() { count++; }
  function decrement() { count--; }
  function reset()     { count = 0; }
  function getCount() { return count; }

  // reveal only what the consumer needs
  return Object.freeze({ increment, decrement, reset, getCount });
})();

counterModule.increment();
counterModule.increment();
console.log(counterModule.getCount()); // 2
// counterModule.count === undefined  (truly private)
```

**Key points**
- Privacy comes from closure scope, not keywords.
- `Object.freeze` prevents the public API from being mutated.
- In modern JS, **ES modules are the de-facto module pattern** — each file has its own scope; `export` is the "revealed" API.

---

## 2. Singleton

**When:** Exactly one instance is needed (config registry, logger, DB connection). 

```js
class Logger {
  static #instance = null; // private static field

  constructor() {
    if (Logger.#instance) {
      return Logger.#instance; // hand back the existing instance
    }
    this.logs = [];
    Logger.#instance = this;
  }

  log(msg) { this.logs.push({ msg, at: Date.now() }); }

  static getInstance() {
    if (!Logger.#instance) new Logger();
    return Logger.#instance;
  }
}

const a = new Logger();
const b = Logger.getInstance();
console.log(a === b); // true
```

**Trade-offs / pitfalls**
- Global mutable state → hard to test (prefer dependency injection).
- In ES modules, a module-level `export const logger = new Logger()` is already a singleton — often cleaner.

---

## 3. Factory (Simple Factory + Factory Method)

**When:** Object creation logic is complex or depends on runtime input; you want to decouple callers from concrete classes.

```js
class Animal {
  constructor(name) { this.name = name; }
  speak() { return `${this.name} makes a sound`; }
}

class Dog extends Animal { speak() { return `${this.name} barks`; } }
class Cat extends Animal { speak() { return `${this.name} meows`; } }
class Bird extends Animal { speak() { return `${this.name} chirps`; } }

// Simple Factory — one function, switches on input
function animalFactory(type, name) {
  switch (type) {
    case 'dog':  return new Dog(name);
    case 'cat':  return new Cat(name);
    case 'bird': return new Bird(name);
    default:     throw new Error(`Unknown animal type: ${type}`);
  }
}

const pet = animalFactory('dog', 'Rex');
console.log(pet.speak()); // "Rex barks"
```

**Factory Method variant** (subclass decides):
```js
class AnimalShelter {
  adopt(name) {
    const animal = this.createAnimal(name); // hook
    animal.vaccinate?.();
    return animal;
  }
  createAnimal(name) { throw new Error('subclass must implement'); }
}
class DogShelter extends AnimalShelter {
  createAnimal(name) { return new Dog(name); }
}
```

---

## 4. Observer (Pub/Sub)

**When:** One-to-many reactive updates (UI state, events, real-time data).

```js
class EventBus {
  constructor() {
    this.listeners = new Map(); // event -> Set of callbacks
  }

  on(event, callback) {
    if (!this.listeners.has(event)) this.listeners.set(event, new Set());
    this.listeners.get(event).add(callback);
    // return an unsubscribe function — prevents leaks
    return () => this.off(event, callback);
  }

  off(event, callback) {
    this.listeners.get(event)?.delete(callback);
  }

  emit(event, payload) {
    for (const cb of this.listeners.get(event) ?? []) {
      try { cb(payload); }
      catch (e) { console.error('listener threw:', e); }
    }
  }
}

const bus = new EventBus();
const unsub = bus.on('login', (user) => console.log('Welcome', user.name));
bus.emit('login', { name: 'Ada' }); // "Welcome Ada"
unsub(); // cleanup
```

**Pitfalls**
- Memory leaks if listeners aren't removed (use the returned unsubscribe).
- Ordering is not guaranteed; don't rely on it.
- For UI, prefer a small store (Redux/Zustand) over a raw event bus to make state predictable.

---

## 5. Decorator

**When:** Add behavior to an object dynamically without subclass explosion. Two common JS flavors.

### A. Functional decorator (higher-order function)
```js
function withLogging(fn) {
  return function (...args) {
    console.log(`→ ${fn.name}(${args.join(', ')})`);
    const result = fn.apply(this, args);
    console.log(`← ${fn.name} returned ${result}`);
    return result;
  };
}

function add(a, b) { return a + b; }
const loggedAdd = withLogging(add);
loggedAdd(2, 3); // logs call + result
```

### B. Class/object decorator (composition)
```js
class Coffee {
  cost() { return 5; }
  description() { return 'Coffee'; }
}

class Milk {
  constructor(coffee) { this.coffee = coffee; }
  cost() { return this.coffee.cost() + 2; }
  description() { return this.coffee.description() + ', milk'; }
}

class Sugar {
  constructor(coffee) { this.coffee = coffee; }
  cost() { return this.coffee.cost() + 1; }
  description() { return this.coffee.description() + ', sugar'; }
}

let drink = new Coffee();
drink = new Milk(drink);
drink = new Sugar(drink);
console.log(drink.description(), drink.cost()); // "Coffee, milk, sugar" 8
```

---

## 6. Strategy

**When:** A family of interchangeable algorithms; pick one at runtime.

```js
class PaymentContext {
  constructor(strategy) { this.strategy = strategy; }
  setStrategy(strategy) { this.strategy = strategy; }
  pay(amount) { return this.strategy.pay(amount); }
}

const strategies = {
  card:   { pay: (a) => `Charged card $${a}` },
  paypal: { pay: (a) => `Paid PayPal $${a}` },
  crypto: { pay: (a) => `Sent crypto $${a}` },
};

const checkout = new PaymentContext(strategies.card);
console.log(checkout.pay(50)); // "Charged card $50"
checkout.setStrategy(strategies.crypto);
console.log(checkout.pay(50)); // "Sent crypto $50"
```

**Key point:** Strategy removes `if/else` chains and makes algorithms testable in isolation. In JS, strategies are often just functions (not classes) since functions are first-class.

---

## 7. Command

**When:** Encapsulate an action as an object — enables undo/redo, queuing, logging.

```js
class TextEditor {
  constructor() { this.text = ''; }
}

class InsertCommand {
  constructor(editor, text, position = null) {
    this.editor = editor;
    this.text = text;
    this.position = position ?? editor.text.length;
  }
  execute() {
    const t = this.editor.text;
    this.editor.text = t.slice(0, this.position) + this.text + t.slice(this.position);
  }
  undo() {
    const t = this.editor.text;
    this.editor.text = t.slice(0, this.position) + t.slice(this.position + this.text.length);
  }
}

class CommandManager {
  constructor() { this.history = []; this.redoStack = []; }
  execute(cmd) {
    cmd.execute();
    this.history.push(cmd);
    this.redoStack = []; // new action invalidates redo
  }
  undo() {
    const cmd = this.history.pop();
    if (cmd) { cmd.undo(); this.redoStack.push(cmd); }
  }
  redo() {
    const cmd = this.redoStack.pop();
    if (cmd) { cmd.execute(); this.history.push(cmd); }
  }
}

const editor = new TextEditor();
const mgr = new CommandManager();
mgr.execute(new InsertCommand(editor, 'Hello'));
mgr.execute(new InsertCommand(editor, ' World', 5));
console.log(editor.text); // "Hello World"
mgr.undo();
console.log(editor.text); // "Hello"
mgr.redo();
console.log(editor.text); // "Hello World"
```

---

## 8. Facade

**When:** A subsystem has a complex API; expose one simplified entry point.

```js
class Amplifier { on() {} setVolume(v) {} }
class DvdPlayer { on() {} play(movie) {} }
class Projector { on() {} setInput(src) {} }
class Lights { dim(level) {} }

class HomeTheaterFacade {
  constructor(amp, dvd, projector, lights) {
    this.amp = amp; this.dvd = dvd;
    this.projector = projector; this.lights = lights;
  }

  watchMovie(movie) {
    this.lights.dim(10);
    this.projector.on();
    this.projector.setInput('dvd');
    this.amp.on();
    this.amp.setVolume(5);
    this.dvd.on();
    this.dvd.play(movie);
  }

  endMovie() {
    this.lights.dim(100);
    this.projector.off?.();
    this.amp.off?.();
    this.dvd.stop?.();
  }
}
```

---

## Bonus: Prototype (the JS-native one)

JS is prototype-based. Prefer `Object.create` / constructor `.prototype` over class sugar when you want delegation.

```js
const animalProto = {
  speak() { return `${this.name} speaks`; },
};

const dogProto = Object.create(animalProto);
dogProto.bark = function () { return `${this.name} barks`; };

const rex = Object.create(dogProto);
rex.name = 'Rex';
console.log(rex.speak()); // "Rex speaks"  (delegated up the chain)
console.log(rex.bark());  // "Rex barks"
```

---

## How I'd Answer "Which One Would You Use Here?"

| Symptom | Pattern |
|---|---|
| Need to hide state + expose API | Module |
| Need exactly one instance | Singleton (or module-level instance) |
| Creation depends on runtime input | Factory |
| Many listeners react to an event | Observer |
| Add features without subclassing | Decorator |
| Swap algorithms at runtime | Strategy |
| Need undo/redo or queueing | Command |
| Tame a messy subsystem | Facade |

**Closing thought:** Patterns are vocabulary, not rules. In modern JS, modules + functions + composition often replace class-heavy patterns (e.g., hooks replace Observer in React). The right answer in an interview is usually *"I'd start simple and refactor toward a pattern when the pain is real."*

---

## Quick Self-Check Questions (often asked after)

1. **Singleton vs Module-level instance?** Module export is simpler and testable via mocking; Singleton class is fine for legacy code.
2. **Observer vs Promise?** Observer = many events over time; Promise = one async result.
3. **Decorator vs Inheritance?** Prefer composition (decorator) when behavior combinations explode combinatorially.
4. **Memory leaks in Observer?** Always unsubscribe; use `WeakMap`/`WeakRef` for auto-cleanup when possible.

# Edge Cases When Using Design Patterns in JavaScript

Below are the most important edge cases for the patterns most commonly used in JS, with runnable code and explanations.

---

## 1. Singleton — Multiple "Instances" from the Same Class

**Edge cases:** module reloads, inheritance, `new` bypass, cross-realm objects.

```js
// Naive singleton
class Singleton {
  static #instance;
  static getInstance() {
    if (!this.#instance) this.#instance = new this();
    return this.#instance;
  }
  constructor() {
    if (Singleton.#instance) throw new Error('Use getInstance()');
  }
}

// EDGE CASE 1: Subclassing breaks the singleton
class Child extends Singleton {}
const a = Singleton.getInstance();
const b = Child.getInstance(); // different instance! #instance is per-class
console.log(a === b); // false

// EDGE CASE 2: `new` still works if constructor isn't guarded
const c = new Singleton(); // throws, but only because we added the guard

// EDGE CASE 3: Cross-realm / iframe — `instanceof` and identity differ
// In an iframe, `window.Singleton !== iframe.contentWindow.Singleton`
```

**Fix:** Use a module-level closure (not a class) and freeze it. For cross-realm safety, compare by a unique `Symbol` or id, not `===` on the constructor.

```js
const Singleton = (() => {
  let instance;
  function create() { return Object.freeze({ id: Math.random() }); }
  return { getInstance() { return instance ??= create(); } };
})();
```

---

## 2. Factory — Losing `this` and Prototype Chain

**Edge cases:** arrow functions as factory methods, `new` misuse, async factories.

```js
class Product { constructor(name) { this.name = name; } }

const factory = {
  create: (name) => new Product(name), // arrow: `this` is lexical
};

// EDGE CASE 1: `new factory.create()` works but `factory.create.call(ctx)` ignores ctx
const p = new factory.create('x'); // OK, but `this` inside arrow is `factory`'s lexical scope

// EDGE CASE 2: Async factory returns a Promise, not an instance
async function asyncFactory() { return new Product('y'); }
const q = asyncFactory();
console.log(q instanceof Product); // false — it's a Promise

// EDGE CASE 3: Factory returning a different constructor than expected
function weirdFactory(type) {
  if (type === 'a') return { kind: 'a' }; // plain object, not Product
  return new Product(type);
}
```

**Fix:** Always document return types; use `async`/`await` at call sites; prefer regular methods when `this` matters.

---

## 3. Observer / PubSub — Memory Leaks & Duplicate Subscriptions

**Edge cases:** strong references preventing GC, double-subscribe, async handlers, error propagation.

```js
class Emitter {
  constructor() { this.listeners = new Map(); }
  on(event, cb) {
    if (!this.listeners.has(event)) this.listeners.set(event, []);
    this.listeners.get(event).push(cb);
  }
  emit(event, ...args) {
    // EDGE CASE 1: mutating array during iteration skips items
    for (const cb of this.listeners.get(event) || []) cb(...args);
    // EDGE CASE 2: throwing listener aborts the rest
  }
}

// EDGE CASE 3: memory leak — handler captures large scope
function leaky() {
  const huge = new Array(1e6).fill(0);
  emitter.on('data', () => console.log(huge.length)); // `huge` retained forever
}

// EDGE CASE 4: duplicate subscription
emitter.on('x', handler);
emitter.on('x', handler); // now fires twice
```

**Fix:** Use `WeakMap`/`WeakRef` for listener storage, dedupe with a `Set`, wrap handlers in try/catch, and provide `off`/`once`.

```js
class SafeEmitter {
  constructor() { this.listeners = new Map(); }
  on(event, cb) {
    const set = this.listeners.get(event) ?? new Set();
    set.add(cb); // Set dedupes by reference
    this.listeners.set(event, set);
  }
  emit(event, ...args) {
    for (const cb of [...(this.listeners.get(event) ?? [])]) {
      try { cb(...args); } catch (e) { console.error(e); }
    }
  }
  off(event, cb) { this.listeners.get(event)?.delete(cb); }
}
```

---

## 4. Module Pattern — Circular Dependencies & Hoisting

**Edge cases:** TDZ, partial exports during circular imports, `this` in CommonJS.

```js
// circular.js
import { b } from './other.js'; // other.js imports from circular.js
export const a = b + 1; // b is undefined at this moment → NaN

// EDGE CASE: hoisting of `const`/`let` exports
export const x = y; // ReferenceError if y declared below with let/const
export function y() {} // function declarations hoist → OK
```

**Fix:** Defer reads (use functions, not top-level values), or restructure to avoid cycles. In CommonJS, `module.exports = ...` overrides; mutating `exports.foo` is safer.

---

## 5. Prototype Pattern — Shared Mutable State

**Edge cases:** reference types on the prototype, `constructor` property, `hasOwnProperty`.

```js
function Animal() {}
Animal.prototype.traits = []; // shared array!
const a = new Animal();
const b = new Animal();
a.traits.push('fast');
console.log(b.traits); // ['fast'] — surprise

// EDGE CASE: constructor property can be reassigned
Animal.prototype = { speak() {} };
const c = new Animal();
console.log(c.constructor === Animal); // false

// EDGE CASE: for...in enumerates inherited props
for (const k in c) console.log(k); // includes speak
```

**Fix:** Initialize reference types in the constructor; restore `constructor`; use `Object.hasOwn` / `hasOwnProperty`.

```js
function Animal() { this.traits = []; }
Animal.prototype.speak = function () {};
Object.defineProperty(Animal.prototype, 'constructor', { value: Animal, writable: true });
```

---

## 6. Decorator — Context Loss & Descriptor Mutability

**Edge cases:** `this` binding, method vs. accessor decorators, stage-3 vs. legacy.

```js
function logged(target, key, descriptor) {
  const original = descriptor.value;
  descriptor.value = function (...args) {
    console.log(key, args);
    return original.apply(this, args); // EDGE: forget `.apply(this)` → `this` is undefined
  };
  return descriptor;
}

class Foo {
  @logged
  greet() { return this.name; } // `this` must be preserved
}
```

**Edge cases with stage-3 decorators:**

```js
function logged(fn, context) {
  return function (...args) {
    console.log(context.name, args);
    return fn.apply(this, args);
  };
}
// EDGE: class decorators receive the class, not instance
// EDGE: field decorators run per-instance; method decorators run once on prototype
```

---

## 7. Strategy — Binding & Selection at Runtime

**Edge cases:** missing strategy, async strategies, `this` in strategy objects.

```js
class Context {
  constructor(strategy) { this.strategy = strategy; }
  run(x) { return this.strategy.execute(x); } // EDGE: if strategy is a plain function, .execute is undefined
}

// Fix: normalize
class Context2 {
  constructor(strategy) {
    this.strategy = typeof strategy === 'function' ? { execute: strategy } : strategy;
  }
  async run(x) {
    if (!this.strategy?.execute) throw new Error('No strategy');
    return this.strategy.execute(x);
  }
}
```

---

## 8. Chain of Responsibility — Async & Termination

**Edge cases:** forgetting to call `next()`, async handlers, infinite loops.

```js
class Handler {
  setNext(h) { this.next = h; return h; }
  handle(req) {
    if (this.canHandle(req)) return this.process(req);
    return this.next?.handle(req); // EDGE: if next is undefined, returns undefined silently
  }
}

// Async version
async handle(req) {
  if (this.canHandle(req)) return this.process(req);
  if (!this.next) throw new Error('Unhandled request');
  return this.next.handle(req);
}
```

---

## 9. State — Invalid Transitions & Shared State

```js
class StateMachine {
  constructor() { this.state = 'idle'; }
  transition(next) {
    // EDGE: no validation → can jump idle → done
    this.state = next;
  }
}

// Fix: explicit transition table
const TRANSITIONS = {
  idle: ['running'],
  running: ['paused', 'done'],
  paused: ['running', 'done'],
};
class SafeSM {
  constructor() { this.state = 'idle'; }
  transition(next) {
    if (!TRANSITIONS[this.state]?.includes(next))
      throw new Error(`Invalid: ${this.state} → ${next}`);
    this.state = next;
  }
}
```

---

## 10. Proxy — Traps, Revocation, and `this`

**Edge cases:** `this` inside traps refers to the proxy (usually fine), but `get` trap returning bound methods; revocable proxies; private fields.

```js
const target = {
  secret: 42,
  reveal() { return this.secret; },
};
const p = new Proxy(target, {
  get(t, prop, receiver) {
    if (prop === 'secret') return 'hidden';
    const v = Reflect.get(t, prop, receiver);
    return typeof v === 'function' ? v.bind(receiver) : v; // EDGE: bind to proxy so `this.secret` → 'hidden'
  },
});

// EDGE: revocable proxy becomes unusable
const { proxy, revoke } = Proxy.revocable(target, {});
revoke();
try { proxy.x; } catch (e) { console.log('revoked throws TypeError'); }

// EDGE: private fields (#x) cannot be proxied access via get trap in older engines;
// accessing #x on a proxy throws TypeError
```

---

## 11. Mixin — Property Collisions & `super`

**Edge cases:** name collisions overwrite silently; `super` resolution.

```js
const A = (Base) => class extends Base {
  log() { return 'A'; }
};
const B = (Base) => class extends Base {
  log() { return 'B'; }
};

// EDGE: order matters, later wins
class C extends A(B(Object)) {} // A's log wins? Actually composition order...
// C.prototype.log === A's log (last applied wraps)

// Collision without warning:
const M1 = (B) => class extends B { value = 1; };
const M2 = (B) => class extends B { value = 2; };
class D extends M1(M2(Object)) {}
console.log(new D().value); // 1 (M1 wins), M2's value silently lost
```

**Fix:** Namespace mixin properties, or detect collisions.

---

## 12. Command — Undo State & Async Execution

**Edge cases:** undo on never-executed command, partial failure, serialization.

```js
class Command {
  execute() {}
  undo() {}
}

class MoveCommand extends Command {
  constructor(obj, dx) { super(); this.obj = obj; this.dx = dx; this.prev = null; }
  execute() { this.prev = this.obj.x; this.obj.x += this.dx; }
  undo() { if (this.prev === null) throw new Error('not executed'); this.obj.x = this.prev; }
}

// EDGE: async command — undo must await
class AsyncCommand extends Command {
  async execute() { await save(); }
  async undo() { await revert(); } // caller must await both
}
```

---

## 13. Facade — Over-abstraction & Leaky Abstraction

```js
// EDGE: facade hides errors that callers need to handle
class Facade {
  async doEverything() {
    await a(); await b(); await c(); // if b throws, c never runs; caller can't retry individual steps
  }
}
```

**Fix:** Expose intermediate results or accept a step callback.

---

## 14. Mediator — Memory Leaks via Colleague References

```js
class Mediator {
  constructor() { this.colleagues = new Set(); }
  register(c) { this.colleagues.add(c); c.mediator = this; } // strong ref both ways → leak
}
// Fix: use WeakRef for colleagues, or unregister on destroy
```

---

## 15. Revealing Module — Shared Private State Across Instances

```js
const Module = (() => {
  let count = 0; // shared across ALL "instances"
  function create() { count++; return { getCount: () => count }; }
  return { create };
})();
const a = Module.create();
const b = Module.create();
console.log(a.getCount(), b.getCount()); // 2, 2 — not per-instance
```

**Fix:** Move `count` inside `create()` if per-instance privacy is needed.

---

## Cross-Cutting Edge Cases

| Concern | Edge Case | Mitigation |
|---|---|---|
| `this` | Arrow functions, detached methods | `.bind`, wrapper, or class fields |
| Async | Fire-and-forget loses errors | `await`, `Promise.allSettled` |
| Equality | `NaN`, `-0`, cross-realm | `Object.is`, Symbol identity |
| Freezing | `Object.freeze` is shallow | Deep freeze recursively |
| Iteration | Mutating collection mid-loop | Snapshot with spread |
| Memory | Closures retain scope | `WeakRef`, `FinalizationRegistry` |
| Types | `typeof null === 'object'` | Explicit null checks |

---

## Summary Checklist

1. **Singleton** → module closure, not class static; guard `new`.
2. **Factory** → normalize sync/async; document return type.
3. **Observer** → `Set` for dedup, try/catch per listener, `off`/`once`, avoid retained scopes.
4. **Module** → avoid circular top-level value reads.
5. **Prototype** → init reference types in constructor; restore `constructor`.
6. **Decorator** → preserve `this` via `.apply`; know stage (legacy vs. 3).
7. **Strategy** → normalize function vs. object; validate presence.
8. **CoR** → handle missing `next`; support async.
9. **State** → transition table; reject invalid.
10. **Proxy** → bind returned methods; handle revocation; avoid private-field traps.
11. **Mixin** → detect collisions; namespace.
12. **Command** → guard undo-before-execute; await async.
13. **Facade** → don't swallow per-step errors.
14. **Mediator** → break strong refs.
15. **Revealing Module** → decide instance vs. shared scope deliberately.

If you want, I can drill into any single pattern (e.g., a full production-grade Observer or a Proxy-based validation layer) with tests.

Here's a thorough implementation of dictionaries/hash maps in JavaScript, from a minimal built-in usage all the way to a from-scratch generic hash map with separate chaining.

## 1. Quick start — built-in `Map` / `Object`

```js
// Map — ordered, any key type, no prototype pollution issues
const dict = new Map();
dict.set('user:42', { name: 'Ada', role: 'admin' });
dict.set(123, 'numeric key'); // keys can be non-strings

console.log(dict.get('user:42'));       // { name: 'Ada', role: 'admin' }
console.log(dict.has(123));            // true
console.log(dict.size);                // 2
dict.delete('user:42');

for (const [k, v] of dict) console.log(k, v);

// Plain object used as a dict (string keys only)
const obj = Object.create(null);        // avoid prototype pollution
obj['a'] = 1;
console.log(obj['a']);                  // 1
```

## 2. From-scratch hash map (hash + collision resolution)

Below is a full generic hash map that:
- Uses polynomial rolling hash with a per-instance seed.
- Resolves collisions by **separate chaining** (array of buckets of `{key, value}`).
- Implements `get`, `set`, `delete`, `has`, `keys`, `values`, `entries`, iteration, `resize` on load factor.
- Supports a pluggable equality function (important for object keys).

```js
// hashmap.js
'use strict';

class HashMap {
  static DEFAULT_CAPACITY = 16;
  static MAX_LOAD_FACTOR = 0.75;

  constructor(capacity = HashMap.DEFAULT_CAPACITY, eq = Object.is) {
    this.capacity = nextPrime(capacity);
    this.size = 0;
    this.eq = eq;
    this.buckets = Array.from({ length: this.capacity }, () => []);
    this.seed = (Math.random() * 0xFFFFFFFF) >>> 0;
  }

  // ---------- hash ----------
  #hash(key) {
    let h = this.seed;
    const s = String(key);
    for (let i = 0; i < s.length; i++) {
      h = (h * 31 + s.charCodeAt(i)) >>> 0;
    }
    return h % this.capacity;
  }

  // ---------- core ----------
  set(key, value) {
    if (this.size >= this.capacity * HashMap.MAX_LOAD_FACTOR) this.#resize();
    const idx = this.#hash(key);
    const bucket = this.buckets[idx];

    for (const node of bucket) {
      if (this.eq(node.key, key)) {
        node.value = value;
        return this;
      }
    }
    bucket.push({ key, value });
    this.size++;
    return this;
  }

  get(key) {
    for (const node of this.buckets[this.#hash(key)]) {
      if (this.eq(node.key, key)) return node.value;
    }
    return undefined;
  }

  has(key) { return this.get(key) !== undefined || this.#hasSentinel(key); }

  #hasSentinel(key) {
    // distinguish "stored undefined" from "missing"
    return this.buckets[this.#hash(key)].some(n => this.eq(n.key, key));
  }

  delete(key) {
    const bucket = this.buckets[this.#hash(key)];
    const i = bucket.findIndex(n => this.eq(n.key, key));
    if (i === -1) return false;
    bucket.splice(i, 1);
    this.size--;
    return true;
  }

  clear() {
    this.buckets = Array.from({ length: this.capacity }, () => []);
    this.size = 0;
  }

  // ---------- resize ----------
  #resize() {
    const old = this.buckets;
    this.capacity = nextPrime(this.capacity * 2);
    this.buckets = Array.from({ length: this.capacity }, () => []);
    this.size = 0;
    for (const bucket of old) for (const { key, value } of bucket) this.set(key, value);
  }

  // ---------- iteration ----------
  *entries() {
    for (const bucket of this.buckets) for (const { key, value } of bucket) yield [key, value];
  }
  *keys()   { for (const [k] of this.entries()) yield k; }
  *values() { for (const [, v] of this.entries()) yield v; }

  forEach(cb, thisArg) {
    for (const [k, v] of this.entries()) cb.call(thisArg, v, k, this);
  }

  [Symbol.iterator]() { return this.entries(); }

  get length() { return this.size; }
}

// ---------- helpers ----------
function isPrime(n) { for (let i = 2; i * i <= n; i++) if (n % i === 0) return false; return n > 1; }
function nextPrime(n) { while (!isPrime(n)) n++; return n; }

module.exports = HashMap;
```

## 3. Runnable smoke test (Node)

```js
// test.js
const HashMap = require('./hashmap');

const m = new HashMap();

// basic set/get
m.set('apple', 5).set('banana', 7).set('cherry', 9);
console.log(m.get('banana'));        // 7
console.log(m.has('cherry'));        // true
console.log(m.delete('apple'));     // true
console.log(m.size);                // 2

// iteration order is insertion-ish (bucket order)
for (const [k, v] of m) console.log(k, v);

// chaining reassign
m.set('banana', 700);
console.log(m.get('banana'));       // 700

// keys/values/entries
console.log([...m.keys()]);         // ['banana','cherry']
console.log([...m.values()]);       // [700, 9]

// forEach
m.forEach((v, k) => console.log('cb', k, v));

// object keys with custom equality (deep eq)
const deepEq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const m2 = new HashMap(8, deepEq);
m2.set({ id: 1 }, 'row-1');
console.log(m2.get({ id: 1 }));     // 'row-1'

// stress: load factor triggers resize
const big = new HashMap();
for (let i = 0; i < 10000; i++) big.set(`k${i}`, i);
console.log(big.size);              // 10000
console.log(big.get('k9999'));      // 9999
console.log('capacity', big.capacity);

// clear
big.clear();
console.log(big.size);              // 0

// sentinel distinguish undefined
const m3 = new HashMap();
m3.set('x', undefined);
console.log(m3.has('x'));          // true
console.log(m3.get('x'));          // undefined
```

Run with:
```bash
node test.js
```

## 4. Design notes / pitfalls

| Concern | Built-in `Map` | From-scratch above |
|---|---|---|
| Key hashing | engine-optimized (hidden) | string hash + chaining |
| Key equality | SameValueZero | pluggable (`eq`) |
| Resize | automatic, amortized | triggered at load factor 0.75 |
| Collision perf | excellent (hash table) | depends on hash quality; chains degrade to O(n) worst case |
| Iteration order | insertion order | bucket order (not insertion) |
| Prototype pollution | none with `Map` | none with `Array` buckets |

### Things to watch for in production

- **Don't use plain objects** for untrusted keys (`{ "__proto__": ... }`).
- **Hash quality matters**: djb2 / polynomial rolling hash is fine; for untrusted input, randomize the seed per instance (done above) and consider FNV-1a to reduce collisions.
- **Load factor**: 0.75 balances space vs. chain length; tune for your access pattern.
- **Equality + hash consistency**: if you change `eq`, the hash must also respect it (two equal keys must hash equally). The above hashes `String(key)`, so object keys rely on deep equality producing identical string forms — only true if both objects serialize identically.
- **Memory**: chaining keeps every node; open addressing (linear/quadratic probing) is more cache-friendly but harder to delete.

## 5. Open-addressing variant (probing)

If you want cache-friendly memory, here's a minimal `set`/`get` using linear probing:

```js
class OpenHashMap {
  constructor(cap = 16) { this.cap = nextPrime(cap); this.size = 0; this.table = new Array(this.cap).fill(null); }
  #idx(key, i) { return (this.#hash(key) + i) % this.cap; }
  #hash(key) { let h = 5381; const s = String(key); for (let c of s) h = ((h << 5) + h + c.charCodeAt(0)) >>> 0; return h % this.cap; }

  set(key, value) {
    for (let i = 0; i < this.cap; i++) {
      const p = this.#idx(key, i);
      const cell = this.table[p];
      if (!cell) { this.table[p] = { key, value }; this.size++; return this; }
      if (cell.key === key) { cell.value = value; return this; }
    }
    throw new Error('map full');
  }
  get(key) {
    for (let i = 0; i < this.cap; i++) {
      const cell = this.table[this.#idx(key, i)];
      if (!cell) return undefined;
      if (cell.key === key) return cell.value;
    }
    return undefined;
  }
}
```

## 6. When to use what

- **Default**: `Map` (fast, spec-backed, any key type).
- **Ordered set of unique values**: `Set`.
- **Need custom equality / hash**: implement from scratch (or use a library like `immutable`).
- **BigInt / cryptographic keys**: built-in `Map` with `Object.is` (default) handles `-0`/`NaN` correctly.

That covers dictionaries/hash maps in JavaScript end-to-end; the first scratch implementation plus the smoke test are fully runnable.

## 1. The idea

A **dictionary / hash map** is a collection of **key → value** pairs where you can:

- Insert a pair: `set(key, value)`
- Look up by key: `get(key)` (expected **O(1)** average)
- Update or delete by key
- Test membership: `has(key)`

Under the hood, keys are fed through a **hash function** that turns them into an array index (a "bucket"). Collisions (two keys → same bucket) are resolved by chaining or open addressing. JavaScript engines (V8, SpiderMonkey, etc.) implement this for both plain objects and `Map`.

---

## 2. Syntax option A — Plain objects (`{}`)

Best for **string/symbol keys** that are known at authoring time.

```js
// Literal
const user = { id: 42, name: "Ada", active: true };

// Access
user.name;            // "Ada"
user["id"];           // 42

// Add / update / delete
user.email = "ada@example.com";
user["role"] = "admin";
delete user.active;

// Membership
"email" in user;      // true
user.hasOwnProperty("id"); // true (avoids inherited props)

// Iteration
for (const key in user) console.log(key, user[key]);
Object.keys(user);    // ["id","name","email","role"]
Object.entries(user); // [["id",42], ...]
```

### Gotchas with objects as dicts
- **Keys are coerced to strings** (except symbols):
  ```js
  const o = {};
  o[1] = "one";
  o["1"] = "str";     // overwrites o[1]!
  Object.keys(o);     // ["1"]
  ```
- **Prototype pollution**: `o.toString` exists even if you never set it. Use `Object.create(null)` for a "pure" dictionary, or check with `hasOwnProperty`.
- No reliable `size` without `Object.keys(o).length`.

```js
const dict = Object.create(null);
dict.foo = 1;
dict.toString;        // undefined (no prototype)
```

---

## 3. Syntax option B — `Map` (built-in hash map)

Use `Map` when you need **any key type**, **insertion order**, **size**, or **frequent add/remove**.

```js
const m = new Map();

// set / get / has / delete
m.set("name", "Ada");
m.set(42, "the answer");          // number key (not coerced)
m.set({ id: 1 }, "obj key");      // object identity key
m.set(NaN, "not a number");       // NaN === NaN inside Map

m.get(42);        // "the answer"
m.has(NaN);       // true
m.size;           // 4
m.delete(42);     // true
m.clear();        // empties

// Initialize from iterable of pairs
const m2 = new Map([["a", 1], ["b", 2]]);

// Iteration (insertion order preserved)
for (const [k, v] of m2) console.log(k, v);
m2.forEach((v, k) => console.log(k, v));
[...m2.keys()];   // ["a","b"]
[...m2.values()]; // [1,2]
[...m2.entries()];
```

### WeakMap (related)
Keys must be objects; entries are **weakly held**, so they can be garbage-collected. Good for private instance data / caching tied to object lifetime.

```js
const cache = new WeakMap();
function getMeta(obj) {
  if (!cache.has(obj)) cache.set(obj, compute(obj));
  return cache.get(obj);
}
```

---

## 4. Object vs. Map — which to pick?

| Need | Prefer |
|---|---|
| String/symbol keys, JSON serialization | Object |
| Numeric/object/function keys | Map |
| Frequent insert/delete, size needed | Map |
| Guaranteed insertion order iteration | Map (objects mostly preserve order for string keys since ES2015, but integer-like keys sort first) |
| Prototype-free semantics | `Object.create(null)` or Map |
| JSON `stringify` | Object (Map serializes as `{}` unless converted) |

**Performance tip:** For hot paths with many keys, `Map` is usually faster for repeated `get/set/delete` and avoids prototype-chain checks.

---

## 5. Typical use cases with examples

### A. Frequency counting (char / word counts)
```js
function countChars(s) {
  const counts = {};
  for (const ch of s) counts[ch] = (counts[ch] ?? 0) + 1;
  return counts;
}
countChars("banana"); // { b:1, a:3, n:2 }
```
With Map (handles any key safely):
```js
const freq = new Map();
for (const w of words) freq.set(w, (freq.get(w) ?? 0) + 1);
```

### B. Indexing / lookup table
```js
const usersById = new Map(users.map(u => [u.id, u]));
const user = usersById.get(42);
```

### C. Memoization / caching
```js
const memo = new Map();
function fib(n) {
  if (n < 2) return n;
  if (memo.has(n)) return memo.get(n);
  const v = fib(n-1) + fib(n-2);
  memo.set(n, v);
  return v;
}
```

### D. Grouping
```js
function groupBy(arr, keyFn) {
  const groups = new Map();
  for (const x of arr) {
    const k = keyFn(x);
    if (!groups.has(k)) groups.set(k, []);
    groups.get(k).push(x);
  }
  return groups;
}
```

### E. Two-sum style hashing
```js
function twoSum(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const comp = target - nums[i];
    if (seen.has(comp)) return [seen.get(comp), i];
    seen.set(nums[i], i);
  }
}
```

### F. Set (unique values) — cousin of hash map
```js
const unique = new Set([1,2,2,3]); // {1,2,3}
unique.has(2); // true
```

---

## 6. Common pitfalls

1. **`NaN` keys in objects**: `o[NaN]` becomes `o["NaN"]`; in `Map`, `NaN` is a valid distinct key (uses SameValueZero).
2. **Integer-like keys sort first** in objects:
   ```js
   const o = { b: 1, 2: 2, a: 3 };
   Object.keys(o); // ["2","b","a"]
   ```
3. **`in` checks prototype**: prefer `hasOwnProperty` or `Object.hasOwn(obj, key)` (ES2022).
4. **Mutating while iterating objects** can skip/visit entries; `Map` iteration is well-defined even if you `set`/`delete` during iteration (new keys may or may not be visited depending on position).
5. **JSON**: `JSON.stringify(new Map())` → `"{}"`; convert first:
   ```js
   JSON.stringify(Object.fromEntries(m));
   ```

---

### Quick mental model

- **Need a plain record / config / JSON-shaped data?** → Object (or `Object.create(null)`).
- **Need a real hash map with arbitrary keys, size, ordering?** → `Map`.
- **Need keys tied to object lifetime / private data?** → `WeakMap`.
- **Need uniqueness only?** → `Set`.

## Mistake: truthiness-based existence check

```js
const names = ["alice", "bob", "carol"];
const indexByName = {};

names.forEach((name, i) => {
  indexByName[name] = i;
});

function getIndex(name) {
  // BUG: index 0 is falsy, so "alice" is treated as missing
  if (indexByName[name]) {
    return indexByName[name];
  }
  return -1;
}

console.log(getIndex("alice")); // -1  (wrong)
console.log(getIndex("bob"));   // 1
```

## Corrected version (using `Map`)

```js
const names = ["alice", "bob", "carol"];
const indexByName = new Map();

names.forEach((name, i) => {
  indexByName.set(name, i);
});

function getIndex(name) {
  // Explicit existence check; value 0 is handled correctly
  if (indexByName.has(name)) {
    return indexByName.get(name);
  }
  return -1;
}

console.log(getIndex("alice")); // 0
console.log(getIndex("bob"));   // 1
console.log(getIndex("zed"));   // -1
```

### What was wrong

- The check `if (indexByName[name])` tests the **value**, not **presence**.  
  When the stored value is falsy (`0`, `""`, `false`, `null`, `undefined`, `NaN`), the branch is skipped even though the key exists.
- Here `"alice"` is at index `0`, so `indexByName["alice"]` is `0`, which is falsy, causing a false negative.

### Why this matters more broadly

Plain objects used as dictionaries have several other pitfalls:

- **Prototype pollution / inherited keys**  
  `{}["toString"]` exists even if you never set it. Membership checks should use `Object.prototype.hasOwnProperty.call(obj, key)` rather than truthiness or `in`.
- **Key coercion**  
  Object keys are always converted to strings, so `obj[1]` and `obj["1"]` collide, and objects as keys become `"[object Object]"`.
- **Iteration hazards**  
  `for...in` walks inherited enumerable properties unless filtered.

`Map` avoids all of these: keys keep their real type, there is no prototype chain, `.has()` gives an explicit existence test, and insertion order is preserved. If you must use a plain object, prefer:

```js
if (Object.prototype.hasOwnProperty.call(indexByName, name)) {
  return indexByName[name];
}
```

Below are the most common pitfalls, grouped into **plain objects used as dictionaries** and **`Map`/`WeakMap`**. Each includes a short example and a fix.

---

## 1. Plain objects coerce keys to strings

```js
const d = {};
d[1] = "one";
d["1"] = "string one";
console.log(d); // { "1": "string one" }

const objKey = { id: 42 };
d[objKey] = "value";
console.log(d); // { "1": "string one", "[object Object]": "value" }
```

**Fix:** use `Map` when keys are not strings (numbers, objects, functions).

```js
const m = new Map();
m.set(1, "one").set("1", "string one").set(objKey, "value");
console.log(m.size); // 3
```

---

## 2. Prototype pollution and inherited keys

```js
const d = {};
console.log("toString" in d); // true (inherited)
console.log(d.hasOwnProperty("toString")); // false

for (const k in d) console.log(k); // nothing own, but inherited props can leak in
```

Keys like `"__proto__"`, `"constructor"`, `"toString"` can overwrite prototype behavior.

```js
const dangerous = {};
dangerous["__proto__"] = { hacked: true };
console.log({}.hacked); // often undefined in modern engines, but still a footgun
```

**Fix:** create a null-prototype object or use `Map`.

```js
const safe = Object.create(null);
safe["__proto__"] = "data";
console.log(safe["__proto__"]); // "data"
console.log(Object.getPrototypeOf(safe)); // null

// Or
const m = new Map();
m.set("toString", 123);
console.log(m.get("toString")); // 123, no prototype collision
```

---

## 3. Numeric-looking string keys are sorted specially

```js
const d = {};
d["10"] = "ten";
d["2"] = "two";
d["1"] = "one";
console.log(Object.keys(d)); // ["1", "2", "10"]  (integer-like keys first, sorted)
```

This breaks assumptions about insertion order for “array-ish” keys.

**Fix:** use `Map` if you need strict insertion order, or use a prefix like `"id:10"`.

```js
const m = new Map();
m.set("10", "ten").set("2", "two").set("1", "one");
console.log([...m.keys()]); // ["10", "2", "1"] (insertion order)
```

---

## 4. `undefined` values are ambiguous with missing keys

```js
const d = {};
d.foo = undefined;
console.log(d.foo === undefined); // true
console.log("foo" in d);           // true  (exists but undefined)
console.log(Object.hasOwn(d, "foo")); // true
```

`if (d.foo)` hides both “missing” and “falsy stored value”.

**Fix:** use `hasOwnProperty` / `Object.hasOwn`, or `Map` with `has()`.

```js
const m = new Map();
m.set("foo", undefined);
console.log(m.has("foo")); // true
console.log(m.get("foo")); // undefined
```

---

## 5. `for...in` includes inherited enumerable properties

```js
Object.prototype.leak = "boom";
const d = { a: 1 };
for (const k in d) console.log(k); // "a", "leak"
delete Object.prototype.leak;
```

**Fix:** use `Object.keys`, `Object.entries`, or `Object.hasOwn` guard.

```js
for (const [k, v] of Object.entries(d)) console.log(k, v);
```

---

## 6. `in` checks properties, not values

```js
const d = { count: 0 };
if ("count" in d) console.log("exists"); // yes
if (d.count) console.log("truthy");       // no, 0 is falsy
```

**Fix:** distinguish existence from truthiness with `hasOwn` / `Map.prototype.has`.

---

## 7. `Map` is not JSON-serializable by default

```js
const m = new Map([["a", 1]]);
console.log(JSON.stringify(m)); // "{}"
```

**Fix:** convert explicitly.

```js
const obj = Object.fromEntries(m);
console.log(JSON.stringify(obj)); // '{"a":1}'

// Reverse
const restored = new Map(Object.entries(JSON.parse('{"a":1}')));
```

Note: this loses non-string keys and `undefined` values.

---

## 8. Mutating a `Map` while iterating

Deleting or adding entries during `for...of` can skip elements or cause unexpected behavior.

```js
const m = new Map([["a",1],["b",2],["c",3]]);
for (const [k] of m) {
  if (k === "a") m.delete("b"); // may skip "b" or still visit depending on state
}
```

**Fix:** iterate over a snapshot.

```js
for (const [k, v] of [...m]) {
  if (k === "a") m.delete("b");
}
```

---

## 9. Object methods as keys collide

```js
const d = {};
d.toString = 42;
console.log(typeof d.toString); // "number" (method overwritten)
console.log(d + "");            // "42" not "[object Object]"
```

**Fix:** use `Map`, or guard with null-prototype objects.

---

## 10. Shallow copy and reference sharing

```js
const original = { nested: { x: 1 } };
const copy = { ...original };
copy.nested.x = 99;
console.log(original.nested.x); // 99 (shared reference)
```

**Fix:** deep clone when needed.

```js
const deep = structuredClone(original);
deep.nested.x = 99;
console.log(original.nested.x); // 1
```

---

## 11. `Object.assign` copies enumerable own properties only

```js
const source = Object.create({ inherited: 1 });
source.own = 2;
const target = Object.assign({}, source);
console.log(target); // { own: 2 } (inherited not copied)
```

This is usually desired, but surprising if you expected full prototype transfer.

**Fix:** be explicit; use `Map` if you want entries as data only.

---

## 12. Wrong size/count APIs

```js
const m = new Map([["a",1],["b",2]]);
const d = { a: 1, b: 2 };

console.log(m.size);        // 2
console.log(Object.keys(d).length); // 2
console.log(d.length);      // undefined (objects have no length)
```

---

## 13. `WeakMap` cannot be inspected or enumerated

```js
const wm = new WeakMap();
const key = {};
wm.set(key, "value");
console.log(wm.size);         // undefined
console.log([...wm]);         // TypeError: not iterable
console.log(wm.has(key));     // true
```

**Use case:** private data tied to object lifetime; not a general dictionary.

---

## 14. `WeakMap` keys must be objects (not primitives)

```js
const wm = new WeakMap();
try { wm.set("str", 1); } catch (e) { console.log(e.message); }
// Invalid value used as weak map key
```

**Fix:** use `Map` for string/number keys.

---

## 15. SameValueZero makes `NaN` and `-0`/`0` collapse in `Map`

```js
const m = new Map();
m.set(NaN, "first");
m.set(NaN, "second");
console.log(m.size); // 1
console.log(m.get(NaN)); // "second"

m.set(0, "zero");
m.set(-0, "neg zero");
console.log(m.size); // 2? Actually 0 and -0 are same key, so still one entry for 0/-0
console.log(m.get(-0)); // "neg zero"
```

In plain objects, `NaN` becomes `"NaN"`, and `0`/`-0` both become `"0"`.

```js
const d = {};
d[NaN] = 1;
d[-0] = 2;
console.log(d); // { "NaN": 1, "0": 2 }
```

---

## 16. Defaulting with `||` drops valid falsy values

```js
const d = { count: 0, name: "" };
const count = d.count || 10; // 10, wrong
const name = d.name || "anon"; // "anon", wrong
```

**Fix:** use nullish coalescing.

```js
const count = d.count ?? 10; // 0
const name = d.name ?? "anon"; // ""
```

---

## 17. Using `delete` is slow/semantically different from `Map.delete`

```js
const d = { a: 1, b: 2 };
delete d.a; // mutates shape; engines may deoptimize
const m = new Map([["a",1],["b",2]]);
m.delete("a"); // intended, O(1) hash removal
```

For hot paths, prefer `Map`; for config objects, `delete` is fine but consider setting to `undefined`.

---

## 18. Object spread does not preserve non-enumerable or symbol props predictably across tools

```js
const sym = Symbol("x");
const d = {};
Object.defineProperty(d, "hidden", { value: 1, enumerable: false });
d[sym] = 2;
const copy = { ...d };
console.log(copy.hidden); // undefined
console.log(copy[sym]);   // 2 (symbols are copied by spread)
```

**Fix:** use `Object.assign` (same behavior) consciously, or structured clone for full property handling.

---

## 19. Map preserves insertion order even after re-setting

```js
const m = new Map();
m.set("a", 1);
m.set("b", 2);
m.set("a", 99); // updates value, keeps original position
console.log([...m]); // [["a", 99], ["b", 2]]
```

Sometimes you want “move to end”; you must delete then re-add.

```js
m.delete("a");
m.set("a", 99); // now last
```

---

## 20. Lookup with `Object.create(null)` loses useful methods

```js
const d = Object.create(null);
console.log(typeof d.toString); // "undefined"
// d.toString() // TypeError
```

**Fix:** call utilities explicitly.

```js
console.log(Object.prototype.toString.call(d)); // "[object Object]"
```

---

## Practical recommendations

| Need | Use |
|---|---|
| String/symbol keys, JSON interop | Plain object + `Object.create(null)` if untrusted keys |
| Arbitrary keys, insertion order, size | `Map` |
| Object-keyed private/ephemeral data | `WeakMap` |
| Deep copy | `structuredClone` |
| Safe existence check | `Object.hasOwn` / `Map.prototype.has` |
| Falsy-safe defaults | `??` |

If you want, I can also provide a small “safe dictionary” wrapper (combining `Map` with JSON serialization) or benchmarks comparing `Map` vs object for large key counts.

## Exercise

**Task:** Write a function `wordFrequency(text)` that returns a plain JavaScript object (a dictionary / hash map) mapping each **normalized word** to how many times it appears in `text`.

Rules:
- Case-insensitive (`"Hello"` and `"hello"` count together).
- Ignore punctuation (treat `",", ".", "!", "?"` etc. as separators).
- Ignore empty tokens.
- Return `{}` for empty/whitespace-only input.

Example:
```js
wordFrequency("Hello, hello! World... world? HELLO")
// => { hello: 3, world: 2 }
```

---

## Step-by-Step Solution

### Step 1: Normalize the input
Lowercase everything so casing doesn't create separate keys.

```js
const lower = text.toLowerCase();
```

### Step 2: Strip punctuation
Replace any run of non-word characters with a single space. `\W+` matches one or more non-word chars (anything not `[a-zA-Z0-9_]`). Note: this keeps underscores as word chars; if you want stricter behavior you can use a custom regex.

```js
const cleaned = lower.replace(/\W+/g, " ");
```

### Step 3: Split into tokens
```js
const tokens = cleaned.trim().split(/\s+/);
```
`trim()` avoids a leading empty string; `split(/\s+/)` handles multiple spaces.

### Step 4: Build the dictionary (hash map)
Iterate tokens and increment counts. Use a plain object as the hash map.

```js
const freq = {};
for (const word of tokens) {
  if (word === "") continue; // safety
  freq[word] = (freq[word] || 0) + 1;
}
```

### Step 5: Handle empty input
If `text` is empty/whitespace, `tokens` becomes `[""]` after split in some edge cases; the `word === ""` guard plus an early return keeps output `{}`.

---

## Final Solution

```js
/**
 * Counts word frequencies in a string, case-insensitively,
 * treating punctuation as separators.
 * @param {string} text
 * @returns {Record<string, number>}
 */
function wordFrequency(text) {
  if (typeof text !== "string" || text.trim() === "") return {};

  const cleaned = text.toLowerCase().replace(/\W+/g, " ").trim();
  if (cleaned === "") return {};

  const tokens = cleaned.split(/\s+/);
  const freq = {};

  for (const word of tokens) {
    freq[word] = (freq[word] || 0) + 1;
  }

  return freq;
}

// --- Tests ---
console.log(wordFrequency("Hello, hello! World... world? HELLO"));
// { hello: 3, world: 2 }

console.log(wordFrequency("  a  b a  "));
// { a: 2, b: 1 }

console.log(wordFrequency(""));
// {}

console.log(wordFrequency("No punctuation here"));
// { no: 1, punctuation: 1, here: 1 }
```

### Why this is a hash map
- **Keys** are normalized words (strings).
- **Values** are counts (numbers).
- Lookup/insert is average **O(1)** per word, so total time is **O(n)** where `n` is the number of characters; space is **O(k)** where `k` is the number of distinct words.

### Optional: using `Map` instead of a plain object
If you need keys that aren't valid identifiers or want insertion order guarantees with non-string keys, use `Map`:

```js
const freq = new Map();
for (const word of tokens) {
  freq.set(word, (freq.get(word) || 0) + 1);
}
return Object.fromEntries(freq); // convert back to plain object if desired
```

Both are valid "dictionary" implementations in JavaScript; plain objects are the idiomatic choice for string keys.

# Dictionaries & Hash Maps in JavaScript

## 1. Concept

A **hash map** (dictionary) stores key–value pairs and answers three questions fast on average:
- **set(key, value)** — insert/overwrite
- **get(key)** — lookup
- **delete(key)** — remove

Average **O(1)**, worst **O(n)** (when everything collides). The trick is a **hash function** that turns a key into a bucket index, plus a **collision strategy** when two keys land in the same bucket.

## 2. Built-ins you actually use

| Tool | Keys | Order | Use when |
|---|---|---|---|
| Plain `Object` | coerced to strings/Symbols | insertion (mostly) | fixed-ish string keys, JSON |
| `Map` | any value, by reference | insertion | arbitrary keys, frequent add/remove, size needed |
| `Set` | values only | insertion | membership tests |
| `WeakMap`/`WeakSet` | object keys only, weak refs | — | caching/metadata without leaking memory |

**Pitfalls with plain objects:** `obj["toString"]` collides with inherited props; keys are strings (`obj[1] === obj["1"]`); no `.size`; prototype pollution risk. Prefer `Map` for a real dictionary.

## 3. How a hash map works internally

1. **Hash** the key → integer.
2. **Modulo** capacity → bucket index.
3. **Collision handling:** here we use *separate chaining* — each bucket is an array of `{key, value}`. (Alternative: open addressing / probing.)
4. **Resize (rehash)** when load factor (`size/capacity`) exceeds ~0.75: double capacity, re-insert everything. Keeps chains short → O(1) expected.

## 4. Implementation

```javascript
/**
 * A hash map with separate chaining and dynamic resizing.
 * Supports arbitrary keys (primitives + objects) via reference equality.
 */
class HashMap {
  constructor(initialCapacity = 16) {
    if (initialCapacity < 1) throw new RangeError("capacity must be >= 1");
    this.capacity = initialCapacity;
    // Each bucket is an array of { key, value } nodes (chaining).
    this.buckets = Array.from({ length: initialCapacity }, () => []);
    this.size = 0;
    this.loadFactor = 0.75;

    // Object keys need stable identity-based hashes.
    this._objectIds = new WeakMap();
    this._nextObjectId = 0;
  }

  // ---------- hashing ----------

  _hashString(s) {
    // djb2-ish, unsigned 32-bit.
    let h = 5381;
    for (let i = 0; i < s.length; i++) {
      h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
    }
    return h;
  }

  _coerceToHashInput(key) {
    if (key === null) return "null:null";
    if (key === undefined) return "undefined:undefined";
    if (typeof key === "symbol") return `symbol:${key.toString()}`;
    if (typeof key === "object") {
      // Identity-based: two distinct objects never share an id.
      if (!this._objectIds.has(key)) {
        this._objectIds.set(key, this._nextObjectId++);
      }
      return `obj:${this._objectIds.get(key)}`;
    }
    return `${typeof key}:${String(key)}`;
  }

  _index(key) {
    return this._hashString(this._coerceToHashInput(key)) % this.capacity;
  }

  // ---------- core API ----------

  /** Insert or overwrite. Returns this for chaining. */
  set(key, value) {
    const bucket = this.buckets[this._index(key)];
    for (const node of bucket) {
      if (node.key === key) {          // reference equality (===)
        node.value = value;
        return this;
      }
    }
    bucket.push({ key, value });
    this.size++;

    if (this.size / this.capacity > this.loadFactor) {
      this._resize(this.capacity * 2);
    }
    return this;
  }

  /** Look up; returns undefined if absent (note: stored undefined is indistinguishable). */
  get(key) {
    const bucket = this.buckets[this._index(key)];
    for (const node of bucket) {
      if (node.key === key) return node.value;
    }
    return undefined;
  }

  /** True if key present, even when its value is undefined. */
  has(key) {
    const bucket = this.buckets[this._index(key)];
    return bucket.some(node => node.key === key);
  }

  /** Remove key. Returns true if it existed. */
  delete(key) {
    const bucket = this.buckets[this._index(key)];
    const i = bucket.findIndex(node => node.key === key);
    if (i === -1) return false;
    bucket.splice(i, 1);
    this.size--;
    return true;
  }

  /** Remove all entries, keep capacity. */
  clear() {
    for (const bucket of this.buckets) bucket.length = 0;
    this.size = 0;
  }

  // ---------- iteration ----------

  *entries() {
    for (const bucket of this.buckets) {
      for (const { key, value } of bucket) {
        yield [key, value];
      }
    }
  }

  *keys() { for (const [k] of this.entries()) yield k; }
  *values() { for (const [, v] of this.entries()) yield v; }

  forEach(cb, thisArg) {
    for (const [k, v] of this.entries()) cb.call(thisArg, v, k, this);
  }

  [Symbol.iterator]() { return this.entries(); }

  // ---------- resizing ----------

  _resize(newCapacity) {
    const oldBuckets = this.buckets;
    this.capacity = newCapacity;
    this.buckets = Array.from({ length: newCapacity }, () => []);
    // Re-hash every entry into the new (larger) table.
    for (const bucket of oldBuckets) {
      for (const { key, value } of bucket) {
        const target = this.buckets[this._index(key)];
        target.push({ key, value });
      }
    }
  }
}
```

## 5. Usage / sanity check

```javascript
const m = new HashMap();
m.set("name", "Ada").set(42, "answer").set({ id: 1 }, "user");

console.log(m.get("name"));   // "Ada"
console.log(m.get(42));        // "answer"
console.log(m.has("missing")); // false
console.log(m.size);           // 3

const objKey = { id: 1 };
m.set(objKey, "x");
console.log(m.get(objKey));    // "x"   (identity, not deep equality)
console.log(m.get({ id: 1 })); // undefined

// iteration order is bucket order, not insertion order
for (const [k, v] of m) console.log(k, v);

m.delete("name");
console.log(m.size); // 2
```

## 6. Interview talking points

- **Why not just use `Object`?** String coercion, prototype chain, no size, ordering caveats.
- **Collision strategies:** separate chaining (above) vs open addressing (linear/quadratic probing, Robin Hood). Chaining is simpler; open addressing is cache-friendly and used in many high-perf maps.
- **Load factor & resizing:** amortized O(1) inserts despite occasional O(n) rehash.
- **Hash quality:** a bad hash (e.g., all keys collide) degrades to O(n) — denial-of-service / HashDoS. Real engines (V8) use randomized seeds per instance.
- **Equality:** JS `Map` uses SameValueZero (like `===` but `NaN === NaN`); this impl uses `===`. To match `Map`, change comparisons to `Object.is`.
- **Weak variants:** keys held weakly; entries vanish when key GC'd — great for caches.

That's the core: hash → bucket → chain → resize. Everything else (`Map`, V8's Swiss Table, etc.) is optimization on top of this idea.

## Edge cases when using dictionaries/hash maps in JavaScript

In JavaScript, a “dictionary” can mean a plain object `{}` or a `Map`. They behave differently, and many bugs come from assuming object keys are arbitrary data.

---

### 1. Prototype pollution and inherited keys

Plain objects inherit from `Object.prototype`, so keys like `toString`, `constructor`, and `hasOwnProperty` already “exist.”

```js
const d = {};
console.log(d.toString); // function, even though never set
console.log("toString" in d); // true

// Dangerous: can overwrite prototype behavior
d.toString = () => "polluted";
console.log({}.toString()); // may be affected depending on scope? Actually own property on d only
```

Safer patterns:

```js
const safeDict = Object.create(null); // no prototype
safeDict.toString = 42;
console.log(safeDict.toString); // 42
console.log("toString" in Object.prototype); // unaffected

// Or use Map
const m = new Map();
m.set("toString", 42);
```

Also beware `__proto__`:

```js
const d = Object.create(null);
d["__proto__"] = { polluted: true }; // stored as a normal string key
console.log(d["__proto__"]); // { polluted: true }
```

With a normal object, `obj.__proto__ = ...` may change the prototype instead of storing data.

---

### 2. Key coercion: objects and arrays become strings

Plain object keys are always strings or symbols. Non-primitive keys are converted with `toString()`.

```js
const d = {};
const key1 = { id: 1 };
const key2 = { id: 2 };

d[key1] = "first";
d[key2] = "second";

console.log(d); // { "[object Object]": "second" }
console.log(Object.keys(d)); // [ "[object Object]" ]
```

Arrays become comma-joined strings:

```js
const d = {};
d[[1, 2]] = "value";
console.log(d["1,2"]); // "value"
```

`Map` preserves key identity and type:

```js
const m = new Map();
const a = { id: 1 };
const b = { id: 2 };

m.set(a, "first");
m.set(b, "second");

console.log(m.get(a)); // "first"
console.log(m.get(b)); // "second"
console.log(m.size); // 2
```

---

### 3. Special primitive key behavior

#### `NaN`

In objects, `NaN` becomes `"NaN"`. In `Map`, all `NaN` keys are the same because `Map` uses SameValueZero.

```js
const d = {};
d[NaN] = 1;
d[NaN] = 2;
console.log(d); // { NaN: 2 }

const m = new Map();
m.set(NaN, 1);
m.set(NaN, 2);
console.log(m.get(NaN)); // 2
console.log(m.size); // 1
```

#### `-0` and `+0`

Both become `"0"` in objects, and `Map` treats them as the same key.

```js
const d = {};
d[-0] = "negative zero";
d[+0] = "positive zero";
console.log(d); // { "0": "positive zero" }

const m = new Map();
m.set(-0, "a");
m.set(+0, "b");
console.log(m.get(-0)); // "b"
console.log(m.size); // 1
```

#### `null` and `undefined`

In objects, they become `"null"` and `"undefined"`. In `Map`, they are valid distinct keys.

```js
const d = {};
d[null] = 1;
d[undefined] = 2;
console.log(d); // { null: 1, undefined: 2 }

const m = new Map();
m.set(null, 1);
m.set(undefined, 2);
console.log(m.get(null)); // 1
console.log(m.get(undefined)); // 2
```

---

### 4. `hasOwnProperty` can be shadowed

If a dictionary contains a key named `hasOwnProperty`, calling the method directly breaks.

```js
const d = { hasOwnProperty: "not a function" };

// d.hasOwnProperty("x"); // TypeError: d.hasOwnProperty is not a function

// Safe:
console.log(Object.prototype.hasOwnProperty.call(d, "hasOwnProperty")); // true

// Map avoids this entirely:
const m = new Map([["hasOwnProperty", 123]]);
console.log(m.has("hasOwnProperty")); // true
```

---

### 5. Enumeration differences

`for...in` includes inherited enumerable properties. `Object.keys` only returns own enumerable string keys. Symbols require separate handling.

```js
const proto = { inherited: 1 };
const d = Object.create(proto);
d.own = 2;
const sym = Symbol("s");
d[sym] = 3;

for (const key in d) console.log("for-in:", key); // own, inherited
console.log(Object.keys(d)); // ["own"]
console.log(Object.getOwnPropertySymbols(d)); // [Symbol(s)]
console.log(Object.getOwnPropertyNames(d)); // ["own"]
```

`Map` iteration is predictable and includes all entries:

```js
const m = new Map();
m.set("a", 1);
m.set(Symbol("s"), 2);
for (const [k, v] of m) console.log(k, v);
```

---

### 6. Key ordering is not simply insertion order for objects

Plain objects sort integer-like keys numerically first, then other string keys by insertion order. Symbols are separate.

```js
const d = {};
d["10"] = "ten";
d["2"] = "two";
d["a"] = "alpha";
d["1"] = "one";

console.log(Object.keys(d)); // ["1", "2", "10", "a"]
```

`Map` preserves insertion order for all keys:

```js
const m = new Map();
m.set("10", "ten");
m.set("2", "two");
m.set("a", "alpha");
console.log([...m.keys()]); // ["10", "2", "a"]
```

---

### 7. Unicode normalization can create distinct keys

Visually identical strings may be different Unicode representations.

```js
const composed = "é"; // U+00E9
const decomposed = "e\u0301"; // e + combining accent

const d = {};
d[composed] = 1;
console.log(d[decomposed]); // undefined
console.log(composed === decomposed); // false

// Normalize before using as key
const normalize = (s) => s.normalize("NFC");
const m = new Map();
m.set(normalize(composed), 1);
console.log(m.get(normalize(decomposed))); // 1
```

---

### 8. Objects as keys are compared by reference

Two objects with identical contents are different keys.

```js
const m = new Map();
m.set({ x: 1 }, "first");
m.set({ x: 1 }, "second");

console.log(m.size); // 2
console.log(m.get({ x: 1 })); // undefined
```

Use a stable primitive key derived from the object when value-based lookup is needed:

```js
function keyOf(obj) {
  return JSON.stringify(obj); // caution: key order, undefined, etc.
}
const m = new Map();
m.set(keyOf({ x: 1 }), "value");
console.log(m.get(keyOf({ x: 1 }))); // "value"
```

---

### 9. Mutating a dictionary while iterating

For objects, adding/removing properties during `for...in` can skip or revisit keys.

```js
const d = { a: 1, b: 2, c: 3 };
for (const key in d) {
  if (key === "b") delete d.c; // may affect iteration
  console.log(key);
}
```

For `Map`, adding a key during iteration may visit it later; deleting an unvisited key skips it.

```js
const m = new Map([["a", 1], ["b", 2]]);
for (const [k] of m) {
  if (k === "a") m.set("c", 3); // "c" will be visited later
  console.log(k);
}
console.log([...m.keys()]); // ["a", "b", "c"]
```

Safer: iterate over a snapshot.

```js
for (const key of [...m.keys()]) {
  // mutate m safely
}
```

---

### 10. Serialization limitations

`JSON.stringify` only serializes own enumerable string-keyed properties. `Map`, `Set`, symbols, functions, and `undefined` values are not serialized as expected.

```js
const d = { a: 1, b: undefined, c: () => {}, [Symbol("s")]: 2 };
console.log(JSON.stringify(d)); // {"a":1}

const m = new Map([["a", 1]]);
console.log(JSON.stringify(m)); // "{}"

// Convert Map to object/array first
console.log(JSON.stringify(Object.fromEntries(m))); // {"a":1}
console.log(JSON.stringify([...m])); // [["a",1]]
```

Also, object key order in JSON is generally insertion order for string keys, but integer-like keys may be reordered by some engines when parsing? Avoid relying on order.

---

### 11. Freezing and sealing

`Object.freeze` prevents adding/removing/changing properties. `Map` remains mutable unless you wrap it.

```js
const d = Object.freeze({ a: 1 });
// d.b = 2; // silently fails in non-strict, throws in strict mode

const m = new Map([["a", 1]]);
// No native freeze for Map; create a read-only wrapper if needed
const readOnly = {
  get: (k) => m.get(k),
  has: (k) => m.has(k),
  size: m.size,
};
```

---

### 12. Memory and reference lifetime

`Map` holds strong references to keys and values, which can prevent garbage collection.

```js
const m = new Map();
let big = { data: new Array(1_000_000) };
m.set(big, "value");
big = null; // object still retained by Map
```

Use `WeakMap` when keys are objects and you want automatic cleanup:

```js
const cache = new WeakMap();
let obj = { id: 1 };
cache.set(obj, "computed");
obj = null; // entry can be garbage collected
```

`WeakMap` cannot be enumerated and keys must be objects.

---

### 13. Arrays are not dictionaries (usually)

Using arrays with non-numeric or sparse keys causes confusion with `length`.

```js
const arr = [];
arr["name"] = "Alice";
arr[1000] = "far";
console.log(arr.length); // 1001
console.log(arr.name); // "Alice"
console.log(Array.isArray(arr)); // true, despite misuse

// Prefer Map or plain object
const dict = Object.create(null);
dict.name = "Alice";
```

---

### 14. Proxy and accessor properties

A “dictionary” may contain getters/setters, so reading a key can have side effects or throw.

```js
const d = {
  get dangerous() {
    throw new Error("getter threw");
  },
};
// d.dangerous; // throws
console.log(Object.hasOwnProperty.call(d, "dangerous")); // true, but value access throws
```

When treating arbitrary objects as dictionaries, prefer `Map` or validate with `Object.getOwnPropertyDescriptor`.

---

### Practical recommendation

- Use `Map` for general-purpose dictionaries, especially with non-string keys, frequent add/remove, or when key identity matters.
- Use `Object.create(null)` for string-keyed dictionaries where prototype safety matters.
- Normalize keys, especially Unicode strings.
- Use `Object.prototype.hasOwnProperty.call` instead of `obj.hasOwnProperty`.
- Use `WeakMap` for object-keyed caches.
- Snapshot keys before mutating during iteration.
- Convert explicitly before serialization.

Dynamic programming (DP) solves problems by breaking them into overlapping subproblems, storing intermediate results, and reusing them. In JavaScript, the two common styles are:

- **Top-down (memoization):** recursively solve subproblems and cache results.
- **Bottom-up (tabulation):** iteratively fill a table of subproblem answers.

Below is a complete, runnable Node.js example demonstrating both styles on Fibonacci, plus two classic DP problems: coin change and longest common subsequence.

```js
// dp-demo.js
// Run with: node dp-demo.js

/* -----------------------------
   1. Fibonacci: top-down memoization
   ----------------------------- */
function fibTopDown(n, memo = new Map()) {
  if (n <= 1) return n;

  if (memo.has(n)) {
    return memo.get(n);
  }

  const result = fibTopDown(n - 1, memo) + fibTopDown(n - 2, memo);
  memo.set(n, result);
  return result;
}

/* -----------------------------
   2. Fibonacci: bottom-up tabulation
   ----------------------------- */
function fibBottomUp(n) {
  if (n <= 1) return n;

  let prev2 = 0; // F(0)
  let prev1 = 1; // F(1)

  for (let i = 2; i <= n; i++) {
    const current = prev1 + prev2;
    prev2 = prev1;
    prev1 = current;
  }

  return prev1;
}

/* -----------------------------
   3. Coin Change: minimum coins
   coins: array of denominations
   amount: target amount
   Returns -1 if impossible
   ----------------------------- */
function coinChange(coins, amount) {
  if (amount === 0) return 0;

  // dp[a] = minimum coins needed to make amount a
  const INF = amount + 1;
  const dp = new Array(amount + 1).fill(INF);
  dp[0] = 0;

  for (let a = 1; a <= amount; a++) {
    for (const coin of coins) {
      if (coin <= a) {
        dp[a] = Math.min(dp[a], dp[a - coin] + 1);
      }
    }
  }

  return dp[amount] === INF ? -1 : dp[amount];
}

/* -----------------------------
   4. Longest Common Subsequence
   Returns length of LCS
   ----------------------------- */
function lcs(a, b) {
  const m = a.length;
  const n = b.length;

  // dp[i][j] = LCS length of a[0..i-1] and b[0..j-1]
  const dp = Array.from({ length: m + 1 }, () =>
    new Array(n + 1).fill(0)
  );

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (a[i - 1] === b[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  return dp[m][n];
}

/* -----------------------------
   Demo / tests
   ----------------------------- */
function assertEqual(actual, expected, label) {
  if (actual !== expected) {
    throw new Error(`${label}: expected ${expected}, got ${actual}`);
  }
  console.log(`PASS: ${label}`);
}

assertEqual(fibTopDown(0), 0, 'fibTopDown(0)');
assertEqual(fibTopDown(1), 1, 'fibTopDown(1)');
assertEqual(fibTopDown(10), 55, 'fibTopDown(10)');
assertEqual(fibTopDown(40), 102334155, 'fibTopDown(40)');

assertEqual(fibBottomUp(0), 0, 'fibBottomUp(0)');
assertEqual(fibBottomUp(1), 1, 'fibBottomUp(1)');
assertEqual(fibBottomUp(10), 55, 'fibBottomUp(10)');
assertEqual(fibBottomUp(40), 102334155, 'fibBottomUp(40)');

assertEqual(coinChange([1, 2, 5], 11), 3, 'coinChange(11)');
assertEqual(coinChange([2], 3), -1, 'coinChange impossible');
assertEqual(coinChange([1], 0), 0, 'coinChange(0)');

assertEqual(lcs('ABCDGH', 'AEDFHR'), 3, 'lcs example');
assertEqual(lcs('', 'ABC'), 0, 'lcs empty');
assertEqual(lcs('AGGTAB', 'GXTXAYB'), 4, 'lcs AGGTAB');

console.log('\nAll DP demos passed.');
```

### How it works

**Fibonacci top-down**
- Starts from `n` and recursively asks for smaller values.
- Stores completed values in a `Map`.
- Avoids exponential recomputation.
- Space and time are `O(n)`, but recursion depth can be a concern for very large `n`.

**Fibonacci bottom-up**
- Starts from the smallest subproblems (`F(0)`, `F(1)`) and builds upward.
- Uses only two variables instead of an array, giving `O(1)` space.
- Usually preferred for simple linear recurrences because it avoids recursion overhead.

**Coin change**
- `dp[a]` represents the minimum coins needed to make amount `a`.
- For each amount, try every coin that fits.
- If no combination works, `dp[amount]` remains `INF`, so return `-1`.
- Time: `O(amount * coins.length)`.
- Space: `O(amount)`.

**Longest common subsequence**
- `dp[i][j]` represents the LCS length of the first `i` characters of `a` and first `j` characters of `b`.
- If characters match, extend the diagonal subproblem.
- Otherwise, take the better of skipping a character from either string.
- Time and space: `O(m * n)`.

### Practical notes

- Use **top-down memoization** when the recursion structure is natural and many subproblems may be unused.
- Use **bottom-up tabulation** when you need predictable iteration order, easier space optimization, or want to avoid recursion limits.
- For very large DP tables, consider memory-efficient variants, such as keeping only the previous row for LCS.
- If values can exceed JavaScript’s safe integer range, use `BigInt` and adjust initialization/comparisons accordingly.

## Dynamic Programming in JavaScript

Dynamic programming (DP) is a technique for solving problems by **breaking them into overlapping subproblems**, solving each once, and storing the result so it isn't recomputed. It applies when a problem has:
- **Overlapping subproblems** – the same smaller problem appears many times.
- **Optimal substructure** – an optimal solution is built from optimal solutions to subproblems.

---

### 1. The two styles

#### Top-down: recursion + memoization
You keep the recursive structure but cache results.

```js
const memo = {};

function fib(n) {
  if (n <= 1) return n;
  if (memo[n] !== undefined) return memo[n];
  return (memo[n] = fib(n - 1) + fib(n - 2));
}
```

#### Bottom-up: iteration + table
You solve smaller subproblems first and build up.

```js
function fib(n) {
  if (n <= 1) return n;
  const dp = [0, 1];
  for (let i = 2; i <= n; i++) dp[i] = dp[i - 1] + dp[i - 2];
  return dp[n];
}
```

**Memoization** is easier to think about; **tabulation** avoids recursion limits and usually uses less overhead.

---

### 2. Idiomatic JavaScript syntax patterns

**Closure-based memoizer** (clean, reusable):
```js
function memoize(fn) {
  const cache = new Map();
  return function (...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };
}
```

**Map vs object**: use `Map` when keys aren't strings or when you need reliable iteration; plain objects are fine for integer-indexed tables.

**Space-optimized DP**: often you only need the last few values.

```js
function fib(n) {
  let prev = 0, curr = 1;
  for (let i = 2; i <= n; i++) [prev, curr] = [curr, prev + curr];
  return n === 0 ? 0 : curr;
}
```

---

### 3. Typical use cases & short examples

#### A. Counting paths / stairs (1D DP)
```js
// climbStairs(n): ways to reach step n (1 or 2 steps at a time)
function climbStairs(n) {
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1; dp[1] = 1;
  for (let i = 2; i <= n; i++) dp[i] = dp[i - 1] + dp[i - 2];
  return dp[n];
}
```

#### B. Coin change (unbounded knapsack flavor)
```js
function coinChange(coins, amount) {
  const INF = Infinity;
  const dp = new Array(amount + 1).fill(INF);
  dp[0] = 0;
  for (let a = 1; a <= amount; a++) {
    for (const c of coins) {
      if (a - c >= 0 && dp[a - c] !== INF) dp[a] = Math.min(dp[a], dp[a - c] + 1);
    }
  }
  return dp[amount] === INF ? -1 : dp[amount];
}
```

#### C. Longest Common Subsequence (2D DP)
```js
function lcs(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      dp[i][j] = a[i - 1] === b[j - 1]
        ? dp[i - 1][j - 1] + 1
        : Math.max(dp[i - 1][j], dp[i][j - 1]);
    }
  }
  return dp[m][n];
}
```

#### D. 0/1 Knapsack
```js
function knapsack(weights, values, capacity) {
  const dp = new Array(capacity + 1).fill(0);
  for (let i = 0; i < weights.length; i++) {
    for (let w = capacity; w >= weights[i]; w--) {   // reverse to avoid reuse
      dp[w] = Math.max(dp[w], dp[w - weights[i]] + values[i]);
    }
  }
  return dp[capacity];
}
```

#### E. Grid path with obstacles (2D, in-place-ish)
```js
function uniquePathsWithObstacles(grid) {
  const m = grid.length, n = grid[0].length;
  const dp = Array.from({ length: m }, () => new Array(n).fill(0));
  dp[0][0] = grid[0][0] === 0 ? 1 : 0;
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === 1) { dp[i][j] = 0; continue; }
      if (i > 0) dp[i][j] += dp[i - 1][j];
      if (j > 0) dp[i][j] += dp[i][j - 1];
    }
  }
  return dp[m - 1][n - 1];
}
```

---

### 4. When to choose DP

- **Brute force has exponential branching** but repeated work (e.g., naive Fibonacci is O(2^n)).
- **State space is small enough** to store (memo table size matters).
- **Transitions are local** – each state depends on a bounded number of previous states.

Time/space trade-offs:
- Memoization: easy to write, but recursion overhead and stack limits (~10^4 frames in V8).
- Tabulation: iterative, stack-safe, often faster.
- Rolling arrays can drop space from O(n) or O(mn) to O(1) or O(min(m,n)).

---

### 5. Common pitfalls

- Forgetting base cases (`dp[0]`, empty strings).
- Mutating the same array in knapsack (wrong direction causes unbounded use).
- Using recursion for huge n without increasing stack or converting to iteration.
- `JSON.stringify` keys in memoizers fail for objects with unstable property order; prefer a custom key or `Map` with tuple keys.
- Off-by-one in indexing (`a[i-1]` vs `a[i]`).

---

### 6. A quick decision checklist

1. Can the answer be expressed from smaller answers? → optimal substructure.
2. Are subproblems repeated? → overlapping → DP helps.
3. What's the state? (index, remaining capacity, position in two strings, etc.)
4. What's the transition? (add/subtract, max/min/sum).
5. What are the base cases?
6. Can I compress space?

If (1) and (2) hold, DP is almost always the right tool.

## Mistaken version

```js
function minPathSum(grid) {
  const m = grid.length;
  const n = grid[0].length;

  // BUG: Array.fill copies the *reference* to one inner array.
  // Every row of `dp` points to the same array.
  const dp = Array(m).fill(Array(n).fill(Infinity));

  dp[0][0] = grid[0][0];

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (i === 0 && j === 0) continue;
      const fromTop = i > 0 ? dp[i - 1][j] : Infinity;
      const fromLeft = j > 0 ? dp[i][j - 1] : Infinity;
      dp[i][j] = grid[i][j] + Math.min(fromTop, fromLeft);
    }
  }

  return dp[m - 1][n - 1];
}
```

## Corrected version

```js
function minPathSum(grid) {
  const m = grid.length;
  const n = grid[0].length;

  // Correct: create a *new* inner array for every row.
  const dp = Array.from({ length: m }, () => Array(n).fill(Infinity));

  dp[0][0] = grid[0][0];

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (i === 0 && j === 0) continue;
      const fromTop = i > 0 ? dp[i - 1][j] : Infinity;
      const fromLeft = j > 0 ? dp[i][j - 1] : Infinity;
      dp[i][j] = grid[i][j] + Math.min(fromTop, fromLeft);
    }
  }

  return dp[m - 1][n - 1];
}
```

## What was wrong and why

The bug is in this line:

```js
const dp = Array(m).fill(Array(n).fill(Infinity));
```

JavaScript arrays store references to objects, including other arrays. `Array(n).fill(Infinity)` creates **one array object**, and `Array(m).fill(thatArray)` puts the **same reference** into every row of `dp`.

So when you later do:

```js
dp[i][j] = grid[i][j] + Math.min(fromTop, fromLeft);
```

you are not updating only row `i`; you are updating the single shared inner array. That makes `dp[i - 1][...]`, `dp[i][...]`, and every other row appear to contain the same values, destroying the dynamic-programming subproblem structure.

The correction:

```js
const dp = Array.from({ length: m }, () => Array(n).fill(Infinity));
```

calls the factory function once per row, producing `m` distinct inner arrays. Each `dp[i]` now has its own storage, so transitions such as `dp[i - 1][j]` and `dp[i][j - 1]` refer to genuinely different previously computed states.

This is a common JavaScript gotcha with DP tables, memoization caches, and any nested mutable structure: `fill(value)` is fine for primitives, but dangerous when `value` is an object or array. Prefer `Array.from`, `map`, or an explicit loop whenever each slot needs its own mutable object.

# Common Pitfalls When Working with Dynamic Programming in JavaScript

Below are the pitfalls I see most often, each with a broken example and the corrected version.

---

## 1. Using plain objects as memo tables with non-primitive keys

JavaScript coerces object keys to strings. Two distinct objects/arrays become the same key (`"[object Object]"`), and `NaN`/`-0` get weird string forms.

```js
// ❌ Broken: all arrays collapse to "[object Object]"
const memo = {};
function dp(arr) {
  if (memo[arr]) return memo[arr];
  // ...
  memo[arr] = result;
  return result;
}
dp([1, 2]);   // computes
dp([3, 4]);   // returns cached result for [1,2]! wrong
```

```js
// ✅ Fix: serialize keys, or use a Map with a canonical key
const memo = new Map();
function key(arr) { return arr.join(','); }  // pick a stable serializer
function dp(arr) {
  const k = key(arr);
  if (memo.has(k)) return memo.get(k);
  // ...
  memo.set(k, result);
  return result;
}
// Or use Map with the array itself only if you keep references stable.
```

**Takeaway:** decide on a canonical key scheme up front. For multi-arg recursion, use template strings: `` `${i}|${j}|${flag}` ``.

---

## 2. Mutating a cached result

If your DP returns an array/object and the caller mutates it, the cache is corrupted for future callers.

```js
// ❌ Broken
const memo = new Map();
function paths(grid, i, j) {
  if (i === 0 && j === 0) return [[0, 0]];
  const k = `${i},${j}`;
  if (memo.has(k)) return memo.get(k); // returns shared reference
  const res = [];
  if (i > 0) for (const p of paths(grid, i-1, j)) res.push([...p, [i,j]]);
  if (j > 0) for (const p of paths(grid, i, j-1)) res.push([...p, [i,j]]);
  memo.set(k, res);
  return res;
}
const a = paths(g, 2, 2);
a[0].push([9,9]);   // silently corrupts cache
const b = paths(g, 2, 2); // b now contains the mutated path
```

```js
// ✅ Fix: return defensive copies, or cache immutable values
function paths(grid, i, j) {
  // ...
  memo.set(k, res);
  return res.map(p => p.map(c => [...c])); // copy on return
}
```

Better yet, avoid storing paths; store counts or parent pointers and reconstruct.

---

## 3. Stack overflow from deep recursion

JS engines have a call stack limit (~10⁴–10⁵ frames). Top-down memoization on large inputs (e.g., `n = 10⁵` Fibonacci, or long strings) crashes.

```js
// ❌ Crashes for large n
function fib(n, memo = {}) {
  if (n < 2) return n;
  if (memo[n] !== undefined) return memo[n];
  return memo[n] = fib(n-1, memo) + fib(n-2, memo);
}
fib(100000); // RangeError: Maximum call stack size exceeded
```

```js
// ✅ Fix: convert to bottom-up iteration
function fib(n) {
  if (n < 2) return n;
  let a = 0, b = 1;
  for (let i = 2; i <= n; i++) [a, b] = [b, a + b];
  return b;
}
```

For DP that genuinely needs recursion (tree DP), increase stack via trampolining or rewrite iteratively with an explicit stack.

---

## 4. Loop-variable capture in closures (classic `var` bug)

When building transitions inside loops, closures over `var` capture the final value.

```js
// ❌ All transitions use the last i
const dp = new Array(n+1).fill(0);
for (var i = 0; i < n; i++) {
  setTimeout(() => { dp[i+1] = Math.max(dp[i+1], dp[i] + val[i]); }, 0);
}
```

```js
// ✅ Use let (block scope) — and beware async DP entirely (see #14)
for (let i = 0; i < n; i++) {
  dp[i+1] = Math.max(dp[i+1], dp[i] + val[i]);
}
```

---

## 5. Off-by-one in table dimensions

DP arrays are usually sized `n+1` (or `(m+1)×(n+1)`). Mixing `n` and `n-1` is the #1 source of `undefined` propagation.

```js
// ❌ dp has length n, but we read dp[n]
function knapsack(W, weights, values) {
  const n = weights.length;
  const dp = new Array(n).fill(0);        // should be n+1
  for (let i = 1; i <= n; i++)
    for (let w = W; w >= weights[i-1]; w--)
      dp[w] = Math.max(dp[w], dp[w - weights[i-1]] + values[i-1]);
  return dp[W];   // dp[W] is undefined if W >= n
}
```

```js
// ✅ Size tables to the problem's natural bounds
function knapsack(W, weights, values) {
  const n = weights.length;
  const dp = new Array(W + 1).fill(0);   // capacity dimension
  for (let i = 0; i < n; i++)
    for (let w = W; w >= weights[i]; w--)
      dp[w] = Math.max(dp[w], dp[w - weights[i]] + values[i]);
  return dp[W];
}
```

---

## 6. Wrong iteration order (0/1 vs unbounded knapsack)

Iterating weight ascending makes an item reusable (unbounded); descending makes it 0/1. Mixing these up silently changes the problem.

```js
// Intended 0/1 knapsack but written as unbounded:
for (let i = 0; i < n; i++)
  for (let w = weights[i]; w <= W; w++)   // ❌ ascending → item reusable
    dp[w] = Math.max(dp[w], dp[w - weights[i]] + values[i]);

// ✅ 0/1: iterate capacity descending
for (let i = 0; i < n; i++)
  for (let w = W; w >= weights[i]; w--)
    dp[w] = Math.max(dp[w], dp[w - weights[i]] + values[i]);
```

---

## 7. Shared mutable default arguments (memo persists across calls)

A default param object is created once per function definition, not per call — but here the issue is subtler: reusing a memo across inputs with different dimensions.

```js
// ❌ Memo keyed only by i,j ignores grid identity; stale across test cases
const memo = {};
function minPath(grid, i, j) {
  const k = `${i},${j}`;
  if (memo[k] !== undefined) return memo[k];
  // ...
}
// Running on grid A then grid B returns A's answers.
```

```js
// ✅ Scope memo to the invocation, or include a grid hash in the key
function minPath(grid) {
  const m = grid.length, n = grid[0].length;
  const memo = new Map();
  function dfs(i, j) {
    const k = `${i},${j}`;
    if (memo.has(k)) return memo.get(k);
    // ...
    memo.set(k, v);
    return v;
  }
  return dfs(m-1, n-1);
}
```

---

## 8. `undefined` vs `0` in memo checks

`if (memo[k])` treats a legitimately computed `0` as a cache miss, causing exponential blowup.

```js
// ❌ dp value 0 (e.g., empty subsequence) re-triggers computation
if (memo[k]) return memo[k];
```

```js
// ✅ Use has() or a sentinel
if (memo.has(k)) return memo.get(k);
// or
if (memo[k] !== undefined) return memo[k];
```

But careful: if a real answer can be `undefined`, use `has` or a `Symbol` sentinel.

---

## 9. Floating-point / precision issues in counting problems

DP counts can exceed `Number.MAX_SAFE_INTEGER` (2⁵³−1). Coin-change counts, path counts on large grids, etc.

```js
// ❌ Loses precision
function uniquePaths(m, n) {
  // combinatorial DP; for large m,n returns inaccurate integer
  const dp = Array.from({length: m}, () => new Array(n).fill(1));
  for (let i = 1; i < m; i++)
    for (let j = 1; j < n; j++)
      dp[i][j] = dp[i-1][j] + dp[i][j-1];
  return dp[m-1][n-1];
}
uniquePaths(35, 35); // not exact
```

```js
// ✅ Use BigInt when exact counts matter
function uniquePaths(m, n) {
  const dp = Array.from({length: m}, () => new Array(n).fill(1n));
  for (let i = 1; i < m; i++)
    for (let j = 1; j < n; j++)
      dp[i][j] = dp[i-1][j] + dp[i][j-1];
  return dp[m-1][n-1];
}
```

Mixing `BigInt` and `Number` in arithmetic throws — keep types consistent throughout.

---

## 10. String concatenation inside recursion (O(n²) blowup)

Building strings by `+` in DP (e.g., edit distance reconstruction, palindrome partitioning) creates O(n) copies per step.

```js
// ❌ O(n²) memory/time even with memo
function minInsertions(s, i, j, acc = '') { /* builds strings */ }
```

```js
// ✅ Store lengths / indices; reconstruct at the end via parent pointers
// Or use array of chars and join once.
```

Same applies to array `.concat` / spread in tight loops — prefer in-place mutation with rollback, or store indices.

---

## 11. Initializing DP tables with the wrong identity

`0` is wrong for minimization (should be `Infinity`); `Infinity` is wrong for maximization / counting (should be `0` or `-Infinity`).

```js
// ❌ Min-cost path initialized to 0 → answer 0
const dp = Array.from({length: m}, () => new Array(n).fill(0));
for (...) dp[i][j] = Math.min(dp[i-1][j], dp[i][j-1]) + cost;

// ✅
const dp = Array.from({length: m}, () => new Array(n).fill(Infinity));
dp[0][0] = cost[0][0];
```

For maximization with "choose subset" semantics, initialize to `-Infinity` (or `-1` for "impossible"), not `0`, otherwise empty selection masquerades as a valid answer.

---

## 12. Forgetting base cases / boundary conditions

Off-by-one in base cases propagates `NaN`/`undefined` through the whole table.

```js
// ❌ dp[0][j] and dp[i][0] left as default for min-path-sum
for (let i = 1; i < m; i++)
  for (let j = 1; j < n; j++)
    dp[i][j] = Math.min(dp[i-1][j], dp[i][j-1]) + grid[i][j];
// first row/column stay Infinity → whole table Infinity
```

```js
// ✅ Seed boundaries explicitly
for (let j = 0; j < n; j++) dp[0][j] = (j ? dp[0][j-1] : 0) + grid[0][j];
for (let i = 0; i < m; i++) dp[i][0] = (i ? dp[i-1][0] : 0) + grid[i][0];
```

---

## 13. Mutating the input during DP

Some solutions “mark visited” by writing into the input grid (e.g., setting to `1`/`0`). This breaks re-runs and parallel calls.

```js
// ❌ Destroys input
function numIslands(grid) {
  // DFS mutates grid[i][j] = '0'
}
```

```js
// ✅ Use a separate visited set/array, or clone input at entry
const seen = new Set();
// or: const g = grid.map(row => [...row]);
```

---

## 14. Doing DP asynchronously

DP relies on synchronous, deterministic completion order. Wrapping transitions in `Promise`/`setTimeout`/`async` breaks dependency ordering and explodes memory.

```js
// ❌ Async transitions; dependencies resolve out of order
async function dp(i) {
  const a = await dp(i-1);
  const b = await dp(i-2);
  return a + b;
}
```

```js
// ✅ Keep the DP core synchronous; only the I/O around it async
function dpSync(n) { /* pure sync */ }
async function handler(req) { const r = dpSync(req.n); ... }
```

If you truly need concurrency, DP is the wrong tool — use divide-and-conquer with memo carefully, or accept sequential.

---

## 15. Map vs Object memo performance on hot paths

For integer keys with dense ranges, a plain `Array` is faster than `Map`/`Object`. For sparse or string keys, `Map` is better. Profile before assuming.

```js
// Dense 1D: array is fastest
const dp = new Array(n + 1);

// Sparse / multi-dim: Map
const memo = new Map();

// Object: prototype pollution risk with keys like "__proto__"
const bad = {};
bad["__proto__"] = 5;   // silently fails or pollutes
```

Use `Object.create(null)` if you must use an object, or prefer `Map`.

---

## 16. Not compressing space when possible

Many DPs only need the previous row/column. Keeping full 2D tables wastes memory and can cause GC pressure.

```js
// ❌ O(mn) space for edit distance
const dp = Array.from({length: m+1}, () => new Array(n+1).fill(0));
```

```js
// ✅ O(n) space
let prev = new Array(n+1).fill(0);
for (let i = 1; i <= m; i++) {
  const cur = new Array(n+1).fill(0);
  cur[0] = i;
  for (let j = 1; j <= n; j++)
    cur[j] = s1[i-1] === s2[j-1] ? prev[j-1] : 1 + Math.min(prev[j], cur[j-1], prev[j-1]);
  prev = cur;
}
```

Caveat: space compression breaks reconstruction — keep full table if you need the path.

---

## 17. Comparing states by reference in memo (Map with object keys)

Even with `Map`, two distinct object literals with identical contents are different keys. Without a serializer you recompute everything.

```js
const memo = new Map();
memo.set({a:1}, 42);
memo.get({a:1}); // undefined
```

Fix: canonicalize (sort keys, join) or use a primitive key.

---

## 18. Ignoring `null`/`undefined` input shape

DP code often assumes non-empty arrays. Guard inputs.

```js
function lis(nums) {
  if (!nums || nums.length === 0) return 0;
  // ...
}
```

---

## Quick checklist before shipping DP code

- [ ] Memo key is canonical and primitive (or stable serializer).
- [ ] Memo check uses `has()` / `!== undefined`, not truthiness.
- [ ] Recursion depth ≤ ~10⁴, else iterative.
- [ ] Table dimensions are `+1` where needed; boundaries seeded.
- [ ] Iteration order matches 0/1 vs unbounded semantics.
- [ ] Initialization identity matches min/max/count semantics.
- [ ] Large counts use `BigInt`.
- [ ] No mutation of cached results or inputs.
- [ ] Space compressed only when reconstruction isn't needed.
- [ ] DP core is synchronous.

If you want, tell me a specific problem (e.g., "longest common subsequence with reconstruction" or "knapsack with item tracking") and I'll show a pitfall-free implementation tailored to it.

## Exercise

**Problem:** Given coin denominations `coins = [1, 3, 4]` and an amount `n`, find the **minimum number of coins** needed to make exactly `n`. If it is impossible, return `-1`.

Examples:
- `n = 6` → `2` (3 + 3)
- `n = 7` → `2` (3 + 4)
- `n = 2` → `2` (1 + 1)
- `n = 0` → `0`

---

## Step 1: Understand the recurrence

Let `dp[x]` = minimum coins needed to make amount `x`.

For each amount `x`, try every coin `c`:
- If `c <= x`, then `dp[x] = min(dp[x], dp[x - c] + 1)`

Base case:
- `dp[0] = 0` (zero coins make zero)
- `dp[x] = Infinity` for `x > 0` initially (unknown)

This is optimal substructure: the best way to make `x` uses the best way to make `x - c`.

---

## Step 2: Naive recursion (for intuition)

```js
function minCoinsNaive(coins, n) {
  if (n === 0) return 0;
  if (n < 0) return Infinity;
  let best = Infinity;
  for (const c of coins) {
    best = Math.min(best, 1 + minCoinsNaive(coins, n - c));
  }
  return best;
}
```

This recomputes the same subproblems many times → exponential time.

---

## Step 3: Memoized recursion (top-down DP)

```js
function minCoinsMemo(coins, n) {
  const memo = new Map();
  function solve(x) {
    if (x === 0) return 0;
    if (x < 0) return Infinity;
    if (memo.has(x)) return memo.get(x);
    let best = Infinity;
    for (const c of coins) {
      best = Math.min(best, 1 + solve(x - c));
    }
    memo.set(x, best);
    return best;
  }
  const res = solve(n);
  return res === Infinity ? -1 : res;
}
```

Time: `O(n * coins.length)`, Space: `O(n)`.

---

## Step 4: Bottom-up tabulation (iterative DP)

```js
function minCoinsDP(coins, n) {
  if (n === 0) return 0;
  const dp = new Array(n + 1).fill(Infinity);
  dp[0] = 0;

  for (let x = 1; x <= n; x++) {
    for (const c of coins) {
      if (c <= x && dp[x - c] !== Infinity) {
        dp[x] = Math.min(dp[x], dp[x - c] + 1);
      }
    }
  }

  return dp[n] === Infinity ? -1 : dp[n];
}
```

---

## Step 5: Reconstruct the actual coins used

Often you also need the combination, not just the count.

```js
function minCoinsWithChoice(coins, n) {
  if (n === 0) return { count: 0, coins: [] };
  const dp = new Array(n + 1).fill(Infinity);
  const choice = new Array(n + 1).fill(-1); // which coin was last used
  dp[0] = 0;

  for (let x = 1; x <= n; x++) {
    for (const c of coins) {
      if (c <= x && dp[x - c] + 1 < dp[x]) {
        dp[x] = dp[x - c] + 1;
        choice[x] = c;
      }
    }
  }

  if (dp[n] === Infinity) return { count: -1, coins: [] };

  // backtrack
  const used = [];
  let x = n;
  while (x > 0) {
    const c = choice[x];
    used.push(c);
    x -= c;
  }
  return { count: dp[n], coins: used };
}
```

---

## Step 6: Test

```js
console.log(minCoinsDP([1, 3, 4], 6)); // 2
console.log(minCoinsDP([1, 3, 4], 7)); // 2
console.log(minCoinsDP([1, 3, 4], 2)); // 2
console.log(minCoinsDP([1, 3, 4], 0)); // 0
console.log(minCoinsDP([1, 3, 4], 5)); // 2 (1+4)
console.log(minCoinsWithChoice([1, 3, 4], 7));
// { count: 2, coins: [3, 4] } (order may vary)
```

---

## Final solution (recommended)

Use bottom-up tabulation for clarity and predictable performance:

```js
function minCoins(coins, n) {
  if (n === 0) return 0;
  const dp = new Array(n + 1).fill(Infinity);
  dp[0] = 0;

  for (let amount = 1; amount <= n; amount++) {
    for (const coin of coins) {
      if (coin <= amount && dp[amount - coin] !== Infinity) {
        dp[amount] = Math.min(dp[amount], dp[amount - coin] + 1);
      }
    }
  }

  return dp[n] === Infinity ? -1 : dp[n];
}
```

**Complexity:** Time `O(n * k)` where `k = coins.length`, Space `O(n)`.

**Key idea:** Build answers for small amounts first, then reuse them to solve larger amounts—classic dynamic programming.

## Dynamic Programming (DP) — Interview Answer

### What is DP?

Dynamic programming is an optimization technique for problems that have two properties:

1. **Overlapping subproblems** — the same smaller problem is solved many times.
2. **Optimal substructure** — the optimal solution to the whole problem can be built from optimal solutions to subproblems.

Instead of recomputing subproblems, DP stores (caches) their results. In JavaScript this is usually done with:

- **Top-down (memoization):** recursive + cache.
- **Bottom-up (tabulation):** iterative array/table filled in dependency order.

### When to use DP?

- You can define a state (e.g., `dp[i]`, `dp[i][j]`).
- You can write a recurrence (transition) between states.
- You want min/max count/ways/length, not just “exists”.

### Complexity idea

If a naive recursive solution has exponential branching but only `O(states)` distinct subproblems, DP turns it into `O(states × transitions)`.

---

## Core JavaScript Implementation

Below are clean, idiomatic examples. Start with the simplest (Fibonacci), then a generic memoizer, then two classic DP patterns (Coin Change and 0/1 Knapsack).

### 1. Fibonacci: top-down vs bottom-up vs space-optimized

```js
// Top-down memoization
function fibMemo(n, memo = new Map()) {
  if (n <= 1) return n;
  if (memo.has(n)) return memo.get(n);

  const value = fibMemo(n - 1, memo) + fibMemo(n - 2, memo);
  memo.set(n, value);
  return value;
}

// Bottom-up tabulation
function fibTab(n) {
  if (n <= 1) return n;
  const dp = [0, 1];
  for (let i = 2; i <= n; i++) {
    dp[i] = dp[i - 1] + dp[i - 2];
  }
  return dp[n];
}

// Space-optimized bottom-up (only last two states matter)
function fibOptimized(n) {
  if (n <= 1) return n;
  let prev2 = 0, prev1 = 1;
  for (let i = 2; i <= n; i++) {
    const curr = prev1 + prev2;
    prev2 = prev1;
    prev1 = curr;
  }
  return prev1;
}
```

### 2. Generic memoizer (useful in interviews)

```js
function memoize(fn) {
  const cache = new Map();
  return function (...args) {
    // Key must uniquely represent arguments.
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);

    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };
}

// Example usage:
const fib = memoize(function (n) {
  if (n <= 1) return n;
  return fib(n - 1) + fib(n - 2);
});
```

> Note: `JSON.stringify` keys are fine for small primitive args; for complex objects, use a custom key or WeakMap.

### 3. Coin Change (unbounded knapsack style) — min coins for amount

**State:** `dp[i]` = minimum coins to make amount `i`.  
**Transition:** try each coin: `dp[i] = min(dp[i], dp[i - coin] + 1)`.

```js
function coinChange(coins, amount) {
  // dp[i] = min coins for amount i; Infinity = unreachable
  const dp = new Array(amount + 1).fill(Infinity);
  dp[0] = 0; // base case: 0 coins make amount 0

  for (let i = 1; i <= amount; i++) {
    for (const coin of coins) {
      if (coin <= i && dp[i - coin] !== Infinity) {
        dp[i] = Math.min(dp[i], dp[i - coin] + 1);
      }
    }
  }

  return dp[amount] === Infinity ? -1 : dp[amount];
}
```

### 4. 0/1 Knapsack — max value within capacity

**State:** `dp[i][w]` = max value using first `i` items with capacity `w`.  
**Transition:** skip or take item `i-1`.

```js
function knapsack(weights, values, capacity) {
  const n = weights.length;
  // dp[w] = best value for capacity w (space-optimized to 1D)
  const dp = new Array(capacity + 1).fill(0);

  for (let i = 0; i < n; i++) {
    // Traverse backwards so each item is used at most once (0/1)
    for (let w = capacity; w >= weights[i]; w--) {
      dp[w] = Math.max(dp[w], values[i] + dp[w - weights[i]]);
    }
  }

  return dp[capacity];
}
```

### 5. Longest Common Subsequence (2D DP)

```js
function lcs(text1, text2) {
  const m = text1.length, n = text2.length;
  // dp[i][j] = LCS length of first i chars of text1 and first j of text2
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (text1[i - 1] === text2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }
  return dp[m][n];
}
```

