## 2. Browser — File Reading & Writing

Browsers cannot freely touch the filesystem for security. You have two realistic options:

### A) Read a user-selected file (FileReader / File API)

```html
<!-- read.html -->
<input type="file" id="picker">
<pre id="out"></pre>
<script>
  const picker = document.getElementById("picker");
  const out = document.getElementById("out");

  picker.addEventListener("change", async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // Modern: file.text() / file.arrayBuffer()
    const text = await file.text();
    out.textContent = text;

    // Or via FileReader (older):
    // const reader = new FileReader();
    // reader.onload = () => out.textContent = reader.result;
    // reader.readAsText(file);
  });
</script>
```

### B) Read **and** write with the File System Access API (Chromium browsers)

```js
// Requires user gesture + HTTPS/localhost
async function openAndSave() {
  // READ
  const [handle] = await window.showOpenFilePicker();
  const file = await handle.getFile();
  const text = await file.text();
  console.log("Read:", text);

  // WRITE (needs permission)
  const writable = await handle.createWritable();
  await writable.write(text.toUpperCase());
  await writable.close();
  console.log("Saved");
}

// CREATE a new file
async function createNew() {
  const handle = await window.showSaveFilePicker({
    suggestedName: "example.txt",
    types: [{ description: "Text", accept: { "text/plain": [".txt"] } }],
  });
  const w = await handle.createWritable();
  await w.write("Created from the browser\n");
  await w.close();
}
```

### C) Download a file (no write to disk path)

```js
function downloadText(filename, content) {
  const blob = new Blob([content], { type: "text/plain" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}
```

