## 3. Cross-cutting checklist

| Concern | Node.js | Browser |
|---|---|---|
| Cancel/missing | ENOENT / empty `files` | `AbortError` / empty list |
| Large data | Streams (`pipeline`) | `file.stream()` |
| Crash safety | Atomic rename via temp | N/A (download/save) |
| Concurrency | `'wx'` / lockfile | Single tab usually |
| Security | Path traversal checks | MIME sniff, sandboxed FS |
| Encoding | Strip BOM, normalise CRLF | `TextDecoder` with `fatal: true` |
| Resource cleanup | `finally { fh.close() }` | Revoke object URLs |

### Quick “safe read” helper (Node)

```js
import { readFile } from 'node:fs/promises';

export async function readTextSafe(path, { allowMissing = false } = {}) {
  let raw;
  try { raw = await readFile(path, 'utf8'); }
  catch (e) {
    if (allowMissing && e.code === 'ENOENT') return null;
    throw e;
  }
  // strip BOM + normalise
  const text = raw.charCodeAt(0) === 0xFEFF ? raw.slice(1) : raw;
  return text.replace(/\r\n/g, '\n');
}
```

### Quick “safe read” helper (Browser)

```js
async function readTextSafe(file) {
  if (!file || file.size === 0) return '';
  const buf = await file.arrayBuffer();
  const text = new TextDecoder('utf-8', { fatal: true }).decode(buf);
  return text.charCodeAt(0) === 0xFEFF ? text.slice(1) : text;
}
```

