Below is a single, runnable Node.js file that demonstrates several functional-programming techniques in JavaScript: pure functions, immutability, higher-order functions, currying, composition, the `Maybe`/`Either` monads, memoization, lazy generators, and trampolined recursion.

Save it as `fp-demo.js` and run with `node fp-demo.js`.

```js
// fp-demo.js
// Run: node fp-demo.js

'use strict';

/* ============================================================
 * 0. Tiny FP utility belt
 * ============================================================ */

const identity = (x) => x;

const compose = (...fns) => (x) => fns.reduceRight((v, f) => f(v), x);
const pipe = (...fns) => (x) => fns.reduce((v, f) => f(v), x);

// Currying for fixed-arity functions
const curry = (fn) => function curried(...args) {
  if (args.length >= fn.length) return fn(...args);
  return (...rest) => curried(...args, ...rest);
};

/* ---------- Maybe monad ---------- */
const Maybe = (value) => ({
  isNothing: value == null,
  map: (fn) => (value == null ? Maybe(null) : Maybe(fn(value))),
  flatMap: (fn) => (value == null ? Maybe(null) : fn(value)),
  getOrElse: (def) => (value == null ? def : value),
  toString: () => `Maybe(${value})`,
});

/* ---------- Either monad ---------- */
const Left = (x) => ({
  tag: 'Left',
  map: () => Left(x),
  flatMap: () => Left(x),
  getOrElse: (def) => def,
  toString: () => `Left(${x})`,
});
const Right = (x) => ({
  tag: 'Right',
  map: (f) => Right(f(x)),
  flatMap: (f) => f(x),
  getOrElse: () => x,
  toString: () => `Right(${x})`,
});
const Either = { Left, Right };

/* ---------- Immutability helpers ---------- */
const groupBy = curry((keyFn, xs) =>
  xs.reduce((acc, x) => {
    const k = keyFn(x);
    return { ...acc, [k]: [...(acc[k] || []), x] }; // new objects/arrays only
  }, {})
);

/* ---------- Memoization ---------- */
const memoize = (fn) => {
  const cache = new Map();
  return (...args) => {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const result = fn(...args);
    cache.set(key, result);
    return result;
  };
};

/* ---------- Lazy sequences ---------- */
function* naturals(start = 0) {
  let n = start;
  while (true) yield n++;
}
const take = (n, gen) => {
  const out = [];
  for (let i = 0; i < n; i++) {
    const r = gen.next();
    if (r.done) break;
    out.push(r.value);
  }
  return out;
};

/* ---------- Trampolined recursion (avoids stack overflow) ---------- */
const trampoline = (fn) => (...args) => {
  let result = fn(...args);
  while (typeof result === 'function') result = result();
  return result;
};

/* ============================================================
 * 1. Domain data (immutable inputs)
 * ============================================================ */

const users = Object.freeze([
  { id: 1, name: 'Alice', email: 'alice@example.com', active: true },
  { id: 2, name: 'Bob',   email: null,                active: true },
  { id: 3, name: 'Carol', email: 'carol@example.com', active: false },
]);

const orders = Object.freeze([
  { id: 101, userId: 1, items: [{ sku: 'A', qty: 2, price: 10 }, { sku: 'B', qty: 1, price: 5 }], coupon: 0.10 },
  { id: 102, userId: 2, items: [{ sku: 'C', qty: 1, price: 20 }], coupon: 0.00 },
  { id: 103, userId: 1, items: [], coupon: 0.20 },
  { id: 104, userId: 99, items: [{ sku: 'D', qty: 1, price: 15 }], coupon: 0.00 },
]);

/* ============================================================
 * 2. Pure domain functions
 * ============================================================ */

const orderSubtotal = (order) =>
  order.items.reduce((acc, it) => acc + it.qty * it.price, 0);

const applyCoupon = curry((rate, amount) => amount * (1 - rate));

const orderTotal = (order) => applyCoupon(order.coupon)(orderSubtotal(order));

// Validation predicates (pure)
const isActive = (u) => u.active === true;
const hasEmail = (u) => typeof u.email === 'string' && u.email.includes('@');
const validUser = (u) => isActive(u) && hasEmail(u);

// Lookup wrapped in Maybe
const findUserMaybe = curry((users, id) => Maybe(users.find((u) => u.id === id)));

/* ============================================================
 * 3. Processing pipeline (Either for richer errors)
 * ============================================================ */

// Validate + enrich a single order, returning Either<Error, EnrichedOrder>
const validateOrder = (users) => (order) => {
  const userM = findUserMaybe(users, order.userId);

  if (userM.isNothing) return Either.Left(`order ${order.id}: unknown user ${order.userId}`);

  const user = userM.getOrElse(null);
  if (!validUser(user)) return Either.Left(`order ${order.id}: user ${user.name} invalid`);

  if (!Array.isArray(order.items) || order.items.length === 0)
    return Either.Left(`order ${order.id}: no items`);

  return Either.Right({
    ...order,                       // immutable copy
    user,
    subtotal: orderSubtotal(order),
    total: orderTotal(order),
  });
};

/* ============================================================
 * 4. Run the pipeline
 * ============================================================ */

const results = orders.map(validateOrder(users));

const successes = results.filter((r) => r.tag === 'Right').map((r) => r.getOrElse(null));
const failures  = results.filter((r) => r.tag === 'Left').map((r) => r.getOrElse(null));

console.log('=== Validation results ===');
console.log('Successes:', successes.map((o) => ({ id: o.id, user: o.user.name, total: o.total })));
console.log('Failures :', failures);

/* Group successful orders by user (immutably) */
const byUser = groupBy((o) => o.user.name, successes);

const userSummary = Object.entries(byUser).map(([name, os]) => ({
  name,
  orderCount: os.length,
  totalSpent: os.reduce((acc, o) => acc + o.total, 0),
}));

console.log('\n=== Per-user summary ===');
console.log(userSummary);

/* ============================================================
 * 5. Demonstrate compose / pipe / point-free style
 * ============================================================ */

const formatMoney = (n) => `$${n.toFixed(2)}`;
const shout = (s) => s.toUpperCase();

// point-free: transform a user summary into a display string
const summarizeUser = pipe(
  (u) => `${u.name}: ${u.orderCount} orders, ${formatMoney(u.totalSpent)}`,
  shout
);

console.log('\n=== Point-free formatting ===');
userSummary.map(summarizeUser).forEach((s) => console.log(s));

/* ============================================================
 * 6. Memoization demo (pure function cached)
 * ============================================================ */

const expensiveTax = (amount, rate) => {
  // pretend heavy work
  let x = amount;
  for (let i = 0; i < 1000; i++) x = x * 1.000001;
  return x * rate;
};
const memoTax = memoize(expensiveTax);

console.log('\n=== Memoization ===');
console.time('first');
console.log(memoTax(100, 0.2).toFixed(4));
console.timeEnd('first');
console.time('second (cached)');
console.log(memoTax(100, 0.2).toFixed(4));
console.timeEnd('second (cached)');

/* ============================================================
 * 7. Lazy sequences demo
 * ============================================================ */

const squares = pipe(
  (xs) => xs.map((n) => n * n)
)(take(8, naturals(1)));

console.log('\n=== Lazy: first 8 squares ===');
console.log(squares);

/* ============================================================
 * 8. Trampolined recursion demo
 * ============================================================ */

const sumList = trampoline(function rec(xs, acc = 0) {
  if (xs.length === 0) return acc;
  return () => rec(xs.slice(1), acc + xs[0]); // thunk, no stack growth
});

// A list large enough to blow a naive recursive call stack
const bigList = Array.from({ length: 200000 }, (_, i) => i + 1);
console.log('\n=== Trampolined sum of 1..200000 ===');
console.log(sumList(bigList)); // 20000100000
```

### What this demonstrates

1. **Pure functions** – `orderSubtotal`, `validUser`, `orderTotal` never mutate inputs and always return the same output for the same input.
2. **Immutability** – `Object.freeze` on source data, and updates use spread (`{ ...order }`, `[...arr]`) instead of mutation.
3. **Higher-order functions** – `curry`, `memoize`, `trampoline`, `validateOrder(users)` (function returning a function).
4. **Currying & partial application** – `applyCoupon(rate)(amount)`, `findUserMaybe(users, id)`, `groupBy(keyFn, xs)`.
5. **Composition** – `compose`/`pipe` build `summarizeUser` point-free.
6. **Monads for control flow** – `Maybe` for nullable lookups, `Either` for validation with typed success/failure.
7. **Memoization** – caches pure `expensiveTax` results.
8. **Lazy evaluation** – `naturals` generator + `take` computes only what’s needed.
9. **Safe recursion** – `trampoline` turns deep recursion into a loop, avoiding stack overflow.

All of these patterns compose naturally and keep state changes explicit and localized, which is the essence of functional programming in JavaScript.

## 1. The Idea

Functional programming (FP) in JavaScript treats computation as the evaluation of **pure functions**:

- **Pure function**: same inputs → same output, no side effects (no mutation of external state, no I/O).
- **Immutability**: data is never mutated in place; you create new values.
- **First-class functions**: functions are values you can pass, return, and store.
- **Composition**: build complex behavior by composing small, focused functions.
- **Declarative style**: describe *what* to compute, not *how* (loops → `map`/`filter`/`reduce`).

JS is multi-paradigm, so FP is a *style* you apply, not a language constraint.

---

## 2. Syntax & Language Features That Enable FP

### Arrow functions
```js
const double = x => x * 2;
const add = (a, b) => a + b;
```

### `const` + immutability by convention
```js
const user = { name: "Ada", age: 30 };
const older = { ...user, age: user.age + 1 }; // new object
```

### Array methods (the FP workhorses)
```js
const nums = [1, 2, 3, 4, 5];
const evens   = nums.filter(n => n % 2 === 0);   // [2, 4]
const doubled = nums.map(n => n * 2);            // [2, 4, 6, 8, 10]
const sum     = nums.reduce((acc, n) => acc + n, 0); // 15
```

### Higher-order functions
```js
const withTiming = fn => (...args) => {
  const t = performance.now();
  const result = fn(...args);
  console.log(`${fn.name}: ${performance.now() - t}ms`);
  return result;
};
```

### Closures & currying
```js
const multiply = a => b => a * b;
const double = multiply(2);
double(5); // 10
```

### Composition
```js
const compose = (...fns) => x => fns.reduceRight((v, f) => f(v), x);
const pipe    = (...fns) => x => fns.reduce((v, f) => f(v), x);

const trim     = s => s.trim();
const lower    = s => s.toLowerCase();
const slugify  = pipe(trim, lower, s => s.replace(/\s+/g, "-"));

slugify("  Hello World  "); // "hello-world"
```

### Destructuring & rest/spread
```js
const pickName = ({ first, last }) => `${first} ${last}`;
const merge = (a, b) => ({ ...a, ...b });
```

