## Implementation 1: Activity Selection (earliest finish)

```js
/**
 * Greedy: Activity Selection
 * Given intervals [start, end], return max set of mutually non-overlapping intervals.
 * Strategy: sort by end time ascending, always pick the one that finishes earliest.
 * Time: O(n log n), Space: O(n) for sorted copy.
 *
 * @param {Array<{start:number, end:number}>} intervals
 * @returns {Array<{start:number, end:number}>}
 */
function activitySelection(intervals) {
  if (!intervals || intervals.length === 0) return [];

  // 1) Sort by finish time (greedy key).
  const sorted = [...intervals].sort((a, b) => a.end - b.end);

  const chosen = [];
  let lastEnd = -Infinity;

  // 2) Iterate, picking any activity that starts at/after lastEnd.
  for (const act of sorted) {
    if (act.start >= lastEnd) {
      chosen.push(act);
      lastEnd = act.end; // commit locally; never revisit
    }
  }
  return chosen;
}

// --- demo ---
const acts = [
  { start: 1, end: 4 },
  { start: 3, end: 5 },
  { start: 0, end: 6 },
  { start: 5, end: 7 },
  { start: 3, end: 8 },
  { start: 5, end: 9 },
  { start: 6, end: 10 },
  { start: 8, end: 11 },
  { start: 2, end: 13 },
  { start: 12, end: 14 },
];
console.log(activitySelection(acts)); // 4 activities: (1,4),(5,7),(8,11),(12,14)
```

