## Implementation 3: Coin Change (canonical coin systems)

```js
/**
 * Greedy: Coin Change (works for canonical systems like USD).
 * Returns min coins to make amount, or -1 if impossible.
 * NOTE: not optimal for arbitrary denominations (use DP there).
 *
 * @param {number[]} coins - denominations (any order)
 * @param {number} amount
 * @returns {number}
 */
function greedyCoinChange(coins, amount) {
  if (amount === 0) return 0;
  // Largest first is the greedy key for canonical systems.
  const sorted = [...coins].sort((a, b) => b - a);
  let remaining = amount;
  let count = 0;

  for (const c of sorted) {
    if (remaining >= c) {
      const q = Math.floor(remaining / c);
      count += q;
      remaining -= q * c;
    }
  }
  return remaining === 0 ? count : -1;
}

// --- demo ---
console.log(greedyCoinChange([1, 5, 10, 25], 63)); // 6 (25+25+10+1+1+1)
```

