### Notes for real-world use

- This is educational; production code should usually use JavaScript’s built-in `Map`/`Object`.
- A production hash table also **resizes** when the load factor gets too high and uses a stronger hash to resist collisions.
- Separate chaining keeps insertion simple; open addressing (linear/quadratic probing) is the other common strategy.

## Hash Tables in JavaScript — Interview‑Style Answer

### 1. Mental model
A **hash table** maps keys to values. The promise is **O(1) average** `get` / `set` / `delete`.  
It works in three stages:

1. **Hash function** – turns a key into an integer.
2. **Compression / index** – `hash % buckets.length` picks a slot.
3. **Collision resolution** – two keys can land in the same slot; we handle that.

Two common collision strategies:
- **Separate chaining** – each bucket is a list/array of `{key, value}`.
- **Open addressing** – probe for the next empty slot (`linear`, `quadratic`, `double` hashing).

Trade‑offs: chaining is simpler and degrades gracefully; open addressing has better cache locality but needs careful deletion (tombstones) and resizing.

### 2. JS realities
- Plain objects (`{}`) coerce keys to strings — bad for numbers/objects/`null`.
- `Map` / `WeakMap` are built‑in hash tables with real key semantics (SameValueZero) and insertion order.
- Here we implement our own to show the innards.

### 3. Design choices for this implementation
- **Separate chaining** with arrays of `{ key, value }`.
- Strict key equality using `Object.is` (handles `NaN`, etc.).
- Hashing: djb2 over `String(key)` — fast and good enough for an interview demo. *(Production: use a stronger mixer and per‑table random seed to avoid hash‑flooding attacks.)*
- **Resize** when `size / capacity > 0.75` (load factor). Rehash everything — O(n), but amortized O(1) per insert.
- Keys/objects: we coerce to string only for hashing, but compare with the original key. Distinct objects that stringify identically will collide in the *same* bucket but are still distinguished by equality — correct but slightly slower.

### 4. Implementation

```js
/**
 * A minimal hash table using separate chaining.
 * Supports arbitrary keys (primitives and objects) via strict equality.
 */
class HashTable {
  constructor(initialCapacity = 8) {
    this.capacity = initialCapacity;
    this.size = 0;
    // Array of buckets; each bucket is an array of { key, value } entries.
    this.buckets = new Array(this.capacity).fill(null).map(() => []);
  }

  /** djb2 string hash — fast, decent distribution. */
  _hash(key) {
    const s = String(key);
    let hash = 5381;
    for (let i = 0; i < s.length; i++) {
      // hash = hash * 33 + charCode
      hash = (hash << 5) + hash + s.charCodeAt(i);
    }
    // >>> 0 coerces to unsigned 32-bit; keeps index non-negative
    return (hash >>> 0) % this.capacity;
  }

  /** Insert or update. Returns this for chaining. */
  set(key, value) {
    const idx = this._hash(key);
    const bucket = this.buckets[idx];

    // Update existing entry if key already present (SameValueZero-ish via Object.is)
    for (const entry of bucket) {
      if (Object.is(entry.key, key)) {
        entry.value = value;
        return this;
      }
    }

    // New entry
    bucket.push({ key, value });
    this.size++;

    // Resize if load factor exceeded
    if (this.size / this.capacity > 0.75) {
      this._resize(this.capacity * 2);
    }
    return this;
  }

  /** Get value or undefined. */
  get(key) {
    const idx = this._hash(key);
    for (const entry of this.buckets[idx]) {
      if (Object.is(entry.key, key)) return entry.value;
    }
    return undefined;
  }

  /** Delete; returns true if something was removed. */
  delete(key) {
    const idx = this._hash(key);
    const bucket = this.buckets[idx];
    for (let i = 0; i < bucket.length; i++) {
      if (Object.is(bucket[i].key, key)) {
        bucket.splice(i, 1);
        this.size--;
        return true;
      }
    }
    return false;
  }

  has(key) {
    return this.get(key) !== undefined || this._hasExplicitUndefined(key);
  }

  // Helper to distinguish "key absent" from "value is undefined"
  _hasExplicitUndefined(key) {
    const idx = this._hash(key);
    return this.buckets[idx].some((e) => Object.is(e.key, key));
  }

  /** Double capacity and rehash all entries. */
  _resize(newCapacity) {
    const oldBuckets = this.buckets;
    this.capacity = newCapacity;
    this.buckets = new Array(newCapacity).fill(null).map(() => []);
    // Reset size; set() will re-increment
    this.size = 0;

    for (const bucket of oldBuckets) {
      for (const { key, value } of bucket) {
        this.set(key, value);
      }
    }
  }

  /** Iterable of [key, value] pairs. */
  *entries() {
    for (const bucket of this.buckets) {
      for (const { key, value } of bucket) {
        yield [key, value];
      }
    }
  }

  *keys()   { for (const [k] of this.entries()) yield k; }
  *values() { for (const [, v] of this.entries()) yield v; }

  clear() {
    this.buckets = new Array(this.capacity).fill(null).map(() => []);
    this.size = 0;
  }

  toString() {
    return `HashTable(size=${this.size}, capacity=${this.capacity})`;
  }
}

// ---------------- Demo ----------------
const ht = new HashTable(4);
ht.set('name', 'Ada').set('age', 36).set('lang', 'JS');
console.log(ht.get('name'));        // 'Ada'
console.log(ht.has('age'));        // true
console.log([...ht.entries()]);    // insertion order NOT guaranteed (bucket order)
ht.delete('age');
console.log(ht.get('age'));        // undefined
console.log(ht.size, ht.capacity); // 2, 8 (resized once)

// Object keys work by reference equality
const o1 = { id: 1 }, o2 = { id: 1 };
ht.set(o1, 'first').set(o2, 'second');
console.log(ht.get(o1)); // 'first'  (distinct objects)
console.log(ht.get(o2)); // 'second'

// NaN handling (Object.is)
ht.set(NaN, 'not a number');
console.log(ht.get(NaN)); // 'not a number'
```

### 5. Complexity summary
| Operation | Average | Worst (all keys collide) |
|-----------|---------|--------------------------|
| `set`     | O(1)    | O(n)                     |
| `get`     | O(1)    | O(n)                     |
| `delete`  | O(1)    | O(n)                     |
| `resize`  | O(n) amortized over inserts | — |

### 6. Follow‑up talking points
- **Why resize at 0.75?** Keeps chains short; memory vs speed trade‑off. Open addressing often uses ~0.7.
- **Worst case** is adversarial collisions. Mitigations: randomized hash seeds, stronger mixer (e.g., SipHash, FNV‑1a), or universal hashing.
- **Open addressing variant**: store entries directly in the array; on delete use a `DELETED` sentinel; probing sequence matters for clustering.
- **JS built‑ins**: `Map` preserves insertion order and handles any key; `WeakMap` allows GC of keys and is great for metadata attached to objects.
- **Hash of objects**: production code may want a stable serialization (`JSON.stringify`) or a unique id, not `String(obj)`.

If you want, I can next walk through an **open‑addressing** version (linear probing + tombstones) or a **Robin Hood hashing** variant.

Below are the most important edge cases when using hash-table-like structures in JavaScript, with both plain objects (`{}`) and `Map`.

### 1. Key coercion in plain objects
Plain objects stringify keys. `Map` preserves key types.

```js
const o = {};
o[1] = 'number 1';
o['1'] = 'string 1';
console.log(o); // { '1': 'string 1' }  (same key)

const m = new Map();
m.set(1, 'number 1');
m.set('1', 'string 1');
console.log(m.size); // 2
```

### 2. Object keys become `"[object Object]"`
Multiple distinct objects collapse to one string key in a plain object.

```js
const o = {};
const a = { id: 1 };
const b = { id: 2 };
o[a] = 'A';
o[b] = 'B';
console.log(o); // { '[object Object]': 'B' }

const m = new Map();
m.set(a, 'A');
m.set(b, 'B');
console.log(m.get(a)); // 'A'
console.log(m.size);  // 2
```

### 3. Prototype pollution and inherited keys
Plain objects inherit from `Object.prototype`. Use `Object.create(null)` or `Map` when keys are untrusted.

```js
const unsafe = {};
unsafe['__proto__'] = { polluted: true }; // may alter prototype chain

const safe = Object.create(null);
safe['__proto__'] = 'stored as own property';
console.log(Object.prototype.hasOwnProperty.call(safe, '__proto__')); // true

// Or use Map for arbitrary keys
const m = new Map();
m.set('__proto__', 'safe');
```

### 4. `NaN` keys
In a plain object, `NaN` becomes `"NaN"`. In `Map`, all `NaN` values are the same key via `SameValueZero`.

```js
const o = {};
o[NaN] = 'first';
o['NaN'] = 'second';
console.log(o); // { NaN: 'second' }

const m = new Map();
m.set(NaN, 'first');
m.set(NaN, 'second');
console.log(m.get(NaN)); // 'second'
console.log(m.size);     // 1
```

### 5. `-0` and `+0`
`Map` treats `-0` and `+0` as the same key. Plain objects stringify both to `"0"`.

```js
const m = new Map();
m.set(-0, 'minus zero');
m.set(+0, 'plus zero');
console.log(m.size); // 1
console.log(m.get(-0)); // 'plus zero'
```

### 6. Symbols
Symbols are valid own keys in plain objects and are not coerced. Not enumerable by `Object.keys`.

```js
const sym = Symbol('id');
const o = {};
o[sym] = 42;
console.log(Object.keys(o));        // []
console.log(Object.getOwnPropertySymbols(o)); // [ Symbol(id) ]
console.log(o[sym]);               // 42
```

### 7. Integer-like keys and iteration order
Plain objects sort integer-like string keys numerically before other keys. `Map` preserves insertion order.

```js
const o = {};
o['z'] = 1;
o['2'] = 2;
o['1'] = 3;
console.log(Object.keys(o)); // ['1', '2', 'z']

const m = new Map([['z',1],['2',2],['1',3]]);
console.log([...m.keys()]); // ['z', '2', '1']
```

### 8. Iteration and deletion
Deleting an entry during iteration is allowed, but adding entries may cause them to be visited. Use a snapshot if needed.

```js
const m = new Map([['a',1],['b',2],['c',3]]);
for (const [k,v] of m) {
  if (k === 'b') m.delete(k); // okay
}
console.log([...m.keys()]); // ['a', 'c']

// Adding during iteration may visit new key
const m2 = new Map([['a',1]]);
for (const [k] of m2) {
  if (k === 'a') m2.set('z', 99);
}
console.log([...m2.keys()]); // ['a', 'z'] in many engines
```

### 9. Object reference equality in `Map`
`Map` uses SameValueZero, so two different objects are different keys even if deeply equal.

```js
const m = new Map();
m.set({ x: 1 }, 'first');
m.set({ x: 1 }, 'second');
console.log(m.size); // 2
```

### 10. `WeakMap` restrictions
`WeakMap` keys must be objects, are weakly held, and the collection is not iterable or sizable.

```js
const wm = new WeakMap();
const key = { id: 1 };
wm.set(key, 'value');
console.log(wm.get(key)); // 'value'
// wm.size; // undefined
// for (const k of wm) {} // TypeError: not iterable
```

### 11. Enumerating vs. own-property checks
`for...in` includes inherited enumerable properties. Prefer `Object.hasOwn` or `hasOwnProperty`.

```js
const base = { inherited: 1 };
const o = Object.create(base);
o.own = 2;

for (const k in o) console.log('for...in:', k); // inherited, own
console.log(Object.keys(o)); // ['own']
console.log(Object.hasOwn(o, 'inherited')); // false
```

### 12. Serialization issues
`JSON.stringify` ignores symbols, functions, `undefined`, and does not serialize `Map`/`Set` meaningfully.

```js
const o = { a: 1, sym: Symbol('x'), fn() {}, undef: undefined };
console.log(JSON.stringify(o)); // {"a":1}

const m = new Map([['a', 1]]);
console.log(JSON.stringify(m)); // {}  (not useful)
```

### 13. Frozen or sealed objects
You cannot add or delete properties on frozen/sealed objects.

```js
const o = Object.freeze({ a: 1 });
try {
  o.b = 2;
} catch (e) {
  console.log('Cannot add to frozen object');
}
console.log(o.b); // undefined
```

### 14. Custom `toString` collisions
Objects with custom `toString` can collide as plain-object keys.

```js
const o = {};
const x = { toString() { return 'key'; } };
const y = { toString() { return 'key'; } };
o[x] = 'X';
o[y] = 'Y';
console.log(o); // { key: 'Y' }
```

---

\boxed{Handle type coercion, prototype pollution, NaN/-0/+0, symbol keys, iteration order, reference equality, WeakMap limits, enumeration pitfalls, serialization, and frozen objects; prefer Map/Object.create(null) for safe arbitrary-key hash tables.}

## Higher-order functions in JavaScript

A **higher-order function (HOF)** is any function that either:
1. **takes one or more functions as arguments**, and/or
2. **returns a function**.

Because JavaScript treats functions as first-class values, you can pass them around, store them, and compose them just like numbers or strings.

---

### Complete, runnable example

Save as `hof.js` and run with `node hof.js`.

```js
'use strict';

/* ---------- 1. Basic HOF: function in, function out ---------- */

// Wrap any function with logging behavior
const withLogging = (fn) => (...args) => {
  console.log(`[call] ${fn.name || 'anonymous'}(${args.join(', ')})`);
  const result = fn(...args);
  console.log(`[result] ${result}`);
  return result;
};

function multiply(a, b) {
  return a * b;
}

const loggedMultiply = withLogging(multiply);
loggedMultiply(3, 4); // logs call + result, returns 12


/* ---------- 2. Factory / closure (returns a function) ---------- */

const makeAdder = (x) => (y) => x + y;   // HOF: returns function
const add5 = makeAdder(5);
const add10 = makeAdder(10);

console.log(add5(3));   // 8
console.log(add10(3));  // 13


/* ---------- 3. Partial application ---------- */

const partial = (fn, ...preset) => (...rest) => fn(...preset, ...rest);

const greet = (salutation, name) => `${salutation}, ${name}!`;
const sayHello = partial(greet, 'Hello');
console.log(sayHello('Ada')); // "Hello, Ada!"


/* ---------- 4. Composition: pipe & compose ---------- */

const pipe = (...fns) => (x) => fns.reduce((acc, f) => f(acc), x);
const compose = (...fns) => (x) => fns.reduceRight((acc, f) => f(acc), x);

const numbers = [1, 2, 3, 4, 5, 6];

const isEven = (n) => n % 2 === 0;
const double = (n) => n * 2;
const sum = (arr) => arr.reduce((a, b) => a + b, 0);

// Pipeline: filter evens → double → sum
const pipeline = pipe(
  (arr) => arr.filter(isEven),
  (arr) => arr.map(double),
  sum
);

console.log(pipeline(numbers)); // evens [2,4,6] → [4,8,12] → 24


/* ---------- 5. Custom data HOF: retry wrapper ---------- */

const withRetry = (fn, attempts = 3) => async (...args) => {
  let lastError;
  for (let i = 1; i <= attempts; i++) {
    try {
      return await fn(...args);
    } catch (err) {
      lastError = err;
      console.warn(`attempt ${i} failed: ${err.message}`);
    }
  }
  throw lastError;
};

// Simulated flaky async function
let calls = 0;
const flakyFetch = async (id) => {
  calls++;
  if (calls < 3) throw new Error('network blip');
  return { id, data: 'ok' };
};

const robustFetch = withRetry(flakyFetch, 3);

(async () => {
  const result = await robustFetch(42);
  console.log('final:', result); // { id: 42, data: 'ok' }
})();


/* ---------- 6. Memoization (HOF returning cached function) ---------- */

const memoize = (fn) => {
  const cache = new Map();
  return (...args) => {
    const key = JSON.stringify(args);
    if (cache.has(key)) {
      console.log('cache hit:', key);
      return cache.get(key);
    }
    const value = fn(...args);
    cache.set(key, value);
    return value;
  };
};

const slowSquare = (n) => { /* imagine expensive work */ return n * n; };
const fastSquare = memoize(slowSquare);
console.log(fastSquare(9));  // computes
console.log(fastSquare(9));  // cache hit


/* ---------- 7. Event-style: HOF as callback factory ---------- */

const onClickFactory = (message) => () => console.log(message);
// In a browser you'd do: button.addEventListener('click', onClickFactory('hi'))
// Here we just invoke to demonstrate:
onClickFactory('button clicked')();
```

---

### What’s happening conceptually

| Pattern | Why it’s useful |
|---|---|
| `withLogging(fn)` | Cross-cutting concerns (logging, timing, auth) without touching original code. |
| `makeAdder(x)` | Factory functions + closures capture `x` per instance. |
| `partial(fn, ...args)` | Reuse a general function in a more specific context. |
| `pipe` / `compose` | Declarative data flow; reads like “do this, then this.” |
| `withRetry(fn)` | Wrap async operations with resilience. |
| `memoize(fn)` | Performance optimization transparent to callers. |

### Key rules of thumb

- **Don’t mutate inputs** in HOFs that transform data (`map`, `filter`) — return new values.
- **Keep returned functions pure** when possible; side effects belong at the edges.
- **Name your inner functions** (e.g., `fn.name`) so debugging/stack traces stay useful.
- **Avoid excessive nesting** — prefer `pipe` over deeply nested calls.

### Built-in HOFs you already use

```js
[1,2,3].map(x => x * 2);          // Array.prototype.map
[1,2,3].filter(x => x > 1);       // filter
[1,2,3].reduce((a,b) => a+b, 0);  // reduce
setTimeout(() => {...}, 1000);     // timer
arr.forEach(fn);                   // iteration
Promise.then(fn);                  // async chaining
```

All of these follow the same idea: **behavior is passed in as data**, which is what makes functional JavaScript flexible and expressive.

## Higher-Order Functions in JavaScript

A **higher-order function (HOF)** is any function that does at least one of:

1. **Takes another function as an argument**, or
2. **Returns a function as its result**.

JavaScript treats functions as **first-class values**, so you can pass them around like numbers or strings. HOFs are the main tool for abstraction, reuse, and declarative code.

---

### 1. The core idea

Instead of hard-coding *what* to do and *how* to do it in one place, a HOF separates them:

- The HOF handles the *mechanics* (looping, timing, caching, event wiring).
- The caller supplies the *behavior* as a function.

---

### 2. Basic syntax

#### Passing a function as an argument

```js
function repeat(n, action) {
  for (let i = 0; i < n; i++) {
    action(i);
  }
}

repeat(3, (i) => console.log(`step ${i}`));
// step 0
// step 1
// step 2
```

`repeat` is the HOF; `(i) => console.log(...)` is the callback.

#### Returning a function

```js
function multiplier(factor) {
  return (x) => x * factor;
}

const double = multiplier(2);
const triple = multiplier(3);

double(5); // 10
triple(5); // 15
```

`multiplier` is the HOF; it produces specialized functions.

---

### 3. Typical use cases

#### A. Array methods (map, filter, reduce)

These are the most common HOFs in everyday JS.

```js
const nums = [1, 2, 3, 4, 5];

const squares = nums.map(n => n * n);
const evens   = nums.filter(n => n % 2 === 0);
const sum     = nums.reduce((acc, n) => acc + n, 0);

console.log(squares); // [1, 4, 9, 16, 25]
console.log(evens);   // [2, 4]
console.log(sum);     // 15
```

#### B. Function composition

Build pipelines by combining small functions.

```js
const compose = (f, g) => (x) => f(g(x));
const pipe    = (f, g) => (x) => g(f(x));

const add1 = (x) => x + 1;
const times2 = (x) => x * 2;

const addThenDouble = pipe(add1, times2);
addThenDouble(4); // (4+1)*2 = 10
```

#### C. Partial application / currying

Pre-fill some arguments to create reusable variants.

```js
function partial(fn, ...presetArgs) {
  return (...restArgs) => fn(...presetArgs, ...restArgs);
}

function greet(greeting, name) {
  return `${greeting}, ${name}!`;
}

const sayHello = partial(greet, "Hello");
sayHello("Alice"); // "Hello, Alice!"
```

#### D. Memoization (caching)

Wrap an expensive function to remember results.

```js
function memoize(fn) {
  const cache = new Map();
  return (...args) => {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const result = fn(...args);
    cache.set(key, result);
    return result;
  };
}

const slowSquare = (n) => {
  console.log("computing");
  return n * n;
};

const fastSquare = memoize(slowSquare);
fastSquare(4); // computing -> 16
fastSquare(4); // (no log) -> 16
```

#### E. “Once” wrapper

Ensure a function runs only the first time.

```js
function once(fn) {
  let called = false;
  let result;
  return (...args) => {
    if (!called) {
      called = true;
      result = fn(...args);
    }
    return result;
  };
}

const init = once(() => {
  console.log("initialized");
  return 42;
});

init(); // initialized -> 42
init(); // -> 42 (no log)
```

#### F. Event handlers / callbacks

DOM APIs and Node APIs are built on HOFs.

```js
button.addEventListener("click", (event) => {
  console.log("clicked", event.target);
});

setTimeout(() => console.log("later"), 1000);
```

---

### 4. A small, realistic example: retry logic

This combines several ideas—taking a function, returning a function, and using closures.

```js
function withRetry(fn, retries = 3, delayMs = 100) {
  return async (...args) => {
    let lastError;
    for (let attempt = 1; attempt <= retries; attempt++) {
      try {
        return await fn(...args);
      } catch (err) {
        lastError = err;
        if (attempt < retries) {
          await new Promise(r => setTimeout(r, delayMs));
        }
      }
    }
    throw lastError;
  };
}

const fetchUser = withRetry(async (id) => {
  const res = await fetch(`/api/users/${id}`);
  if (!res.ok) throw new Error("not ok");
  return res.json();
});

fetchUser(123).then(console.log).catch(console.error);
```

---

### 5. Key takeaways

- **HOF = function that accepts/returns functions.**
- They enable **abstraction**: separate “how to iterate/cache/retry” from “what to do.”
- Common HOFs: `map`, `filter`, `reduce`, `setTimeout`, `addEventListener`, plus your own wrappers like `memoize`, `once`, `partial`.
- Use them to keep code **declarative, reusable, and composable**.

If you want, I can go deeper into a specific area—e.g., implementing your own `map`/`reduce`, async HOFs, or HOFs in React (hooks, higher-order components).

## Mistake: passing a function whose parameter list doesn’t match the callback contract

```js
const strings = ['1', '2', '3', '10'];

// Looks innocent: "parse each string to a number"
const numbers = strings.map(parseInt);

console.log(numbers);
// => [1, NaN, NaN, 3]   (not [1, 2, 3, 10])
```

### Corrected version

```js
const strings = ['1', '2', '3', '10'];

const numbers = strings.map(s => parseInt(s, 10));

console.log(numbers);
// => [1, 2, 3, 10]
```

### What was wrong and why

`Array.prototype.map` calls its callback with **three arguments**:

1. the current element
2. the current index
3. the array itself

So for the call above, `map` effectively does something like:

```js
parseInt('1', 0, strings);   // radix 0  -> 1
parseInt('2', 1, strings);   // radix 1  -> NaN
parseInt('3', 2, strings);   // radix 2  -> NaN  ('3' isn't valid base-2)
parseInt('10', 3, strings);  // radix 3  -> 3
```

`parseInt(string, radix)` happily accepts that second argument as the radix, so the index leaks into the parsing logic. The bug is not in `parseInt` itself; it’s a **callback-signature mismatch** introduced by treating a multi-argument function as a unary callback.

The fix is to introduce a wrapper that explicitly takes only the value and forwards it with the intended radix:

```js
strings.map(s => parseInt(s, 10));
```

This is a general HOF pitfall: **when you pass a function reference as a callback, you inherit whatever arguments the higher-order function decides to pass.** If the callee’s parameter order/meaning doesn’t match, you get surprising behavior.

---

### Another common HOF pitfall: losing `this`

```js
const user = {
  name: 'Alice',
  greetLater() {
    setTimeout(this.greet, 100); // `this` is lost
  },
  greet() {
    console.log(`Hi, I'm ${this.name}`);
  }
};

user.greetLater(); // "Hi, I'm undefined" (or throws in strict mode)
```

**Corrected:**

```js
greetLater() {
  setTimeout(() => this.greet(), 100); // lexical `this`
}
// or: setTimeout(this.greet.bind(this), 100);
```

**Why:** passing `this.greet` detaches the method from its object. When the timer invokes it, `this` is determined by the call site, not by where the method was defined. An arrow function (or `.bind`) preserves the intended receiver.

# Common pitfalls with higher-order functions in JavaScript

Higher-order functions (HOFs) such as `map`, `filter`, `reduce`, `forEach`, `sort`, and functions that return functions are powerful, but most bugs come from **hidden context, mutation, async timing, and accidental `undefined` returns**.

---

## 1. Losing `this` when passing a method as a callback

Passing `obj.method` directly strips its receiver.

```js
const user = {
  name: "Ada",
  format(name) {
    return `${this.name}: ${name}`;
  },
  greetNames(names) {
    // `this.format` is passed as a plain function
    return names.map(this.format);
  }
};

user.greetNames(["Grace", "Linus"]);
// TypeError: Cannot read properties of undefined (reading 'name')
```

**Fix:** wrap in an arrow function or bind.

```js
return names.map(name => this.format(name));
// or names.map(this.format.bind(this));
```

---

## 2. Forgetting to `return` inside a block-bodied arrow function

With curly braces, `map`/`filter` callbacks do **not** implicitly return.

```js
const doubled = [1, 2, 3].map(n => {
  n * 2; // no return
});

console.log(doubled); // [undefined, undefined, undefined]
```

**Fix:** either use an expression body or add `return`.

```js
const doubled = [1, 2, 3].map(n => n * 2);
```

---

## 3. Mutating the original array or objects

HOFs often *look* pure, but callbacks can mutate shared data.

```js
const users = [{ score: 1 }, { score: 2 }];

const boosted = users.map(user => {
  user.score *= 2; // mutates original object
  return user;
});

console.log(users);   // [{score:2},{score:4}]  (unexpected)
console.log(boosted); // same references
```

**Fix:** create new objects.

```js
const boosted = users.map(user => ({
  ...user,
  score: user.score * 2
}));
```

---

## 4. Stale closures over loop variables

Classic closure trap, often hidden inside HOF-generated callbacks.

```js
const callbacks = [];

for (var i = 0; i < 3; i++) {
  callbacks.push(() => i);
}

console.log(callbacks.map(fn => fn())); // [3, 3, 3]
```

**Fix:** use `let`, or capture the value in a parameter.

```js
for (let i = 0; i < 3; i++) {
  callbacks.push(() => i);
}
```

A subtler version happens with `setTimeout`:

```js
[1, 2, 3].forEach((n, i) => {
  setTimeout(() => console.log("index", i), 10); // safe: i is a parameter
});
```

---

## 5. Using `forEach` with `async` callbacks

`forEach` does **not** await promises and returns `undefined`.

```js
async function delay(ms) {
  return new Promise(r => setTimeout(r, ms));
}

[1, 2, 3].forEach(async n => {
  await delay(10);
  console.log("done", n);
});

console.log("all scheduled"); // prints before async work finishes
```

**Fix:** use `for...of` for sequential work, or `Promise.all` + `map` for parallel work.

```js
await Promise.all([1, 2, 3].map(async n => {
  await delay(10);
  console.log("done", n);
}));
```

---

## 6. `map(async fn)` returns an array of promises

```js
const urls = ["/a", "/b"];

const results = urls.map(async url => fetch(url));
console.log(results); // [Promise, Promise]
```

**Fix:**

```js
const results = await Promise.all(urls.map(url => fetch(url)));
```

---

## 7. `reduce` on an empty array without an initial value

```js
const total = [].reduce((acc, n) => acc + n);
// TypeError: Reduce of empty array with no initial value
```

**Fix:** always provide an initial value when the array may be empty.

```js
const total = [].reduce((acc, n) => acc + n, 0);
```

---

## 8. Mutating or losing the accumulator in `reduce`

`Array.prototype.push` returns the new length, not the array.

```js
const items = [{ id: 1 }, { id: 2 }];

const grouped = items.reduce((acc, item) => {
  acc.push(item); // returns 1, then 2, not acc
  return acc;     // must explicitly return acc
}, []);

console.log(grouped); // [{id:1},{id:2}]
```

A broken version:

```js
const bad = items.reduce((acc, item) => acc.push(item), []);
// acc becomes 1, then push fails because 1 has no push
```

**Fix:** always return the accumulator.

```js
const grouped = items.reduce((acc, item) => {
  acc.push(item);
  return acc;
}, []);
```

Or prefer immutable updates:

```js
const grouped = items.reduce((acc, item) => [...acc, item], []);
```

---

## 9. Incorrect `sort` comparator

`sort` expects a number, not a boolean.

```js
const nums = [10, 2, 30];
nums.sort((a, b) => a > b);
console.log(nums); // often [10, 2, 30] or platform-dependent
```

**Fix:** return a subtraction or `Math.sign`.

```js
nums.sort((a, b) => a - b); // [2, 10, 30]
```

Also note: `sort` **mutates** the original array. If you need immutability:

```js
const sorted = [...nums].sort((a, b) => a - b);
```

---

## 10. Relying on sparse-array behavior

`map`, `filter`, and `forEach` skip holes in sparse arrays.

```js
const arr = [1, , 3]; // hole at index 1

const mapped = arr.map(x => x * 2);
console.log(mapped); // [2, <1 empty item>, 6]

arr.forEach((x, i) => console.log(i, x));
// only 0 and 2 are visited
```

If holes matter, normalize first:

```js
const dense = Array.from(arr, x => x ?? 0);
```

---

## 11. Using `find` / `findIndex` without handling “not found”

```js
const users = [{ id: 1 }, { id: 2 }];
const user = users.find(u => u.id === 99);

console.log(user.name); // TypeError: Cannot read properties of undefined
```

**Fix:**

```js
const user = users.find(u => u.id === 99);
if (!user) throw new Error("User not found");
```

For `findIndex`, remember `-1` means not found:

```js
const index = users.findIndex(u => u.id === 99);
if (index === -1) { /* handle */ }
```

---

## 12. Performance pitfalls from chaining HOFs

Each HOF creates a new intermediate array.

```js
const result = data
  .filter(x => x.active)
  .map(x => x.value)
  .filter(x => x > 10)
  .map(x => x * 2);
```

For large datasets, this allocates multiple arrays and traverses multiple times.

**Fix:** combine logic, or use a single `reduce`, or a plain loop for hot paths.

```js
const result = data.reduce((acc, x) => {
  if (x.active && x.value > 10) acc.push(x.value * 2);
  return acc;
}, []);
```

---

## 13. Mutation during iteration

Mutating an array while `map`/`filter`/`forEach` runs can skip or double-process elements.

```js
const arr = [1, 2, 3, 4];

arr.forEach((x, i) => {
  if (x % 2 === 0) arr.splice(i, 1);
});

console.log(arr); // [1, 3, 4] (4 was skipped)
```

**Fix:** build a new array instead of mutating during traversal.

```js
const oddOnly = arr.filter(x => x % 2 !== 0);
```

---

## 14. HOFs returned from factories capture stale state

When a factory returns a function, beware of closure timing and shared mutable state.

```js
function makeCounter(start = 0) {
  let count = start;
  return {
    inc: () => ++count,
    get: () => count
  };
}

const a = makeCounter();
const b = makeCounter();

a.inc();
console.log(a.get(), b.get()); // 1 0 (good, separate scopes)
```

But accidental shared state can happen:

```js
const state = { count: 0 };

function makeInc() {
  return () => ++state.count; // all instances share state
}

const incA = makeInc();
const incB = makeInc();
incA();
console.log(incB()); // 2, not 1
```

**Fix:** keep state inside the factory closure unless sharing is intentional.

---

## 15. `this` inside callbacks passed to HOFs

Traditional function callbacks have their own `this`.

```js
const obj = {
  threshold: 5,
  filterBig(nums) {
    return nums.filter(function(n) {
      return n > this.threshold; // this is undefined in strict mode
    });
  }
};
```

**Fix:** arrow function or use the `thisArg` parameter.

```js
return nums.filter(n => n > this.threshold);

// or
return nums.filter(function(n) {
  return n > this.threshold;
}, this);
```

---

## Quick checklist

- Does the callback **return** the right value?
- Does it **mutate** input data?
- Does it preserve `this`?
- Is the operation **sync or async**?
- Did you handle empty arrays in `reduce`?
- Does `sort` mutate data and use a numeric comparator?
- Are you creating unnecessary intermediate arrays?
- Are closures capturing the intended variable, not a stale one?

If you want, I can also provide a compact “HOF bug checklist” or refactor examples for `reduce`, `async map`, and closure bugs.

## Exercise

**Task:** Build a tiny functional utility kit and use it to process a product catalog.

Given this data:

```js
const products = [
  { id: 1, name: "Laptop",   category: "electronics", price: 1200, stock: 5 },
  { id: 2, name: "Mouse",    category: "electronics", price: 25,   stock: 0 },
  { id: 3, name: "Desk",     category: "furniture",    price: 300,  stock: 2 },
  { id: 4, name: "Monitor",  category: "electronics",  price: 400,  stock: 3 },
  { id: 5, name: "Chair",    category: "furniture",    price: 150,  stock: 4 },
];
```

Implement these **higher-order functions** (functions that take/return functions):

1. `createFilter(predicate)` → returns `(arr) => arr.filter(predicate)`
2. `createMapper(transform)` → returns `(arr) => arr.map(transform)`
3. `compose(...fns)` → right-to-left composition
4. `pipe(...fns)` → left-to-right composition
5. `memoize(fn)` → caches results keyed by serialized arguments
6. `curry(fn)` → converts a multi-arg function into nested unary functions

Then use them to compute: **the total value (price × stock) of in-stock electronics**, and **a memoized, piped formatter** that turns a number into a currency string.

---

## Step-by-step solution

### Step 1 — `createFilter` / `createMapper`

These are the simplest HOFs: they *manufacture* a function configured by an argument.

```js
const createFilter = (predicate) => (arr) => arr.filter(predicate);
const createMapper  = (transform)  => (arr) => arr.map(transform);
```

Why HOF? The predicate/transform is captured in closure, so the returned function is reusable and specialized.

### Step 2 — `compose` and `pipe`

Composition lets us build pipelines from small, testable pieces.

```js
const compose = (...fns) => (x) =>
  fns.reduceRight((acc, fn) => fn(acc), x);

const pipe = (...fns) => (x) =>
  fns.reduce((acc, fn) => fn(acc), x);
```

- `reduceRight` applies the **last** function first → right-to-left.
- `reduce` applies the **first** function first → left-to-right.

### Step 3 — `memoize`

Cache by a stable key. `JSON.stringify(args)` is a pragmatic key for pure functions.

```js
const memoize = (fn) => {
  const cache = new Map();
  return (...args) => {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    const result = fn(...args);
    cache.set(key, result);
    return result;
  };
};
```

Caveats: only safe for **pure** functions; `JSON.stringify` can't distinguish some values (e.g. `undefined`, functions, `NaN`). For production, consider a `WeakMap` or a hashing library.

### Step 4 — `curry`

Convert `f(a, b, c)` into `f(a)(b)(c)`. We collect args until we have enough.

```js
const curry = (fn) => {
  const arity = fn.length;
  const curried = (...args) =>
    args.length >= arity
      ? fn(...args)
      : (...more) => curried(...args, ...more);
  return curried;
};
```

`fn.length` gives the declared parameter count, so partial application works naturally.

### Step 5 — Apply to the catalog

```js
const isInStock     = (p) => p.stock > 0;
const isElectronics = (p) => p.category === "electronics";
const valueOf       = (p) => p.price * p.stock;

const inStockElectronics = pipe(
  createFilter((p) => isInStock(p) && isElectronics(p)),
  createMapper(valueOf),
);

const totalValue = (arr) => arr.reduce((s, v) => s + v, 0);

const computeTotal = pipe(inStockElectronics, totalValue);

console.log(computeTotal(products)); // 1200*5 + 400*3 = 6000 + 1200 = 7200
```

### Step 6 — Memoized currency formatter (piped)

```js
const formatCurrency = (n) => `$${n.toFixed(2)}`;
const addTax = (rate) => (n) => n * (1 + rate);

const pricePipeline = pipe(
  addTax(0.08),          // +8% tax
  formatCurrency
);

const memoizedFormat = memoize(pricePipeline);

console.log(memoizedFormat(100)); // "$108.00"
console.log(memoizedFormat(100)); // cached → "$108.00"
```

Notice `addTax` is itself a HOF: it returns a function configured by `rate`. This is the essence of higher-order programming — functions as data.

### Step 7 — Curry in action

```js
const multiply = curry((a, b) => a * b);
const double   = multiply(2);
console.log(double(7)); // 14

const greet = curry((greeting, name) => `${greeting}, ${name}!`);
const sayHi = greet("Hi");
console.log(sayHi("Ada")); // "Hi, Ada!"
```

